(window.GIM_TS=window.GIM_TS||{})["Sanhedrin.1"]={"from":24,"a":[["\u0003בטלו דיני קנסות מישראל,\u0004 שלא היו יכולים לדון עוד דינים אלה בהיעדר חכמים סמוכים. \u0003שפעם אחת גזרה מלכות הרשעה\u0004 (רומי) \u0003שמד על ישראל\u0004 לבטל את שרשרת הסמיכה ואת סמכותם של חכמי ארץ ישראל, ואמרו \u0003שכל הסומך\u0004 — \u0003יהרג, וכל הנסמך\u0004 — \u0003יהרג, ו\u0004עוד קבעו ש\u0003עיר שסומכין בה\u0004 — \u0003תיחרב. ו\u0004אף סימוני \u0003תחומין שסומכין בהן\u0004 — \u0003יעקרו,\u0004 כדי להרתיע את הסומכים והנסמכים מתוך חשש לשלומם של בני מקומות אחרים.","\u0003מה עשה יהודה בן בבא? הלך וישב לו בין שני הרים גדולים, ובין שתי עיירות גדולות, ובין שני תחומי שבת,\u0004 כלומר, במקום שומם, שלא יוכלו לומר שהוא שייך לתחומה של עיירה מסויימת ולא יענישו את בני העיירה, \u0003בין אושא לשפרעם, וסמך שם חמשה זקנים. ואלו הן: ר' מאיר, ור' יהודה, ור' שמעון, ור' יוסי, ור' אלעזר בן שמוע. ר' אויא מוסיף\u0004 שהיה שם \u0003אף ר' נחמיה,\u0004 בין הנסמכים.","\u0003כיון שהכירו אויביהם בהן,\u0004 שנודע להם הדבר שסומכים שם, \u0003אמר להן\u0004 ר' יהודה בן בבא לחכמים: \u0003בניי, רוצו\u0004 וברחו מכאן. \u0003אמרו לו: רבי, מה תהא עליך\u0004 שאתה זקן ואינך יכול לרוץ? \u0003אמר להן:\u0004 הרי בין כה וכה \u0003הריני מוטל לפניהם כאבן שאין לה הופכים,\u0004 שבוודאי לא אוכל להימלט גם אם תעזרוני, ואם לא תמלטו לבדכם גם אתם תהרגו. \u0003אמרו: לא זזו\u0004 האויבים \u0003משם עד שנעצו בו שלש מאות לונביאות\u0004 (חניתות) \u0003של ברזל ועשאוהו ככברה.\u0004 ודרך אגב אפשר ללמוד ממעשה זה שחכם אחד בלבד יכול לסמוך!","ודוחים: \u0003ר' יהודה בן בבא אחריני הוו בהדיה\u0004 \u0005[\u0006חכמים \u0005אחרים היו עמו],\u0006 שצרפם כדי לסמוך את התלמידים, \u0003והאי\u0004 \u0005[וזה]\u0006 ש\u0003לא חשיב להו\u0004 \u0005[חשב,\u0006 מנה, \u0005אותם],\u0006 — \u0003משום כבודו\u0004 של \u0003ר' יהודה בן בבא\u0004 שהיה הגדול שבהם, והשאר רק נספחו לו כדי להוות בית דין. ועוד שואלים בקשר למעשה זה: \u0003ור' מאיר,\u0004 האם \u0003ר' יהודה בן בבא סמכיה\u0004 \u0005[סמכו]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר רבה בר בר חנה אמר ר' יוחנן: כל האומר ר' מאיר לא סמכו ר' עקיבא אינו אלא טועה,\u0004 ואם כן לשם מה היה צריך שיסמכוהו שנית? ומשיבים: \u0003סמכיה\u0004 \u0005[סמכו]\u0006 \u0003ר' עקיבא ולא קיבלו\u0004 הבריות את המינוי, שהיה ר' מאיר עדיין צעיר מאד, והיה הדבר נראה תמוה בעיני הבריות, ולאחר זמן \u0003סמכיה\u0004 \u0005[סמכו]\u0006 \u0003ר' יהודה בן בבא\u0004 — \u0003וקיבלו.\u0004","\u0003אמר ר' יהושע בן לוי: אין סמיכה בחוצה לארץ.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אין סמיכה\"? אילימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003לא דייני\u0004 \u0005[דנים]\u0006 \u0003דיני קנסות כלל בחוצה לארץ, והא תנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003סנהדרין\u0004 ושלטון הסנהדרין \u0003נוהגת בין בארץ ובין בחוצה לארץ!\u0004 \u0003אלא\u0004 הכוונה היא ש\u0003לא סמכינן\u0004 \u0005[סומכים אנו]\u0006 חכמים \u0003בחוצה לארץ\u0004 אלא בארץ ישראל בלבד.","ומעתה מבררים כמה פרטים בענין סמיכה, \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו \u0005]\u0006 כי אם היו ה\u0003סומכין\u0004 נמצאים \u0003בחוצה לארץ ונסמכין בארץ\u0004 — \u0003הא אמרינן\u0004 \u0005[הרי\u0006 כבר \u0005אמרנו]\u0006 ש\u0003לא,\u0004 שאין סמיכה, \u0003אלא\u0004 בארץ ישראל בלבד. ואולם אם ה\u0003סומכין בארץ ו\u0004ה\u0003נסמכין\u0004 נמצאים \u0003בחוצה לארץ, מאי\u0004 \u0005[מה]\u0006 יהא הדין? האם יכולים הם למנותם מרחוק, בחוצה לארץ, או לא?","ומשיבים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר מן העובדה ש\u0003ר' יוחנן הוה\u0004 \u0005[היה]\u0006 \u0003מצטער\u0004 (משתדל) \u0003עליה\u0004 \u0005[עליו]\u0006 על \u0003רב שמן בר אבא\u0004 ש\u0003לא הוה גבייהו\u0004 \u0005[היה אתם]\u0006 בזמן שקיבלו את הסכמת הנשיא \u0003דליסמכיה\u0004 \u0005[\u0006לצורך זה \u0005שיסמכוהו],\u0006 וכן \u0003ר' שמעון בן זירוד וחד דעימיה\u0004 \u0005[ואחד שעמו]\u0006 שהיה חבירו, \u0003ומנו\u0004 \u0005[ומי הוא]?\u0006 — \u0003ר' יונתן בן עכמאי. ואמרי לה\u0004 \u0005[ויש אומרים אותה]\u0006 בגירסא שונה: \u0003ר' יונתן בן עכמאי וחד דעימיה\u0004 \u0005[ואחד שעמו],\u0006 \u0003ומנו\u0004 \u0005[ומי הוא]?\u0006 — \u0003ר' שמעון בן זירוד,\u0004 שאף על פי שהיו חברים שווים במדרגה, \u0003חד דהוה גבייהו\u0004 \u0005[אחד שהיה עמם]\u0006 בארץ ישראל — \u0003סמכוהו, וחד\u0004 \u0005[ואחד]\u0006 ש\u0003לא הוה גבייהו\u0004 \u0005[היה עמם]\u0006 — \u0003לא סמכוהו,\u0004 ומכאן שאין לסמוך אלא בתוך הארץ.","כיון שדברנו בענין הסמיכה מביאים סיפורים נוספים בנושא זה. \u0003ר' חנינא ור' הושעיא הוה קא משתקיד\u0004 \u0005[היה משתדל]\u0006 \u0003ר' יוחנן למיסמכינהו\u0004 \u0005[לסמוך אותם],\u0006 שחכמים וצדיקים היו, \u0003לא הוה מסתייעא מילתא\u0004 \u0005[היה מסתייע,\u0006 מצליח בידו \u0005הדבר],\u0006 \u0003הוה קא מצטער טובא\u0004 \u0005[\u0006ו\u0005היה מצטער ביותר],\u0006 שכל פעם היה קורה מאורע אחר שהיה גורם שלא יוכל לסמכם. \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003לא נצטער מר דאנן\u0004 \u0005[אל יצטער אדוני, כי אנחנו]\u0006 \u0003מ\u0004צאצאי \u0003בית עלי קאתינן\u0004 \u0005[אנו\u0006 \u0005באים],\u0006","ש\u0003אמר ר' שמואל בר נחמן אמר ר' יונתן: מניין שאין\u0004 חכמים \u0003נסמכין לבית עלי, שנאמר\u0004 בקללה שנאמרה לבית עלי: \u0003\"\u0004ו\u0003לא יהיה זקן בביתך כל הימים\"\u0004 (שמואל א' ב, לב), ונברר: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"זקן\"\u0004 בפסוק זה? \u0003אילימא\u0004 \u0005[אם תאמר]:\u0006 \u0003זקן ממש,\u0004 כלומר, אדם בא בימים, \u0003והכתיב\u0004 \u0005[והרי\u0006 כבר \u0005נאמר]\u0006 דבר זה \u0003\"\u0004ו\u0003כל מרבית ביתך ימותו אנשים\"\u0004 (שמואל א' ב, לג), משמע שימותו בבחרותם ולא יגיעו לזקנה, \u0003אלא\u0004 \"זקן\" זה הוא תואר כבוד לחכם, ומשמעו — \u0003סמיכה,\u0004 שנתקללו בני בית עלי שלא יהיו ביניהם חכמים סמוכים.","מסופר: \u0003ר' זירא הוה מיטמר למיסמכיה\u0004 \u0005[היה מתחבא\u0006 כדי להימנע מהאפשרות \u0005שיסמכו אותו],\u0006 וטעמו היה על פי מה ש\u0003אמר ר' אלעזר: לעולם הוי קבל וקיים\u0004 \u0005[היה אפל ו\u0006תישאר \u0005קיים],\u0006 כלומר, ככל שאתה צנוע יותר ואינך ידוע תאריך ימים. \u0003כיון\u0004 ש\u0003שמעה להא\u0004 \u0005[לאותה\u0006 שמועה\u0005]\u0006 ש\u0003אמר ר' אלעזר: אין אדם עולה לגדולה אלא אם כן מוחלין לו על כל עונותיו,\u0004 ראה שיש בגדולה גם מחילת עוונות, \u0003אמצי ליה אנפשיה\u0004 \u0005[המציא לו,\u0006 לנשיא, \u0005את עצמו]\u0006 שיוכלו לסמכו.","מסופר, \u0003כי סמכוה\u0004 \u0005[כאשר סמכו]\u0006 את \u0003ר' זירא שרו ליה\u0004 \u0005[לו]\u0006 החכמים המצויים שם \u0003הכי\u0004 \u0005[כך]:\u0006 \u0003\"לא כחל\u0004 (צבע כחול לעינים), \u0003ולא שרק\u0004 (צבע אדום ללחיים), \u0003ולא פירכוס\u0004 (ליפות השיער), שהוא כאשה שאיננה מקשטת עצמה בשום אמצעי חיצוני, \u0003ו\u0004בכל זאת \u0003יעלת חן.\u0004 ואגב מסופר, \u0003כי סמכוה\u0004 \u0005[כאשר סמכו]\u0006 את \u0003ר' אמי ו\u0004את \u0003ר' אסי, שרו להו הכי\u0004 \u0005[להם\u0006 החכמים \u0005כך]:\u0006 \u0003כל מן דין, כל מן דין סמוכו לנא\u0004 \u0005[כל כמו אלה, כל כמו אלה, סמכו לנו],\u0006 שהם הם הדוגמא לראויים לסמיכה. \u0003לא תסמכו לנא\u0004 \u0005[אל תסמכו לנו]\u0006 \u0003לא מסרמיטין\u0004 \u0005[מן הסמרטוטים]\u0006 \u0003ולא מסרמיסין\u0004 \u0005[מן המסרסין].\u0006 \u0003ואמרי לה\u0004 \u0005[ויש אומרים שאמרו]:\u0006 אל תסמכו לנו \u0003לא מחמיסין\u0004 \u0005[מן החמסנים]\u0006 \u0003ולא מטורמיסין\u0004 \u0005[מן הדורסנים],\u0006 וכיון שהוזכרו השירים שחוברו לכבודם של חכמים, מספרים גם כי","\u0003ר' אבהו כי הוה אתי ממתיבתא לבי קיסר\u0004 \u0005[כאשר היה בא מן הישיבה אל בית הקיסר],\u0006 \u0003נפקי מטרוניתא דבי קיסר ומשריין ליה\u0004 \u0005[היו יוצאות גבירות בית הקיסר ושרות לפניו]:\u0006 \u0003\"רבה דעמיה, מדברנא דאומתיה, בוצינא דנהורא, בריך מתייך לשלם\"\u0004 \u0005[\"גדול עמו, מנהיג אומתו, נר המאור, ברוך בואך לשלום\"]!\u0006","שנינו במשנה כי \u0003עריפת עגלה בשלשה\u0004 חכמים. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא על הנאמר בדין עגלה ערופה: \u0003\"ויצאו זקניך ושפטיך\u0004 ומדדו אל הערים אשר סביבות החלל\u0003\"\u0004 (דברים כא, ב), \u0003\"זקניך\"\u0004 לשון רבים, ומיעוט רבים — הרי \u0003שנים. \"שפטיך\"\u0004 רבים — הרי \u0003שנים, ואין\u0004 עושים \u0003בית דין שקול\u0004 — \u0003מוסיפין עליהן עוד אחד, הרי כאן חמשה,\u0004 אלו \u0003דברי ר' יהודה. ר' שמעון אומר: \"זקניך\"\u0004 — הרי \u0003שנים, ואין בית דין שקול\u0004 — \u0003מוסיפין עליהם עוד אחד, הרי כאן שלשה.\u0004","ושואלים: \u0003ור' שמעון, האי\u0004 \u0005[זה\u0006 שנאמר\u0005]\u0006 \u0003\"שפטיך\", מאי עביד ליה\u0004 \u0005[מה עושה\u0006 הוא \u0005בו],\u0006 כיצד מבין הוא אותו? ומשיבים: \"שופטיך\" \u0003ההוא מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 \u0003ל\u0004למד שיהו אלו מן ה\u0003מיוחדין שבשופטיך,\u0004 שלצורך זה מביאים מזקני סנהדרין הגדולה, ולא די בחכמים ממקום אחר. ושואלים: \u0003ור' יהודה,\u0004 מנין למד הוא דבר זה? ומסבירים: \u0003מ\"זקני\" \"זקניך\" נפקא\u0004 \u0005[יוצא],\u0006 שאילו היה כתוב רק \"זקני\" היה משמעו כל זקנים (חכמים), אולם כיון שנאמר \"זקניך\" כוונתו לזקנים המיוחדים לכל ישראל, והם חכמי הסנהדרין.","\u0003ור' שמעון\u0004 סבור כי לא די בכך, כי \u0003אי\u0004 \u0005[אם]\u0006 היה כתוב רק \u0003\"זקני\", הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי מדובר ב\u0003זקני השוק,\u0004 כלומר, סתם אנשים זקנים, לכן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"זקניך\",\u0004 ללמד שדרושים חכמים המפורסמים בישראל, \u0003ואי כתיב\u0004 \u0005[ואילו נאמר]\u0006 רק \u0003\"זקניך\", הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 הכוונה לזקנים מ\u0003סנהדרי קטנה,\u0004 לכן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"ושפטיך\",\u0004 ללמדנו \u0003ממיוחדין שבשופטיך.\u0004 ושואלים: \u0003ור' יהודה,\u0004 מה משיב הוא לטענה זו? ומשיבים: \u0003גמר\u0004 \u0005[למד]\u0006 בגזירה שווה \u0003\"זקני\" \"זקני\" מ\u0004דין סמיכה, שנאמר שם \u0003\"וסמכו זקני העדה את ידיהם\"\u0004 (ויקרא ד, טו), \u0003מה להלן\u0004 בענין סמיכה על חטאת הציבור הכוונה \u0003מיוחדין שבעדה\u0004 מסנהדרי גדולה, \u0003אף כאן מיוחדין שבזקניך.\u0004","ושואלים: \u0003אי יליף\u0004 \u0005[אם לומד]\u0006 הוא גזירה שווה, \u0003לילף כולה מהתם\u0004 \u0005[שילמד\u0006 את \u0005הכל משם],\u0006 גם את מספר הדיינים וגם את דרגתם (שהרי לשיטתו החמישה הם מזקני סנהדרי גדולה), ואם כן \u0003\"זקניך ושפטיך\" למה לי? אלא\u0004 ודאי לא קיבל גזירה שווה זו, אלא לומד הלכה זו מ\u0003וי\"ו\u0004 היתירה של \u0003\"ושפטיך\",\u0004 שלדעתו \u0003למניינא\u0004 \u0005[למנין\u0006 בא\u0005],\u0006 שמ\"שופטיך\" עצמו למדים אנו שצריכים שיהיו מסנהדרי גדולה, ומן הוי\"ו היתירה למדים שבא הדבר להוסיף עוד שנים על מנין הזקנים. \u0003ור' שמעון:\u0004 את ייתור האות \u0003וי\"ו לא דריש\u0004 \u0005[אינו דורש].\u0006","ומקשים עוד: \u0003אלא מעתה,\u0004 אם דורשים אנו לשון ריבוי למספר הדיינים, הרי בהמשך הכתוב נאמר \u0003\"ויצאו\"\u0004 — הרי עוד \u0003שנים, \"ומדדו\"\u0004 — עוד \u0003שנים,\u0004 אם כן \u0003לר' יהודה הרי תשעה\u0004 דיינים, ו\u0003לר' שמעון שבעה!\u0004 ומשיבים: \u0003ההוא מיבעי ליה לכדתניא\u0004 \u0005[\u0006דבר \u0005זה נצרך לו לכפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003\"ויצאו\",\u0004 יש בכך הדגשה לומר: \u0003הן ולא שלוחן,\u0004 שאין החכמים יכולים שיעשה אחר את העבודה הזאת במקומם, \u0003\"ומדדו\"\u0004 — שמדידה זו מצוה לעצמה היא, \u0003שאפילו נמצא\u0004 החלל"],["\u0003בעליל\u0004 (בגלוי ובבירור) בסמוך \u0003לעיר, צריך לעסוק במדידה.\u0004","ומעירים: \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 ש\u0003לא כי האי תנא\u0004 \u0005[כ\u0006שיטת \u0005תנא זה],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' אליעזר בן יעקב אומר\u0004 על מה שנאמר \u0003\"ויצאו זקניך ושפטיך\" \"זקניך\"\u0004 — \u0003זו סנהדרין, \"ושפטיך\"\u0004 — \u0003זה מלך וכהן גדול.\u0004 ומנין שהם קרויים \"שופטיך\"? \u0003מלך\u0004 קרוי \"שופט\" — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"מלך במשפט יעמיד ארץ\"\u0004 (משלי כט, ד). \u0003כהן גדול\u0004 נקרא \"שופט\" — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"ובאת אל הכהנים הלוים ואל השפט\u0004 אשר יהיה בימים ההם\u0003\"\u0004 (דברים יז, ט), המרמז על הכהן הגדול.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו: \u0003ר' אליעזר בן יעקב בחדא פליג\u0004 \u0005[ב\u0006ענין \u0005אחד\u0006 בלבד \u0005חלק]\u0006 על משנתנו, \u0003או בתרתי פליג\u0004 \u0005[בשני\u0006 עניינים \u0005חלק]?\u0006 כלומר, האם \u0003במלך וכהן גדול\u0004 בלבד \u0003פליג\u0004 \u0005[חלק],\u0006 שהוא מוסיף את אלה, \u0003אבל בסנהדרי\u0004 אין לו שיטה מיוחדת אלא הוא סובר \u0003אי\u0004 \u0005[או]\u0006 \u0003כ\u0004שיטת \u0003ר' יהודה, אי\u0004 \u0005[או]\u0006 \u0003כ\u0004שיטת \u0003ר' שמעון, או דילמא\u0004 \u0005[שמא]\u0006 \u0003ב\u0004ענין ה\u0003סנהדרי נמי פליג\u0004 \u0005[גם כן חלק],\u0006 ש\u0003אמר: כולה\u0004 \u0005[\u0006את \u0005כל]\u0006 חברי ה\u0003סנהדרי בעינן\u0004 \u0005[צריכים אנו]?\u0006","\u0003אמר רב יוסף: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה שלמדנו בענין זקן ממרא, שהוא החכם המורה הלכה כנגד פסק דינם והכרעתם של אנשי הסנהדרי הגדולה. ואומרים כי אם \u0003מצאן\u0004 אותו זקן את אנשי הסנהדרין ב\u0003בית פגי,\u0004 מחוץ לירושלים, \u0003והמרה עליהן,\u0004 שלא קיבל את החלטתם, \u0003יכול תהא המראתו המראה\u0004 וייהרג אם ידרוש ברבים לעשות כשיטתו — \u0003תלמוד לומר: \"וקמת ועלית אל המקום\u0004 אשר יבחר ה' אלהיך בו\u0003\"\u0004 (דברים יז, ה), שלשם באים לקבל פסק הלכה, ושהוא מקום המשפט. \u0003מלמד שהמקום גורם\u0004 וסמכות הסנהדרין תלויה במידה מסויימת בהיותם במקום הקבוע להם, בלשכת הגזית הסמוכה למקדש. ויש לברר באותה ברייתא כיצד בדיוק היה הענין.","\u0003דנפוק\u0004 \u0005[שיצאו]\u0006 \u0003כמה\u0004 מחברי הסנהדרין? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שיצאו רק \u0003מקצתן\u0004 ועל דעת מקצתם חלק, אם כן אין כאן כל חידוש, \u0003דילמא הנך דאיכא גואי קיימי כוותיה\u0004 \u0005[שמא אותם שנמצאים בפנים\u0006 בלשכת הגזית והם הרוב \u0005סבורים כמותו],\u0006 ובודאי שאינו נעשה זקן ממרא על פי דעת המיעוט בלבד. \u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 \u0003דנפוק כולהו\u0004 \u0005[שיצאו כולם].\u0006 ומעתה נברר: \u0003למאי\u0004 \u0005[למה\u0006 יצאו\u0005]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שיצאו \u0003לדבר הרשות,\u0004 כלומר, שלא לצורך מצוה, \u0003מי מצו נפקי\u0004 \u0005[האם יכולים\u0006 הם \u0005לצאת]?\u0006 \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"שררך אגן הסהר אל יחסר המזג\"\u0004 (שיר השירים ז, ג), ורמז לסנהדרין היושבים כחצי גורן עגולה, כאגן הסהר, שלא יחסר המזג — שלא יחסרו מהם יותר משני שלישים כשיעור יין המזוג במים. \u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 שיצאו \u0003לדבר מצוה.\u0004","\u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר\u0006\u0005]?\u0006 \u0003לאו\u0004 \u0005[האם לא]\u0006 שיצאו \u0003למדידת עגלה\u0004 ערופה? \u0003ו\u0004שיטת \u0003ר' אליעזר בן יעקב היא,\u0004 ומכאן נלמד ש\u0003אמר: כולי\u0004 \u0005[\u0006את \u0005כל]\u0006 ה\u0003סנהדרי בעינן\u0004 \u0005[צריכים אנו\u0006 לכך\u0005].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: לא,\u0004 אין להוכיח מכאן, שמא מדובר כאן באופן מסווים ו\u0003כגון שיצאו להוסיף על העיר\u0004 ירושלים או \u0003על העזרות\u0004 שבמקדש. \u0003כדתנן\u0004 \u0005[כפי ששנינו\u0006 במשנה\u0005]:\u0006 \u0003אין מוסיפין על העיר ועל העזרות אלא בבית דין של שבעים ואחד.\u0004","\u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב יוסף,\u0004 שלענין זקן ממרא נאמר: \u0003מצאן\u0004 ב\u0003בית פאגי והמרה עליהן, כגון שיצאו למדידת עגלה, ולהוסיף על העיר ועל העזרות, יכול שתהא המראתו המראה\u0004 — \u0003תלמוד לומר \"וקמת ועלית אל המקום\", מלמד שהמקום גורם.\u0004 ולפי דרכנו למדנו שיש תנא הסבור שבמדידת עגלה צריכים כל חברי הסנהדרין להשתתף.","שנינו במשנה כי \u0003נטע רבעי ומעשר שני שאין דמיו ידועין\u0004 נפדה \u0003בשלשה.\u0004 \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006: \u0003איזהו מעשר שני שאין דמיו ידועין\u0004 ודורש בית דין מיוחד להעריכו — אלו הם \u0003פירות שהרקיבו ויין שהקרים\u0004 (שהתחיל להחמיץ) \u0003ומעות שהחלידו\u0004 ואינן עוברות לסוחר בשווין, ולכן יש צורך בהערכת מומחים. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא אחרת: \u0003מעשר שני שאין דמיו ידועין\u0004 — \u0003פודין אותו בשלשה לקוחות\u0004 (אנשים הבקיאים במסחר) \u0003אבל לא בשלשה\u0004 כלשהם \u0003שאין\u0004 הם \u0003לקוחות. אפילו גוי אחד מהן\u0004 מן הלקוחות יכול להשתתף בהערכה זו. ו\u0003אפילו אחד מהם\u0004 מן המעריכים הוא אחד ה\u0003בעלים.\u0004","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' ירמיה: שלשה ומטילין לתוך כיס אחד,\u0004 שהם שותפים בהוצאות ובהכנסות, \u0003מהו\u0004 הדין בכגון זה? האם נחשבים הם לענין זה כשלשה או כאחד? ומשיבים \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו: \u0003איש ושתי נשיו פודין מעשר שני שאין דמיו ידועין,\u0004 ומשמע ששלושה שותפים נחשבים כבית דין לענין זה. ודוחים: מכאן אין ראיה, \u0003דילמא\u0004 \u0005[שמא]\u0006 היה זה \u0003כגון רב פפא ו\u0004אשתו \u0003בת אבא סוראה\u0004 (בתו של אבא מסורא) שהיה לכל אחד מהם משק בית לחוד, ואם יש לאיש ולשתי נשיו לכל אחד חשבון הוצאות לעצמו ודאי שהם כשלושה לענין זה.","שנינו במשנה כי את \u0003ההקדשות\u0004 פודים \u0003בשלשה.\u0004 ומעירים: \u0003מתניתין דלא כי האי תנא\u0004 \u0005[משנתנו אינה כ\u0006שיטתו \u0005של תנא זה]\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' אליעזר בן יעקב אומר: אפילו\u0004 דבר פעוט כ\u0003צינורא\u0004 \u0005[\u0006כעין \u0005מזלג קטן]\u0006 \u0003של הקדש צריכה עשרה בני אדם לפדותה.\u0004","\u0003אמר ליה רב פפא לאביי: בשלמא\u0004 \u0005[נניח\u0006 לשיטת\u0005]\u0006 \u0003ר' אליעזר בן יעקב\u0004 דבריו מובנים \u0003כ\u0004שיטת \u0003שמואל. דאמר שמואל: עשרה \"כהנים\",\u0004 כלומר, עשר פעמים \"כהן\" \u0003כתובין בפרשה\u0004 זו של הקדשים ופדיית הקדשים (ויקרא פרק כז), ועל כל פעם שנזכר \"כהן\" אנו מחייבים שיהיה דיין שיבדוק פדיון זה. \u0003אלא לרבנן\u0004 \u0005[ל\u0006שיטת \u0005חכמים]\u0006 \u0003שלשה מנא להו\u0004 \u0005[מנין להם]?\u0006","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שבענין פדיון מטלטלין (או פדיון בהמה) \u0003דכתיב בהו\u0004 \u0005[שנאמר בהם]\u0006 רק \u0003שלשה\u0004 פעמים \"כהן\" (ויקרא יא–יב) אם כן בפדיון \u0003קרקעות דכתיב בהו\u0004 \u0005[שנאמר בהם]\u0006 רק \u0003ארבעה\u0004 פעמים \"כהן\" (ויקרא יד, יח, כג) \u0003תיסגי\u0004 \u0005[יהא די]\u0006 \u0003בארבעה\u0004 אנשים! \u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003הכי נמי\u0004 \u0005[כך הוא גם כן]\u0006 שבאמת די בארבעה, \u0003אלמה תנן\u0004 \u0005[מדוע שנינו]\u0006 ש\u0003הקרקעות\u0004 נפדים ב\u0003תשעה\u0004 אנשים \u0003ו\u0004עוד אחד \u0003כהן,\u0004 משמע שיש צורך בעשרה לפדיון קרקעות!","\u0003אלא מאי\u0004 \u0005[מה]\u0006 תאמר שקרקעות \u0003דמשלמי בהו\u0004 \u0005[שהושלם בהם]\u0006 מנין \u0003עשרה\u0004 \"כהנים\" הכתובים בפרשה ולכן צריכים עשרה, אם כן, \u0003הקדשות דמשלמי בהו שיתא\u0004 \u0005[שנשלמים בהם ששה]\u0006 \"כהנים\" המוזכרים שם \u0003ליבעו שיתא\u0004 \u0005[שיצטרכו ששה\u0006 אנשים\u0005]\u0006 לפדותם! ומעירים, אכן \u0003קשיא\u0004 \u0005[קשה]\u0006 הדבר.","שנינו במשנה כי \u0003הערכין\u0004 המטלטלין בשלושה. ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"ערכין המטלטלין\"?\u0004 שהרי ערכים הם רק סוג מיוחד של הקדשות שבהם נודבים רק ערכם של בני אדם, לפי סכומים קבועים האמורים במפורש בתורה (ויקרא א-ח), ומה הם איפוא \"ערכין המטלטלין\"? \u0003אמר רב גידל אמר רב:\u0004 הכוונה היא \u0003באומר\u0004 אותו אדם: \u0003ערך כלי זה עלי.\u0004 ויש להבינו כפי ש\u0003אמר רב גידל אמר רב\u0004 עצמו:"],["\u0003האומר \"ערך כלי זה עלי\",\u0004 וכפי שאמרנו אין ערכים אלא לאדם — \u0003נותן דמיו\u0004 של הכלי להקדש. \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הלכה זו? \u0003אדם יודע שאין ערך לכלי,\u0004 כלומר, שבכלי אין שייך מושג הערך, \u0003וגמר ואמר\u0004 והיתה כוונתו \u0003לשום\u0004 (לשם) \u0003דמים,\u0004 והשתמש במלה \"ערך\" שלא כדיוקה, \u0003משום הכי\u0004 \u0005[כך]\u0006 \u0003נותן דמיו.\u0004 ומקשים: הסבר זה אינו מתיישב היטב בלשון, \u0003האי\u0004 \u0005[זו\u0006 הלשון\u0005]\u0006 \u0003\"ערכין המטלטלין\"\u0004 אינה מדוייקת כל כך, אלא לשון \u0003\"ערכין של מטלטלין\" מבעיא ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]!\u0006 ומשיבים: זו אינה קושיה, \u0003תני\u0004 \u0005[שנה]\u0006 ותקן קצת בנוסח המשנה: \u0003\"ערכין של מטלטלין\".\u0004","\u0003רב חסדא אמר\u0004 בשם \u0003אבימי\u0004 הסבר אחר: מדובר \u0003במתפיס מטלטלין לערכין\u0004 שלא היה לו ממון בעין לשלם, והתפיס בקדושת הערכין מטלטלין שונים שהקדישם לצורך זה ופדיונם בשלושה. ושוב מקשים מצד הלשון: \u0003האי\u0004 \u0005[זו\u0006 הלשון\u0005]\u0006 \u0003\"ערכין המטלטלין\"\u0004 אינה ראויה, ולשון \u0003\"מטלטלין של ערכין\" מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]!\u0006 ומשיבים: \u0003תני\u0004 \u0005[שנה]\u0006 ותקן את לשון המשנה כך: \u0003\"מטלטלין של ערכין\".\u0004","\u0003ר' אבהו אמר,\u0004 אפשר לפרש כך: \u0003באומר \"ערכי עלי\",\u0004 ואז אם \u0003בא כהן לגבות ממנו מטלטלין\u0004 בתשלום הערך — אומדים אותם \u0003בשלשה,\u0004 ואם בא לגבות ממנו \u0003קרקעות\u0004 — \u0003בעשרה. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא מדיפתי לרבינא\u0004 בענין זה: \u0003בשלמא לאפוקי\u0004 \u0005[נניח ל\u0006ענין זה ש\u0005להוציא]\u0006 \u0003מ\u0004ן ה\u0003הקדש בעינן\u0004 \u0005[צריכים אנו]\u0006 \u0003שלשה\u0004 דיינים, שאם הוטעה ההקדש הרי זה כמועל בקודש. \u0003אלא לעיולי\u0004 \u0005[להכניס]\u0006 \u0003להקדש\u0004 \u0003שלשה\u0004 דיינים לשם כך \u0003למה לי?\u0004 ולשם מה דיינים אלה כשבא אדם להקדיש דבר?","\u0003אמר ליה\u0004 \u0005לו]:\u0006 \u0003סברא הוא\u0004 דבר זה: \u0003מה לי עיולי\u0004 \u0005[להכניס]\u0006 \u0003מה לי אפוקי\u0004 \u0005[להוציא],\u0006 כי \u0003אפוקי מאי טעמא\u0004 \u0005[\u0006ב\u0005הוצאה מה טעם]\u0006 צריכים בית דין — \u0003דילמא טעי\u0004 \u0005[שמא יטעה]\u0006 ויפחית מן המחיר, ויימצא ההקדש נפסד, \u0003עיולי נמי דילמא טעי\u0004 \u0005[\u0006ב\u0005הכנסה גם כן\u0006 קיים החשש \u0005שמא יטעה]\u0006 ונמצא ההקדש נפסד.","שנינו במשנה כי \u0003ר' יהודה אומר\u0004 שבערכים, על אחד מאומדי הערך לצורך פדיון להיות כהן. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי: בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003ר' יהודה\u0004 — \u0003היינו דכתיב\u0004 \u0005[זהו שנאמר\u0006 שם\u0005]\u0006 בפרשת פדיון הקדשות \u0003\"כהן\", אלא לרבנן\u0004 \u0005[ל\u0006שיטת \u0005חכמים]\u0006 שכל אדם ראוי לכך, \u0003\"כהן\" למה להו\u0004 \u0005[להם]\u0006 שיהא כתוב שם? ומסכמים: אכן, \u0003קשיא\u0004 \u0005[קשה\u0006 הדבר\u0005].\u0006","עוד שנינו במשנה כי הקדשי \u0003קרקעות\u0004 דנים ב\u0003תשעה וכהן.\u0004 ושואלים: \u0003מנהני מילי\u0004 \u0005[מנין דברים אלה],\u0006 מה מקורם בכתוב? \u0003אמר שמואל: עשרה \"כהנים\",\u0004 כלומר, עשר פעמים \"כהן\" \u0003כתובין בפרשה\u0004 זו של הקדשים ופדיית הקדשים (ויקרא פרק כז), \"כהן\" \u0003חד לגופיה\u0004 \u0005[אחד לגופו],\u0006 כלומר, שיהיה צורך בכהן, \u0003הנך\u0004 \u0005[הללו]\u0006 האחרים הנוספים עליו \u0003הוי\u0004 \u0005[הריהם]\u0006 \u0003מיעוט אחר מיעוט,\u0004 שכן כל פעם יש הדגשה נוספת \"כהן\" ולא אחר, \u0003ו\u0004כלל בידינו: \u0003אין מיעוט אחר מיעוט אלא לרבות,\u0004 ללמדנו ש\u0003אפילו תשעה ישראל ואחד כהן.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה עליה],\u0006 על סברה זו, \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נתן: אימא\u0004 \u0005[אמור]\u0006 על פי אותו כלל שאין מיעוט אחר מיעוט אלא לרבות, באופן זה שיצטרכו \u0003חמשה כהנים וחמשה ישראלים,\u0004 שהרי בפעם הראשונה שמוזכר \"כהן\" הרי זה כהן ממש, בפעם השניה לשון זו באה לרבות וללמד שאפילו ישראל כשר, ואולם בפעם השלישית שנאמר \"כהן\" שוב אפשר לפרש שהכוונה לכהן דווקא. לשאלה זו לא נמצאה תשובה, ונשארה ב\u0003קשיא\u0004 \u0005[קשה].\u0006","שנינו במשנה שכשם שהקרקעות בתשעה וכהן, כך \u0003אדם כיוצא בהן.\u0004 ותוהים: \u0003אדם מי\u0004 \u0005[האם]\u0006 \u0003קדוש?\u0004 כיצד אפשר שתחול עליו קדושת הגוף? \u0003אמר ר' אבהו:\u0004 הכוונה לאדם ה\u0003אומר \"דמי עלי\",\u0004 כלומר, אני מקדיש את מחירי כנדר לבית המקדש. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003האומר \"דמי עלי\"\u0004 — \u0003שמין\u0004 (מעריכים) \u0003אותו כעבד הנמכר בשוק,\u0004 והמחיר שהיו משלמים עבורו בתורת עבד הוא המחיר שעליו לתת להקדש. \u0003ועבד אתקש\u0004 \u0005[הושווה\u0006 במקרא\u0005]\u0006 \u0003לקרקעות,\u0004 וכל דין האמור בקרקעות יש לשייכו ולהחילו גם על העבד. ולכן כדין הערכת קרקעות דין הערכת אדם.","באותו ענין \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' אבין: שער\u0004 של אדם שהוקדש, ואותו שיער גדל והוא כבר \u0003עומד ליגזוז, בכמה?\u0004 האם נאמר כי שיער כזה \u0003כגזוז דמי\u0004 \u0005[נחשב]\u0006 \u0003ו\u0004הוא נערך כשאר מטלטלין \u0003בשלשה\u0004 דיינים, \u0003או כמחובר\u0004 לגופו עדיין \u0003דמי\u0004 \u0005[נחשב],\u0006 והמחובר לו הריהו כמותו, \u0003ובעשרה\u0004 דיינים?","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לבעיה זו ממה ששנינו: \u0003המקדיש את עבדו אין מועלין בו\u0004 בעבד, משום שאין בו קדושת הגוף, שאין גופו קדוש, \u0003רבן שמעון בן גמליאל אומר: מועלין בשערו. וקיימא לן\u0004 \u0005[ומוחזק בידינו]\u0006 ש\u0003בשערו העומד ליגזוז פליגי\u0004 \u0005[נחלקו],\u0006 אם כן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שנחלקו האם שיער זה כגזוז או אינו כגזוז.","ומציעים: \u0003נימא הני תנאי כהני תנאי\u0004 \u0005[האם לומר ש\u0006מחלוקת \u0005תנאים אלו, כ\u0006מחלוקת אחרת של \u0005תנאים אלו].\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005],\u0006 \u0003ר' מאיר אומר: יש דברים שהן כקרקע\u0004 מבחינה אחת, \u0003ואינן כקרקע\u0004 מבחינה אחרת, \u0003ואין חכמים מודים לו. כיצד?\u0004 — אמר אדם לחבירו: \u0003\"עשר גפנים טעונות\u0004 ענבים \u0003מסרתי לך,\u0004 ורצוני לקבל דמיהן \u0003\"\u0004, \u0003והלה אומר: \"אינן אלא חמש\". ר' מאיר מחייב\u0004 את הנתבע שישבע על השאר, כדין מודה במקצת הטענה. \u0003וחכמים אומרים: כל המחובר לקרקע הרי הוא כקרקע,\u0004 וממדרש המקראות למדנו שאין אדם נשבע בהכחשה (\"כפירה\") בטענה בדין קרקעות.","\u0003ואמר ר' יוסי בר חנינא: בענבים העומדות ליבצר עסקינן\u0004 \u0005[עוסקים אנו]\u0006 במשנה זו. \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' מאיר, \u0005סבר]:\u0006 \u0003כבצורות דמיין\u0004 \u0005[\u0006הן \u0005נחשבות],\u0006 וכיון שהענבים בצורים הרי שהטענה היא ביחס למטלטלין, וראוי שישבע הנתבע, המכחיש שקיבל את הענבים הללו. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 חכמים, \u0005סברו]:\u0006 \u0003לאו\u0004 \u0005[לא]\u0006 \u0003כבצורות דמיין\u0004 \u0005[\u0006הן \u0005נחשבות].\u0006 ודוחים: \u0003לא,\u0004 אין להוכיח מכאן, \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 ששיטת חכמים בענין השיער היא כדעת \u0003ר' מאיר,\u0004 כי \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' מאיר התם\u0004 \u0005[שם,\u0006 בענין הגפנים\u0005]\u0006 שענבים העומדים להיבצר דינם כבצורים, משום ש\u0003כל כמה דשבקה להו מיכחש כחשי\u0004 \u0005[ש\u0006הוא \u0005משאיר אותן\u0006 על הגפן הרי הן \u0005מכחישות\u0006 ונחלשות\u0005],\u0006 ולכן הענבים נחשבים כבצורים. \u0003אבל שערו\u0004 — \u0003כל כמה דשבקה להו אשבוחי משבח\u0004 \u0005[ש\u0006הוא \u0005משאיר אותן\u0006 עליו הרי הן \u0005משביחות],\u0006 ששיער ארוך הוא בעל ערך רב יותר, ולכן אין לומר ששיער העומד להיגזז נחשב כבר כגזוז, כפי שאומרים בענבים.","במשנה שנינו ש\u0003דיני נפשות\u0004 בעשרים ושלושה, וכן הרובע והנרבע בעשרים ושלושה. ומעירים: במשנה \u0003קא פסיק ותני\u0004 \u0005[פסק ושנה]\u0006 בלא לחלק בין הדברים, \u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 אם היה זה פר \u0003רובע\u0004 את ה\u0003זכר, ולא שנא\u0004 \u0005[ואינו שונה]\u0006 אם היה זה פר ה\u0003רובע נקבה. בשלמא\u0004 \u0005[נניח]\u0006 במקרה של ה\u0003רובע נקבה, דכתיב\u0004 \u0005[שנאמר]\u0006 במפורש: \u0003\"\u0004ואשה אשר תקרב אל כל בהמה לרבעה אותה \u0003והרגת את האשה ואת הבהמה\"\u0004 (ויקרא כ, טז), \u0003אלא\u0004 שור ה\u0003רובע\u0004 את ה\u0003זכר מנא לן\u0004 \u0005[מנין לנו]\u0006 שהבהמה בהריגה?","ומשיבים: \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כל שכב עם בהמה מות יומת\"\u0004 (שמות כב, יח), \u0003אם אינו ענין לשוכב\u0004 העושה מעשה שכבר נאמר דינו במקום אחר, \u0003תניהו ענין לנשכב\u0004 ונפרש ששוכב עם בהמה אינו דווקא זה שעושה מעשה, אלא כל מי שיש לו מגע מיני עם בהמה, גם אם הוא הנרבע. \u0003ואפקיה רחמנא\u0004 \u0005[והוציאתו התורה]\u0006 \u0003בלשון \"שוכב\", לאקושי\u0004 \u0005[להשוות]\u0006 \u0003נשכב לשוכב. מה שוכב\u0004 — \u0003הוא ובהמתו\u0004 נידונים \u0003בעשרים ושלשה\u0004 דיינים, \u0003אף נשכב\u0004 — \u0003הוא ובהמתו בעשרים ושלשה.\u0004","שנינו במשנה כי \u0003שור הנסקל\u0004 נידון \u0003בעשרים ושלשה\u0004 דיינים, \u0003שנאמר: \"השור יסקל וגם בעליו יומת\"\u0004 (ויקרא כא, כט), ולומדים מהשוואה זו: \u0003כמיתת הבעלים\u0004 שהיא בבית דין של עשרים ושלושה, \u0003כך מיתת השור. אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרבא: ממאי דהאי\u0004 \u0005[מנין\u0006 לנו \u0005שזה]\u0006 הכתוב \u0003\"וגם בעליו יומת\", לכמיתת בעלים כך מיתת השור הוא דאתא\u0004 \u0005[שבא]?\u0006 שהרי לא נכתבה הלכה זו במפורש, ושמא יש לפרש את הכתוב אחרת,"],["\u0003אימא לקטלא\u0004 \u0005[אמור\u0006 כי \u0005ל\u0006דין \u0005מיתה]\u0006 עצמו \u0003הוא דאתא\u0004 \u0005[שבא],\u0006 שהבעלים חייבים מיתה! ענה לו רבא: \u0003אם כן,\u0004 שהכוונה היתה שגם הבעלים יומתו, \u0003ליכתוב\u0004 \u0005[שיכתוב]\u0006 באותו מקרא רק \u0003\"\u0004השור יסקל \u0003וגם בעליו\" ולישתוק\u0004 \u0005[ושישתוק]\u0006 ולא יוסיף עוד, ותהא המשמעות ברורה שגם בעליו במיתה.","אמר לו אביי: \u0003אי כתב רחמנא הכי, הוה אמינא\u0004 \u0005[אילו היתה כותבת התורה כך, הייתי אומר]\u0006 שעונשו \u0003בסקילה,\u0004 שהשור יסקל וגם בעליו. ודוחים: \u0003בסקילה סלקא דעתך\u0004 \u0005[עולה על דעתך\u0006 לומר\u0005]?\u0006 הלא אם \u0003קטל איהו\u0004 \u0005[הורג הוא עצמו\u0006 אדם\u0005]\u0006 — \u0003בסייף,\u0004 שהיא נחשבת מיתה קלה, אם \u0003ממונו\u0004 הורג יהא עונשו \u0003בסקילה\u0004 החמורה?!","אלא ודאי הכוונה כפי שהבינו מתחילה. ושואלים: ושמא נאמר שהכוונה באמת שגם הבעלים במיתה, \u0003ודילמא האי דכתב רחמנא\u0004 \u0005[ושמא זה שכתבה התורה]\u0006 \u0003\"יומת\"\u0004 — הרי זה \u0003לאקולי עילויה\u0004 \u0005[להקל עליו]\u0006 בדינו, \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 את דינו \u0003מ\u0004דין \u0003סייף ל\u0004דין \u0003חנק,\u0004 שדין רוצח בעצמו בסייף, אבל מי שהרגה בהמתו עונשו קל יותר והוא בחנק! וממשיכים בשאלה: \u0003הניחא למאן ד\u0004\u0003אמר\u0004 \u0005[זה נוח ל\u0006דעת \u0005מי שאומר]\u0006 ש\u0003חנק חמור\u0004 מסייף, ואז ברור שאין מקום לטענה כגון זו, שוודאי אין באים להחמיר עליו ולדונו בעונש קשה יותר מרוצח בעצמו, \u0003אלא למאן ד\u0004\u0003אמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 ש\u0003חנק קיל\u0004 \u0005[קל\u0006 יותר\u0005],\u0006 \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 שמא בא הכתוב לצורך זה?","ודוחים: \u0003לא סלקא דעתך\u0004 \u0005[יעלה על דעתך]\u0006 לומר כן, \u0003דכתיב\u0004 \u0005[ש\u0006הרי \u0005נאמר\u0006 שם\u0005]\u0006 \u0003\"אם כפר יושת עליו\u0004 ונתן פדיון נפשו ככל אשר יושת עליו\u0003\"\u0004 (שמות כא, ל), \u0003ואי סלקא דעתך בר קטלא\u0004 \u0005[ואם עולה על דעתך\u0006 לומר כי \u0005בן מוות]\u0006 \u0003הוא,\u0004 \u0003והכתיב\u0004 \u0005[והרי נאמר\u0006 במפורש\u0005]\u0006 \"ו \u0003לא תקחו כפר לנפש רצח\u0004 אשר הוא רשע למות כי מות יומת\" (במדבר לה, לא), הרי מכאן נלמד כי אדם זה שלוקחים ממנו כופר אינו חייב מיתה!","ודוחים: \u0003אדרבה, משום היא\u0004 (אותה טענה) \u0003גופה\u0004 נאמר כך: אם \u0003קטל איהו\u0004 \u0005[הרג הוא עצמו\u0006 אדם\u0005],\u0006 \u0003לא תיסגי ליה בממונא\u0004 \u0005[יהיה די לו ב\u0006עונש \u0005ממון]\u0006 \u0003אלא בקטלא\u0004 \u0005[במוות\u0006 ממש\u0005],\u0006 אם \u0003קטל\u0004 \u0005[הרג]\u0006 \u0003שורו\u0004 — \u0003ליפרוק נפשיה בממונא\u0004 \u0005[שיפדה\u0006 את \u0005עצמו בממון],\u0006 ואם לא פדה עצמו — דינו במיתה! \u0003אלא\u0004 אין ראיה גמורה ממקראות אלה, ויש להוכיח ממה ש\u0003אמר חזקיה, וכן תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003חזקיה\u0004 ברייתא זו, \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"מות יומת המכה רצח הוא\"\u0004 (במדבר לה, כא), ונדייק מן המלה \"הוא\": \u0003על רציחתו\u0004 שלו \u0003אתה הורגו, ואי\u0004 (ואין) \u0003אתה הורגו על רציחת שורו.\u0004","אגב ענין זה \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 \u0003שור סיני בכמה?\u0004 שכן בשעת מתן תורה נאסר על הכל לעלות על הר סיני, שנאמר: \"לא תגע בו יד כי סקול יסקל או ירה יירה אם בהמה אם איש לא יחיה\" (שמות יט, יג), האם גם בהמה שעלתה על ההר מיתתה בעשרים ושלושה דיינים? ועיקר השאלה: \u0003מי גמר\u0004 \u0005[האם לומדים\u0006 אנו\u0005]\u0006 הוראת \u0003שעה\u0004 שהיתה בסיני \u0003מ\u0004דין שנאמר ל\u0003דורות,\u0004 שבהמה הנסקלת נידונה בעשרים ושלושה, \u0003או לא?\u0004 ומשיבים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003רמי בר יחזקאל\u0004 ברייתא זו על הכתוב \u0003\"אם בהמה אם איש לא יחיה\",\u0004 שהשוואה זו בכתוב באה ללמד: \u0003מה איש\u0004 נידון \u0003בעשרים ושלשה\u0004 דיינים, \u0003אף בהמה בעשרים ושלשה.\u0004","במשנה הובאה מחלוקת ביחס ל\u0003ארי ו\u0004ל\u0003זאב,\u0004 אם מיתתם בעשרים ושלושה. \u0003אמר ריש לקיש: והוא\u0004 מדובר בזאב וארי \u0003שהמיתו\u0004 אדם, \u0003אבל\u0004 אם \u0003לא המיתו\u0004 — \u0003לא,\u0004 ומסבירים: \u0003אלמא קסבר\u0004 \u0005[מכאן\u0006 ש\u0005סבר]\u0006 ריש לקיש כי \u0003יש להן תרבות,\u0004 כלומר, בעלי חיים אלה נעשים בני תרבות ומותר לגדלם, \u0003ו\u0004לכן \u0003יש\u0004 \u0003להן בעלים,\u0004 ואי אפשר להורגם ללא סיבה כשם שאין הורגים שאר בעלי חיים ביתיים. ואילו \u0003ר' יוחנן אמר:\u0004 מחלוקת זו היתה \u0003אף על פי שלא המיתו, אלמא קסבר\u0004 \u0005[מכאן\u0006 ש\u0005סבר]\u0006 ר' יוחנן כי \u0003אין להם תרבות\u0004 לחיות טרף אלה, \u0003ואין להם בעלים.\u0004","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005],\u0006 \u0003ר' אליעזר אומר: כל הקודם להורגן זכה, בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003ר' יוחנן, למאי\u0004 \u0005[למה]\u0006 \u0003זכה?\u0004 הכוונה היא ש\u0003זכה לעורן,\u0004 שכיון שאין להם בעלים כל הקודם להורגן זכה, ולוקח את עורן לעצמו. \u0003אלא ל\u0004דעת \u0003ריש לקיש, למאי\u0004 \u0005[למה]\u0006 \u0003זכה?\u0004 הרי \u0003כיון שהמיתו\u0004 כבר \u0003שוינהו רבנן כמאן דגמר דינייהו\u0004 \u0005[עשו אותם חכמים כמי שנגמר דינם]\u0006 בבית דין (שהרי לדעת האומר שהקודם להורגן זכה, משמע שאין צריכים בהכרעת בית דין מיוחד, וכאילו נידונו כבר), ושור הנסקל כיון שנגמר דינו למיתה, אף לפני שסקלוהו בבית דין, אסור אף עורו בהנאה, \u0003ו\u0004אם כן חיות אלה \u0003איסורי הנאה נינהו\u0004 \u0005[הן],\u0006 ואסור ליהנות לא רק מבשרן אלא גם מעורן!","ודוחים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"זכה\"\u0004 לדעת ריש לקיש, ש\u0003זכה\u0004 על פי שיטת ר' אליעזר \u0003לשמים,\u0004 שעשה מעשה מצוה כשהשמיד דבר המזיק. ומעירים, \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 תוספתא \u0005כשיטתו]\u0006 של \u0003ריש לקיש: אחד שור שהמית ואחד בהמה וחיה שהמיתו\u0004 — דינם \u0003בעשרים ושלשה, ר' אליעזר אומר: שור שהמית\u0004 דינו \u0003בעשרים ושלשה, ושאר בהמה וחיה שהמיתו\u0004 — \u0003כל הקודם להורגן זכה בהן לשמים.\u0004 משמע שנחלקו רק באלה שהמיתו. ו\"זכה בהן\" משמעו שזוהי זכיה מוסרית בלבד, וכדברי ריש לקיש.","במשנה הובא ש\u0003ר' עקיבא אומר:\u0004 מיתתן בעשרים ושלושה. ומקשים: שיטת \u0003ר' עקיבא\u0004 לכאורה \u0003היינו\u0004 \u0005[זוהי]\u0006 ממש שיטת ה\u0003תנא קמא\u0004 \u0005[הראשון],\u0006 ומה חידוש בדבריו? ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005]\u0006 לענין \u0003נחש,\u0004 שלדעת התנא הראשון גם הוא נידון בעשרים ושלושה, ור' עקיבא סבור שרק חיות ובהמות בכלל זה, ולא נחשים.","שנינו במשנה ש\u0003אין דנין\u0004 את השבט אלא בשבעים ואחד דיינים. ומבררים: \u0003האי\u0004 \u0005[זה]\u0006 ה\u0003שבט\u0004 שאמרנו ש\u0003חטא, במאי\u0004 \u0005[במה\u0006 חטא\u0005]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהיה זה \u0003שבט שחלל את השבת, אימר\u0004 \u0005[אמור]\u0006 \u0003דפליג רחמנא\u0004 \u0005[שחילקה התורה]\u0006 \u0003בין\u0004 דין \u0003יחידים ל\u0004דין \u0003מרובין לענין עבודה זרה,\u0004 שיש דין מיוחד לעיר שלמה שהודחה אחרי עבודה זרה, ואולם \u0003בשאר מצו‍ת מי פליג\u0004 \u0005[האם חילק]\u0006 בין יחיד ובין רבים? \u0003אלא\u0004 צריכים לומר שהמשנה מדברת \u0003בשבט שהודח\u0004 לעבודה זרה.","ויש להקשות: \u0003למימרא דבדינא\u0004 \u0005[האם לומר שבדין]\u0006 של \u0003רבים דיינינן ליה\u0004 \u0005[אנו דנים אותם]\u0006 בעיר הנדחת? אם כן \u0003כמאן\u0004 \u0005[כמי\u0006 תהיה דעה זו\u0005]?\u0006 הלא אין היא \u0003לא כר' יאשיה ולא כר' יונתן! דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003עד כמה\u0004 אנשים הגרים בעיר \u0003עושין\u0004 אותה \u0003עיר הנדחת? מעשרה ועד מאה\u0004 אנשים, אלו \u0003דברי ר' יאשיה. ר' יונתן אומר: מ\u0004עיר שיש בה \u0003מאה\u0004 אנשים \u0003ועד רובו של שבט.\u0004 שנחלקו חכמים אלה מהו הקרוי \"עיר\" בכתוב.","\u0003ו\u0004משמע, ש\u0003אפילו ר' יונתן לא קאמר\u0004 \u0005[אמר]\u0006 שעושים עיר הנדחת, \u0003אלא\u0004 עד \u0003רובו\u0004 של שבט, \u0003אבל\u0004 \u0003כולו\u0004 — \u0003לא,\u0004 ודאי אין דין עיר הנדחת חל עליו, ושבט שחטא אינו נכלל בכלל זה! \u0003אמר רב מתנה: הכא\u0004 \u0005[כאן]\u0006 במשנה,"],["\u0003בנשיא שבט שחטא עסקינן\u0004 \u0005[עוסקים אנו].\u0006 \u0003מי\u0004 \u0005[האם]\u0006 \u0003לא אמר רב אדא בר אהבה \"כל הדבר הגדל יביאו אליך\"\u0004 (שמות יח, כב), פירושו: \u0003דבריו של גדול,\u0004 שכל מקום שגדול ישראל נאשם באשמה שעונשה מוות, הוא נידון בשבעים ואחד דיינים. \u0003האי נמי\u0004 \u0005[זה,\u0006 נשיא השבט, \u0005גם כן]\u0006 \u0003גדול הוא,\u0004 ודינו צריך להיות בשבעים ואחד.","\u0003עולא אמר\u0004 בשם \u0003ר' אלעזר\u0004 הסבר אחר, שהשבט נידון בשבעים ואחד באופן מסויים — \u0003בבאין\u0004 שני שבטים להידון \u0003על עסקי נחלות\u0004 מהי הנחלה השייכת לכל שבט, \u0003ו\u0004עושים זאת בבית דין של שבעים ואחד \u0003כתחילתה של\u0004 חלוקת \u0003ארץ ישראל\u0004 לשבטים בימי יהושע. \u0003מה תחילתה\u0004 של חלוקה היתה ב\u0003שבעים ואחד\u0004 זקני העדה, \u0003אף כאן\u0004 לא ידון ענין הנחלה אלא בבית דין של \u0003שבעים ואחד.\u0004","ומקשים: \u0003אי\u0004 \u0005[או]\u0006 אולי נאמר כך, \u0003מה תחילתה\u0004 של חלוקת הארץ היתה ב\u0003קלפי\u0004 (גורל), ב\u0003אורים ותומים, וכל ישראל\u0004 מצויים שם, \u0003אף כאן,\u0004 בסכסוך בין השבטים, יצטרך להיות \u0003קלפי, אורים ותומים וכל ישראל,\u0004 וכיון שאין עושים כן, משמע שאף לענין סכסוכי נחלה בין השבטים אין צורך בבית הדין הגדול. \u0003אלא מחוורתא\u0004 \u0005[מחוור,\u0006 ברור\u0005]\u0006 \u0003כ\u0004הסברו של \u0003רב מתנה\u0004 שמדובר בנשיא של שבט שחטא.","\u0003רבינא אמר: לעולם\u0004 יש לפרש שמדובר כאן \u0003בשבט שהודח\u0004 לעבודה זרה, \u0003ודקא קשיא\u0004 \u0005[ו\u0006מה \u0005שהיה קשה]\u0006 \u0003לך\u0004 וכי \u0003בדינא\u0004 \u0005[בדין]\u0006 של \u0003רבים דיינינן ליה\u0004 \u0005[אנו דנים אותם]\u0006 ולא כיחידים, הרי יש להשיב: \u0003אין\u0004 \u0005[כן],\u0006 \u0003אף על גב דקטלינן ביחיד\u0004 \u0005[אף על פי שאנו הורגים\u0006 אותם \u0005כיחידים],\u0006 ודנים אותם בסקילה, ואין מחרימים את ממונם, בכל זאת \u0003בי דינא\u0004 \u0005[בבית דין]\u0006 של \u0003רבים דיינינן ליה\u0004 \u0005[אנו דנים אותו],\u0006 שדנים דינו של כל אחד בסנהדרי גדולה.","וראיה לדבר: \u0003מי\u0004 \u0005[האם]\u0006 \u0003לא אמר ר' חמא בר' יוסי אמר ר' אושעיא:\u0004 על הכתוב שנאמר ביחיד העובד עבודה זרה \u0003\"והוצאת את האיש ההוא או את האשה ההוא\u0004 אשר עשו את הדבר הרע הזה אל שעריך, את האיש או את האשה וסקלתם באבנים ומתו\u0003\"\u0004 (דברים יז, ה), ומדיוק הלשון למדנו: \u0003איש ואשה\u0004 בודדים \u0003אתה מוציא לשעריך\u0004 לדון אותם בבית הדין שבשער העיר, שהוא סנהדרי קטנה, \u0003ואי\u0004 (ואין) \u0003אתה מוציא\u0004 את \u0003כל העיר כולה לשעריך,\u0004 אלא הם נידונים בבית הדין הגדול. \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 בשבט שחטא: \u0003איש ואשה אתה מוציא לשעריך, ואי אתה מוציא כל השבט כולו לשעריך,\u0004 אלא נידונים בבית דין של שבעים ואחד.","שנינו במשנה ש\u0003לא\u0004 דנים \u0003את נביא השקר\u0004 אלא בבית דין של שבעים ואחד. ושואלים: \u0003מנהני מילי\u0004 \u0005[מנין דברים אלה],\u0006 מה מקורם במקרא?","\u0003אמר ר' יוסי בר' חנינא: אתיא\u0004 \u0005[בא,\u0006 נלמד\u0005]\u0006 הדבר בגזירה שווה של לשון \u0003\"הזדה\" \"הזדה\" מזקן ממרא,\u0004 שבנביא שקר נאמר \"אך הנביא אשר יזיד לדבר דבר בשמי את אשר לא צויתיו לדבר ואשר ידבר בשם אלהים אחרים ומת הנביא ההוא\" (דברים יח, כ), ובזקן ממרא נאמר \"והאיש אשר יעשה בזדון לבלתי שמוע אל הכהן העומד לשרת שם את ה' אלהיך או אל השופט ומת האיש ההוא ובערת הרע מישראל\" (דברים יז, יב), \u0003מה להלן ב\u0004זקן ממרא אין הזדה אלא כנגד בית הדין הגדול של \u0003שבעים ואחד, אף כאן\u0004 בנביא שקר אינו נידון אלא \u0003ב\u0004בית דין של \u0003שבעים ואחד.\u0004","ותוהים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"הזדה\" כי כתיבא\u0004 \u0005[כאשר נאמרה]\u0006 בזקן ממרא, \u0003ב\u0004דין \u0003קטלא\u0004 \u0005[מיתה]\u0006 \u0003הוא דכתיבא\u0004 \u0005[שנאמרה],\u0006 \u0003וקטלא בעשרין ותלתא\u0004 \u0005[והמיתה\u0006 שלו \u0005בעשרים ושלושה]\u0006 דיינים בלבד \u0003הוא\u0004 ולא בשבעים ואחד! \u0003אלא אמר ריש לקיש:\u0004 יש לומר כי \u0003גמר\u0004 \u0005[למד]\u0006 בגזירה שווה \u0003\"דבר\" \"דבר\" מהמראתו,\u0004 שהמצוה שהזקן הממרא עובר עליה במריו היא הוראת התורה \"ועשית על פי הדבר אשר יגידו לך\" (דברים יז, י), ובמיתת נביא השקר נאמר \"אשר יזיד לדבר דבר בשמי\" (דברים יח, כ), וכשם שהזקן הממרא עושה דבר כנגד בית דין של שבעים ואחד — אף המזיד לדבר דבר שלא בשם ה' דינו מיתה בבית דין של שבעים ואחד.","ושואלים: \u0003ולהדר\u0004 \u0005[ושיחזור]\u0006 דין \u0003זקן ממרא, ולגמר\u0004 \u0005[ושילמד]\u0006 בגזירה שווה מן המילים \u0003\"הזדה\" \"הזדה\" מנביא השקר,\u0004 ואף זקן ממרא יצטרכו לדונו בבית דין של שבעים ואחד! ומשיבים: \u0003\"דבר\" \"דבר\"\u0004 — \u0003גמיר\u0004 \u0005[למד],\u0006 גזירה שווה זו קיבל במסורת, ואילו \u0003\"הזדה\" \"הזדה\"\u0004 — גזירה שווה זו \u0003לא גמיר\u0004 \u0005[למד],\u0006 לא קיבל במסורת.","שנינו במשנה ש\u0003לא\u0004 דנים \u0003את\u0004 ה\u0003כהן גדול,\u0004 אלא בבית דין של שבעים ואחד. ושואלים: \u0003מנהני מילי\u0004 \u0005[מנין דברים אלה]?\u0006 \u0003אמר רב אדא בר אהבה:\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"כל הדבר הגדל יביאו אליך\"\u0004 (שמות יח, כב), ומשמעו שמשה (או בית דין של שבעים ואחד שהוא במקומו) ידון ב\u0003דבריו של גדול\u0004 בישראל.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו בברייתא: \u0003\"דבר גדל\"\u0004 שנאמר בכתוב משמעו — \u0003דבר קשה. אתה אומר\u0004 שמשמעו \u0003דבר קשה, או אינו אלא דבריו של גדול?\u0004 — \u0003כשהוא אומר\u0004 בפסוק אחר המספר כיצד ביצע משה את עצת יתרו \u0003\"את הדבר הקשה יביאון אל משה\"\u0004 (דברים יח, כו) — \u0003הרי דבר קשה אמור,\u0004 משמע שדבר הגדול הוא הוא דבר הקשה!","ומשיבים: \u0003הוא,\u0004 רב אדא בר אהבה, ש\u0003אמר כי האי תנא\u0004 \u0005[כ\u0006שיטתו של \u0005תנא זה],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 אחרת: משמעות הכתוב \u0003\"דבר גדל\"\u0004 היא — \u0003דבריו של גדול. אתה אומר\u0004 שהמשמעות היא \u0003דבריו של גדול, או אינו אלא דבר הקשה?\u0004 ויש לדחות: \u0003כשהוא אומר\u0004 הלאה \u0003\"הדבר הקשה\u0004 יביאון אל משה \u0003\",\u0004 \u0003הרי דבר קשה אמור,\u0004 ולמדנו שדבר שבית דין אינו יכול לפתרו מביאים לפני משה, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003מה אני מקיים \"דבר גדל\"\u0004 — \u0003דבריו של גדול,\u0004 ושואלים:","\u0003והאי תנא\u0004 \u0005[ותנא זה]\u0006 שלדעתו \"דבר גדול\" ו\"דבר קשה\" אחד הוא, \u0003תרי קראי\u0004 \u0005[שני כתובים]\u0006 לדבר אחד \u0003למה לי?\u0004 ומשיבים: \u0003חד לצואה בעלמא\u0004 \u0005[אחד לציווי בלבד],\u0006 \u0003וחד\u0004 \u0005[ואחד]\u0006 \u0003לעשייה\u0004 שכן נעשה הדבר. ושואלים: \u0003ואידך\u0004 \u0005[ו\u0006התנא \u0005האחר],\u0006 מדוע אינו מפרש כן? ומסבירים: \u0003אם כן,\u0004 ששניהם אחד הם, \u0003לכתוב\u0004 \u0005[שיכתוב]\u0006 \u0003או \"גדול\" \"גדול\"\u0004 בשני המקרים, \u0003או \"קשה\" \"קשה\"\u0004 בשני המקרים, \u0003מאי\u0004 \u0005[מה]\u0006 משמע \u0003\"גדול\", ומאי\u0004 \u0005[ומה]\u0006 משמע \u0003\"קשה\"\u0004 שנאמרו בשני מקומות? \u0003שמע מינה תרתי\u0004 \u0005[למד מכאן שני\u0006 דברים\u0005],\u0006 גם לענין דבר הגדול וגם לענין דבר הקשה.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' אלעזר\u0004 שאלה זו: \u0003שורו של כהן גדול\u0004 שהרג נפש, \u0003בכמה\u0004 דיינים הוא נידון? וצדדי השאלה: האם \u0003למיתת בעלים דידיה\u0004 \u0005[שלו]\u0006 \u0003מדמינן ליה\u0004 \u0005[משווים אנו אותו],\u0006 ולפיכך אף שורו נידון בשבעים ואחד, \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003למיתת בעלים דעלמא\u0004 \u0005[בכלל]\u0006 \u0003מדמינן ליה\u0004 \u0005[משווים אנו אותו]\u0006 ויהיה נידון בעשרים ושלושה בלבד? \u0003אמר אביי: מדקא מבעיא ליה\u0004 \u0005[מתוך שנשאלה לו\u0006 השאלה\u0005]\u0006 ב\u0003שורו,\u0004 הרי \u0003מכלל\u0004 הדבר תלמד ש\u0003ממונו פשיטא ליה\u0004 \u0005[פשוט לו],\u0006 שבשאר דיני ממונות של הכהן הגדול דן בית דין רגיל.","על הערה זו של אביי תוהים: \u0003פשיטא\u0004 \u0005[פשוט\u0006 הדבר\u0005]!\u0006 ומדוע לא יהא כן? ומסבירים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003הואיל וכתב \"כל הדבר הגדל\",\u0004 היינו חושבים שהכוונה היא ל\u0003כל דבריו של גדול,\u0004 כל סכסוך שכהן גדול הוא צד בו ידון בבית הדין הגדול, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 דבר זה.","שנינו במשנה ש\u0003אין מוציאין\u0004 למלחמת הרשות אלא על פי בית דין של שבעים ואחד, ושואלים: \u0003מנהני מילי\u0004 \u0005[מנין דברים אלה]?\u0006 \u0003אמר ר' אבהו:\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בזמן מינוי יהושע: \u0003\"ולפני אלעזר הכהן יעמד\u0004 ושאל לו במשפט האורים לפני ה' על פיו יצאו ועל פיו יבואו הוא וכל בני ישראל אתו וכל העדה\u0003\"\u0004 (במדבר כז, כא), והרי פסוק זה מדבר במנהיג היוצא למלחמה (\"יצאו\" \"יבואו\"),","\u0003\"הוא\"\u0004 — \u0003זה מלך,\u0004 יהושע או כל מנהיג אחר שיהיה במקומו, \u0003\"וכל בני ישראל אתו\"\u0004 — \u0003זה משוח מלחמה,\u0004 כהן שנמשח במיוחד לעמוד לפני המלחמה ולהדריך את העם (ראה דברים כ, ב), \u0003\"וכל העדה\"\u0004 — \u0003זה סנהדרי.\u0004 הרי שסנהדרין גדולה צריכה להיות שם ולתת רשות למלך.","ושואלים: \u0003ודילמא\u0004 \u0005[ושמא]\u0006 זה שהכתוב מזכיר את הסנהדרין, הכוונה היא ש\u0003לסנהדרי הוא דקאמר להו רחמנא\u0004 \u0005[שאמרה להם התורה],\u0006 \u0003דלישיילו\u0004 \u0005[שישאלו]\u0006 \u0003באורים ותומים,\u0004 ולהם הרשות לעשות זאת, אבל המלך יכול לצאת למלחמה בלא רשות סנהדרין?","\u0003 אלא\u0004 הראיה היא \u0003כי הא\u0004 \u0005[כמו זה]\u0006 ש\u0003אמר רב אחא בר ביזנא אמר ר' שמעון חסידא\u0004 \u0005[החסיד]:\u0006 \u0003כנור היה תלוי למעלה ממטתו של דוד, כיון שהגיע חצות לילה רוח צפונית מנשבת בו, והיה מנגן\u0004 הכינור \u0003מאליו. מיד היה דוד עומד\u0004 משנתו \u0003ועוסק בתורה עד שעלה עמוד השחר. כיון שעלה עמוד השחר נכנסו חכמי ישראל אצלו,\u0004","\u0003אמרו לו: אדונינו המלך, עמך ישראל צריכין לפרנסה\u0004 ואין להם מהיכן! \u0003אמר להן: לכו והתפרנסו זה מזה. אמרו לו: אין הקומץ\u0004 (הכמות הקטנה הנכנסת ליד אחת) \u0003משביע את הארי\u0004 הגדול, \u0003ואין הבור מתמלא מחולייתו\u0004 (רק ממי הגשמים שיורדים במישרין לתוכו בלבד), אלא צריכים למשוך לו מים ממקום אחר. \u0003אמר להם:\u0004 אם כן, \u0003לכו פשטו ידיכם בגדוד\u0004 ועשו מלחמה על העמים השכנים.","\u0003מיד יועצין באחיתופל\u0004 היכן ומתי להילחם, \u0003ונמלכין\u0004 מתייעצים ומקבלים רשות \u0003בסנהדרין, ושואלין באורים ותומים\u0004 אם יעשו את הדבר אם לא. \u0003אמר רב יוסף: מאי קרא\u0004 \u0005[מהו הכתוב]\u0006 המרמז ומלמד על דבר זה — שנאמר:"],["\u0003\"ואחרי אחיתפל בניהו בן יהוידע ואביתר ושר צבא למלך יואב\"\u0004 (ראה דברי הימים א' כז, לד). וכך יש להבין: \u0003\"אחיתופל\"\u0004 — \u0003זה יועץ, וכן הוא אומר: \"ועצת אחיתפל אשר יעץ\u0004 בימים ההם כאשר ישאל איש בדבר האלהים\u0003\"\u0004 (שמואל ב' טז, כג). \u0003\"ובניהו בן יהוידע\"\u0004 — \u0003זו סנהדרין,\u0004 שהוא היה בראשה. \u0003\"אביתר\"\u0004 — \u0003אלו אורים ותומים,\u0004 שהוא היה הכהן הגדול.","\u0003ו\u0004ראיה שבניהו בן יהוידע הוא סנהדרין, ש\u0003כן הוא אומר \"ובניהו בן יהוידע על הכרתי ועל הפלתי\"\u0004 (דברי הימים א' יח, יז). \u0003ולמה נקרא שמן \"כרתי\" ו\"פלתי\"? \"כרתי\"\u0004 — מפני \u0003שכורתין דבריהן\u0004 ומחליטים, \u0003\"ופלתי\"\u0004 — \u0003שמופלאין מעשיהן. ואחר כך\u0004 לאחר שעשו את כל הדברים האלה \u0003\"שר הצבא למלך יואב\"\u0004 שהוא מנהיג בפועל את המלחמה.","\u0003אמר ר' יצחק בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אדא ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003אמר\u0004 זאת \u0003ר' יצחק בר אבודימי: מאי קרא\u0004 \u0005[מהו הכתוב]\u0006 המרמז מעשה זה בדוד שהיה כינור תלוי לו למעלה ממיטתו והיה מעירו משנתו — שנאמר: \u0003\"עורה כבודי עורה הנבל וכנור אעירה שחר\"\u0004 (תהלים נז, ט).","שנינו במשנה: \u0003ואין מוסיפין על העיר\u0004 ועל העזרות אלא בבית דין של שבעים ואחד. ושואלים: \u0003מנהני מילי\u0004 \u0005[מנין דברים אלה],\u0006 מה מקורם במקרא? \u0003אמר רב שימי בר חייא: אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ככל אשר אני מראה אותך את תבנית המשכן\u0004 ואת תבנית כל כליו \u0003וכן תעשו\"\u0004 (שמות כה, ט), \"וכן תעשו\" משמעו \u0003לדורות הבאין,\u0004 וכשם שהמשכן נעשה בכל פרטיו על פי משה, כך בית המקדש צריך להיעשות על פי בית דין של שבעים ואחד שהם במקום משה.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רבא\u0004 ממה ששנינו בברייתא אחרת: \u0003כל הכלים שעשה משה\u0004 רבינו \u0003משיחתן\u0004 בשמן הקודש היא ש\u0003מקדשן\u0004 להיות ראויים לעבודת המקדש, \u0003מיכן\u0004 (מכאן) \u0003ואילך,\u0004 לדורות הבאים, אין צורך במשיחה אלא עצם \u0003עבודתן מחנכתן,\u0004 שכאשר עושים בהם עבודת קודש כדרכם ממילא הם נעשים כלי קודש. \u0003ואמאי\u0004 \u0005[ומדוע\u0006 יהיה כן\u0005]?\u0006 \u0003נימא\u0004 \u0005[נאמר]\u0006 \u0003\"וכן תעשו\",\u0004 שיעשו \u0003לדורות הבאין\u0004 כבמשכן, ויהא צורך במשיחה בשמן הקודש בכל הדורות!","ומשיבים, \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 באותו ענין ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"\u0004ויהי ביום כלות משה להקים את המשכן וימשח אתו ויקדש אותו ואת כל כליו ואת המזבח ואת כל כליו \u0003וימשחם ויקדש אתם\"\u0004 (במדבר ז, א), ויש כאן הדגשה \u0003\"אתם\"\u0004 — רק הכלים ההם צריכים קידוש \u0003במשיחה, ולא לדורות\u0004 יש צורך \u0003במשיחה.\u0004","ומקשים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 באופן אחר: \u0003אותם\u0004 יש לקדש \u0003במשיחה\u0004 דווקא, \u0003ולדורות\u0004 — \u0003אי\u0004 \u0005[או]\u0006 \u0003במשיחה אי\u0004 \u0005[או]\u0006 \u0003בעבודה,\u0004 שיש גם דרך אחרת ולא רק בעבודה! \u0003אמר רב פפא: אמר קרא\u0004 \u0005[הכתוב]\u0006 לגבי זה: \u0003\"\u0004ולקחו את כל כלי השרת \u0003אשר ישרתו בם בקדש\"\u0004 (במדבר ד, יב), \u0003הכתוב תלאן בשירות,\u0004 שעם שירותם יתקדשו.","ומקשים: \u0003אלא\u0004 אם כן, שיש כתוב מיוחד לענין זה, ההדגשה \u0003\"אתם\" למה לי?\u0004 הרי הדגשה זו מיותרת ואינה באה ללמד דבר! ומשיבים: \u0003אי לאו\u0004 \u0005[אם לא]\u0006 ההדגשה \u0003\"אתם\", הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003לדורות\u0004 נעשה הדבר \u0003במשיחה ובעבודה\u0004 גם יחד, \u0003דהא כתיב\u0004 \u0005[שהרי נאמר]:\u0006 \u0003\"וכן תעשו\",\u0004 והייתי מצרף את האמור בשני הכתובים, לכן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"אתם\",\u0004 ללמד: \u0003אותם\u0004 בלבד \u0003במשיחה, ולא לדורות במשיחה.\u0004","עוד שנינו במשנה ש\u0003אין עושין סנהדראות\u0004 לשבטים אלא על פי בית דין של שבעים ואחד. ושואלים: \u0003מנא לן\u0004 \u0005[מנין לנו]\u0006 דבר זה? ומשיבים: \u0003כדאשכחן\u0004 \u0005[כפי שמצאנו]\u0006 \u0003במשה, דאוקי\u0004 \u0005[שהעמיד]\u0006 \u0003סנהדראות,\u0004 בתי הדין הקטנים לכל ישראל (שמות יח, כה–כו), \u0003ומשה במקום שבעים וחד קאי\u0004 \u0005[ואחד עומד],\u0006 שמינוי שבעים האיש הוא על ידי משה ומכוחו של משה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מניין שמעמידין שופטים לישראל?\u0004 — \u0003תלמוד לומר: \"שפטים\u0004 ושוטרים \u0003תתן\u0004 לך בכל שעריך אשר ה' אלהיך נותן לך לשבטיך ושפטו את העם משפט צדק\u0003\"\u0004 (דברים טז, יח). \u0003שטרים לישראל מניין\u0004 שמעמידים? — \u0003תלמוד לומר: \"\u0004ו\u0003שטרים תתן\". שופטים\u0004 שצריכים למנות לא רק לכל ישראל אלא \u0003לכל שבט ושבט מניין?\u0004 — \u0003תלמוד לומר: \"שפטים... לשבטיך\". שוטרים לכל שבט ושבט מניין?\u0004 — \u0003תלמוד לומר: \"שטרים... לשבטיך\".\u0004","\u0003שופטים\u0004 שצריכים למנות \u0003לכל עיר ועיר מניין?\u0004 — \u0003תלמוד לומר: \"שפטים... לשעריך\",\u0004 ששער העיר הוא מושב זקני העיר ודייניה. \u0003שוטרים לכל עיר ועיר מניין?\u0004 — \u0003תלמוד לומר: \"שטרים... לשעריך\". ר' יהודה אומר:\u0004 צריך שיהא בית דין \u0003אחד\u0004 ה\u0003ממונה על כולן, שנאמר: \"תתן לך\",\u0004 שצריך שיהא מוסד הדואג לכל המינויים הללו. \u0003רבן שמעון בן גמליאל אומר:\u0004 מאותו פסוק עצמו אפשר לדרוש \u0003\"לשבטיך ושפטו\",\u0004 מכאן ש\u0003מצוה בשבט לדון את\u0004 החוטאים בתוך \u0003שבטו,\u0004 ולא למסור את הדין לשבטים אחרים.","שנינו במשנה ש\u0003אין עושין עיר הנדחת\u0004 אלא בסנהדרי גדולה. ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין דברים אלה]?\u0006 \u0003אמר ר' חייא בר יוסף אמר ר' אושעיא:\u0004 שכן \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בעובד עבודה זרה: \u0003\"והוצאת את האיש ההוא או את האשה ההיא\u0004 אשר עשו את הדבר הרע הזה אל שעריך\u0003\"\u0004 (דברים יז, ה). ולמדנו מכאן: \u0003איש ואשה\u0004 בודדים \u0003אתה מוציא לשעריך\u0004 לבית הדין של שער העיר, \u0003ואי\u0004 (אין) \u0003אתה מוציא\u0004 את \u0003כל העיר כולה לשעריך.\u0004 שאינה נידונה בבית דין של שער העיר אלא בבית דין הגדול.","שנינו במשנה ש\u0003אין עושין עיר הנדחת בספר.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 ומסבירים: \"יצאו אנשים בני בליעל \u0003מקרבך\u0004 וידיחו את יושבי עירם\" (דברים יג, יד) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 ובא אומר: מקרבך — מתוך המדינה עצמה \u0003ולא מן הספר,\u0004 שהוא על גבול המדינה ולא בתוכה.","הדין המובא במשנה ש\u0003לא\u0004 עושים \u0003שלש ערי הנדחת\u0004 נלמד ממה \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בדין עיר הנדחת: \"כי תשמע ב\u0003אחת\u0004 עריך אשר ה' אלהיך נותן לך לשבת שם לאמר\" דברים טז, יג), ולא שלוש. \u0003אבל עושין\u0004 עיר נידחת \u0003אחת או שתים, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"עריך\",\u0004 לשון רבים הרי שתים בכלל. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003\"אחת\"\u0004 שבכתוב בא להדגיש — \u0003אחת ולא שלש. אתה אומר\u0004 שהכוונה היא \u0003אחת ולא שלש, או אינו אלא אחת ולא שתים?\u0004 — \u0003כשהוא אומר \"עריך\"\u0004 — \u0003הרי שתים אמור, הא\u0004 \u0005[הרי]\u0006 \u0003מה אני מקיים \"אחת\"\u0004 — \u0003אחת ולא שלש.\u0004","\u0003זימנין\u0004 \u0005[לעיתים,\u0006 לפעמים\u0005]\u0006 \u0003אמר רב: בבית דין אחד הוא\u0004 ש\u0003אין עושין\u0004 יותר משתי ערים נדחות, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003בשנים ושלשה בתי דינין\u0004 — \u0003עושין. וזימנין\u0004 \u0005[ופעמים]\u0006 \u0003אמר רב: אפילו בשנים ושלשה בתי דינין\u0004 — \u0003לעולם אין עושין.\u0004 ולשיטה אחרונה זו שואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003רב?\u0004 ומשיבים: \u0003משום קרחה,\u0004 כלומר, שלא להרבות בישראל חלל ריק מישוב. \u0003אמר ריש לקיש: לא שנו\u0004 שאין עושים שלוש ערים נדחות \u0003אלא במקום אחד, אבל בשנים ושלשה מקומות\u0004 — \u0003עושין. ר' יוחנן אמר: אין עושין\u0004 כלל \u0003משום קרחה,\u0004 שלא לעשות מקומות חסרי ישוב בתוך ארץ ישראל.","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003ר' יוחנן: אין עושין שלש עיירות מנודחות בארץ ישראל, אבל עושין אותם שתים, כגון אחת ביהודה ואחת בגליל, אבל שתים ביהודה ושתים בגליל\u0004 — \u0003אין עושין. וסמוכה לספר\u0004 — \u0003אפילו אחת אין עושין. מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003שמא ישמעו גוים\u0004 שיש בספר עיר אחת שאין בה ישוב כלל \u0003ויחריבו את ארץ ישראל,\u0004 שיכנסו ללא הפרעה דרך מקום ריק זה.","ושואלים: \u0003ותיפוק ליה\u0004 \u0005[ויצא לו]\u0006 דין זה לא מטעם זה אלא משום גזירת הכתוב ש\u0003\"מקרבך\" אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 \u0003ולא מן הספר!\u0004 ומשיבים: תוספתא זו כשיטת \u0003ר' שמעון היא, דדריש טעמא דקרא\u0004 \u0005[ש\u0006הוא \u0005דורש\u0006 את \u0005טעם הכתוב],\u0006 ולדעתו זהו טעמו של הכתוב האומר שאין להרוס כלל עיר הנדחת שעל הספר.","שנינו במשנה ש\u0003סנהדרי גדולה היתה\u0004 של שבעים ואחד איש, ור' יהודה סבור כי היו בה רק שבעים, שמשה אסף רק שבעים מזקני ישראל ולא יותר. ושואלים: \u0003מאי טעמייהו דרבנן\u0004 \u0005[מה טעמם של חכמים]?\u0006 — \u0003דאמרי\u0004 \u0005[ש\u0006הם \u0005אומרים]\u0006 שאמנם נאמר שבעים איש, אבל \u0003משה על גביהן\u0004 ומצטרף עמם. \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"\u0004ויאמר ה' אל משה אספה לי שבעים איש מזקני ישראל אשר ידעת כי הם זקני העם ושוטריו ולקחת אותם אל אהל מועד \u0003והתיצבו שם\u0004"],["\u0003עמך\"\u0004 (במדבר יא, טז), משמעו: \u0003\"עמך\"\u0004 — \u0003ואת בהדייהו\u0004 \u0005[ואתה עמם].\u0006 הוה אומר: שבעים ואחד בסך הכל. \u0003ור' יהודה\u0004 סבור: \u0003\"עמך\"\u0004 אין כוונתו שמשה נמנה עם הזקנים, אלא \u0003משום שכינה\u0004 ששורה על משה, והוא צריך להיות עמם שהשכינה תשרה אף עליהם.","\u0003ורבנן\u0004 \u0005[וחכמים]\u0006 מה הם משיבים על טענה זו? \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"ונשאו אתך במשא העם\"\u0004 (במדבר יא, יז), ולדעתם כוונת הכתוב \u0003\"אתך\"\u0004 — \u0003ואת בהדייהו\u0004 \u0005[ואתה עמם]!\u0006 \u0003ור' יהודה\u0004 מבין זאת: \u0003\"אתך\"\u0004 כוונתו — \u0003בדומין לך,\u0004 כלומר, שמעלות שהיו במשה צריכות להיות (במידה מסויימת) גם באותם זקנים.","\u0003ורבנן\u0004 \u0005[וחכמים],\u0006 מהיכן לומדים דבר זה? — \u0003מ\u0004מה שנאמר במינוי שרי אלפים ושרי מאות לישראל \u0003\"והקל מעליך ונשאו אתך\"\u0004 (שמות יח, כב) \u0003נפקא\u0004 \u0005[יוצא]\u0006 דבר זה, ש\"אתך\" — בדומים לך. \u0003וילפא\u0004 \u0005[ולומדת]\u0006 \u0003סנהדרי גדולה\u0004 של שבעים \u0003מסנהדרי קטנה\u0004 שמינה משה את השופטים בכל שאר בתי הדינים.","כיון שהוזכר ענין מינוי הזקנים בידי משה, דנים בצדדים נוספים של אותו דבר. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 על הנאמר \u0003\"וישארו שני אנשים במחנה\u0004 שם האחד אלדד ושם השני מידד ותנח עליהם הרוח והמה בכתובים ולא יצאו האהלה ויתנבאו במחנה\u0003\"\u0004 (במדבר יא, כו), \u0003יש אומרים\u0004 כי \u0003בקלפי נשתיירו.\u0004 כיצד?","— \u0003שבשעה שאמר לו הקדוש ברוך הוא למשה \"אספה לי שבעים איש מזקני ישראל\"\u0004 (במדבר יא, טז), \u0003אמר משה: כיצד אעשה?\u0004 אם \u0003אברור ששה מכל שבט ושבט\u0004 — \u0003נמצאו\u0004 שבעים ושנים, ו\u0003שנים יתירים, אברור חמשה חמשה מכל שבט ושבט\u0004 — \u0003נמצאו\u0004 בסך הכל שישים, ו\u0003עשרה חסרים, אברור ששה משבט זה וחמשה משבט זה\u0004 — \u0003הריני מטיל קנאה בין השבטים,\u0004 שיטענו מדוע לא זכה שבטנו למספר נציגים כשבט אחר!","\u0003מה עשה?\u0004 — \u0003בירר ששה ששה\u0004 מכל שבט \u0003והביא שבעים ושנים פיתקין, על שבעים\u0004 מהם \u0003כתב \"זקן\", ושנים\u0004 מהם \u0003הניח חלק, בללן ונתנן בקלפי. אמר להם: בואו וטלו פיתקיכם! כל מי שעלה בידו\u0004 פתק שכתוב עליו \u0003\"זקן\", אמר\u0004 לו: \u0003כבר קידשך שמים. מי שעלה בידו חלק, אמר\u0004 לו: \u0003המקום לא חפץ בך, אני מה אעשה לך?\u0004","\u0003כיוצא בדבר,\u0004 כלומר, בשיטה דומה \u0003אתה אומר\u0004 שיש לפרש את הכתוב \u0003\"ולקחת חמשת חמשת שקלים לגלגלת\"\u0004 (במדבר ג, מז) הכתובים בענין פדיון הבכורים, שנאמר: \"קח את הלויים תחת כל בכור בבני ישראל... ואת פדויי השלושה והשבעים והמאתים העודפים על הלוים מבכור בני ישראל\" (במדבר מה–מו), \u0003אמר משה: כיצד אעשה להן לישראל? אם אומר לו\u0004 לבכור \u0003תן לי פדיונך\u0004 שאתה מהמאתיים והשבעים והשלושה העודפים, \u0003וצא\u0004 — \u0003יאמר לי: כבר פדאני בן לוי\u0004 מאותם עשרים ושנים אלף לויים שנותרו, ומנין אתה יודע שאני הוא מאלה שאינם פדויים?","\u0003מה עשה? הביא עשרים ושנים אלפים פיתקין, וכתב עליהן \"בן לוי\", ועל שלשה ושבעים ומאתים\u0004 הנותרים שהיו הבכורות יתרים על הלויים \u0003כתב עליהן \"חמשה שקלים\", בללן ונתנן בקלפי. אמר להן: טלו פיתקיכם. מי שעלה בידו \"בן לוי\", אמר לו: כבר פדאך בן לוי. מי שעלה בידו \"חמשת שקלים\", אמר לו: תן פדיונך וצא.\u0004 ואלדד ומידד היו אותם שני זקנים שהיו ראויים להיות נמנים על הסנהדרין, אבל העלו בידם פתק חלק.","\u0003ר' שמעון אומר: במחנה נשתיירו\u0004 ולא רצו לבוא להגרלה. \u0003בשעה שאמר לו הקדוש ברוך הוא למשה: \"אספה לי שבעים איש\", אמרו אלדד ומידד: אין אנו ראויין לאותה גדולה,\u0004 ואין אנו חשובים להימנות על הזקנים. \u0003אמר הקדוש ברוך הוא: הואיל ומיעטתם עצמכם, הריני מוסיף גדולה על גדולתכם\u0004 יותר משתהיה לשאר זקנים, \u0003ומה גדולה הוסיף להם?\u0004 — \u0003שהנביאים כולן,\u0004 כלומר, שאר הזקנים שניתנה להם נבואה, \u0003נתנבאו ופסקו, והם נתנבאו ולא פסקו.\u0004","כיון שהוזכר שהיו מתנבאים, שואלים: \u0003ומה נבואה נתנבאו?\u0004 — \u0003אמרו\u0004 (נתנבאו): \u0003משה מת, יהושע מכניס את ישראל לארץ. אבא חנין אומר משום\u0004 (בשם) \u0003ר' אליעזר: על עסקי שליו\u0004 שעתיד לבוא \u0003הן מתנבאים,\u0004 בלשון זו: \u0003\"עלי שליו, עלי שליו\",\u0004 ואכן בא השליו לאחר מכן!","\u0003רב נחמן אמר: על עסקי גוג ומגוג היו מתנבאין, שנאמר\u0004 לגבי גוג ומגוג: \u0003\"כה אמר ה' אלהים האתה הוא אשר דברתי בימים קדמונים ביד עבדי נביאי ישראל הנבאים בימים ההם שנים להביא אותך עליהם\"\u0004 (יחזקאל לח, יז), \u0003אל תיקרי \"שנים\" אלא שנים, ואיזו הן שנים נביאים שנתנבאו בפרק\u0004 (בזמן) \u0003אחד נבואה אחת?\u0004 — \u0003הוי אומר: אלדד ומידד\u0004 הם.","את דברי הברייתא הזו מבארים: \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003כל הנביאים כולן נתנבאו ופסקו, והן נתנבאו ולא פסקו.\u0004 ושואלים: \u0003מנא לן\u0004 \u0005[מנין לנו]\u0006 ש\u0003פסקו\u0004 שאר הנביאים? \u0003אילימא מדכתיב\u0004 \u0005[אם תאמר מ\u0006מה \u0005שנאמר\u0006 בהם\u0005]\u0006 \u0003\"ויתנבאו ולא יספו\"\u0004 (במדבר יא, כה), והכוונה היא שלא פסקו, \u0003אלא מעתה\u0004 מה שנאמר במתן תורה \u0003\"קול גדול ולא יסף\"\u0004 (דברים ה, יט), \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 אתה מפרש קול ש\u0003לא אוסיף\u0004 \u0005[הוסיף]\u0006 \u0003הוא?\u0004 והלא ממשמעות הכתובים שם רואים שנאמר הדבר בתוך עשרת הדברות, \u0003אלא\u0004 הכוונה שם ש\u0003לא פסק הוא.\u0004 ואם כן, אף כאן יכול אתה לפרש \"יסף\" במשמעות פסק ששבעים הזקנים לא פסקו מלהינבא!","\u0003אלא\u0004 הראיה בדרך אחרת: \u0003הכא כתיב\u0004 \u0005[כאן נאמר]\u0006 \u0003\"ויתנבאו\u0004 ולא יספו\u0003\"\u0004 (במדבר יא, כה), \u0003התם כתיב\u0004 \u0005[שם נאמר]\u0006 \"אלדד ומידד \u0003מתנבאים\u0004 במחנה\" (במדבר יא, כז), משמע \u0003עדיין מתנבאים והולכים.\u0004","ובבירור הדעות ביחס לתוכן נבואותיהם, \u0003בשלמא למאן ד\u0004\u0003אמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר]\u0006 שנבואתם היתה ש\u0003\"משה\u0004 \u0003מת\", היינו דכתיב\u0004 \u0005[זהו שנאמר]\u0006 שם: \u0003\"\u0004ויען יהושע בן נון משרת משה מבחוריו ויאמר \u0003אדני משה כלאם\"\u0004 (במדבר יא, כח), שנראה הדבר כמרידה בסמכותו של משה. \u0003אלא למאן ד\u0004\u0003אמר הנך תרתי\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר אותם שתים]\u0006 נבואות אחרות, שאין בהן נגיעה למשה, \u0003מאי\u0004 \u0005[מה\u0006 טעם\u0005]\u0006 אמר יהושע \u0003\"אדני משה כלאם\"?\u0004 ומסבירים: \u0003דלאו אורח ארעא\u0004 \u0005[שאין\u0006 זה \u0005דרך ארץ]\u0006 שיתנבאו לעצמם, \u0003דהוה ליה\u0004 \u0005[שהרי הם]\u0006 \u0003כתלמיד המורה הלכה לפני רבו,\u0004 שיש צד חוצפה בזה, וכן בנביאים המתנבאים שלא ברשות רבם.","ושואלים: \u0003בשלמא למאן דאמר הנך תרתי\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר\u0006 שנבאו \u0005אלה השנים]\u0006 על דברים לעתיד — \u0003היינו דכתיב\u0004 \u0005[זהו שנאמר]:\u0006 \"ויאמר לו משה המקנא אתה לי ו\u0003מי יתן\u0004 כל עם ה' נביאים\" (במדבר יא, כט), \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 שנבאו ש\u0003\"משה מת\u0004 ויהושע מכניס את ישראל לארץ\", \u0003מינח הוה ניחא ליה\u0004 \u0005[נוח היה לו בכך]\u0006 שכל עם ה' יהיו נביאים כיוצא בזה?! ומשיבים: \u0003לא סיימוה קמיה\u0004 \u0005[סיימוהו\u0006 לאותו הדבר \u0005לפניו]\u0006 ולא סיפרו למשה מה אמרו, אלא אמרו לו רק שהם מתנבאים.","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 משמע\u0005]\u0006 \u0003\"כלאם\"\u0004 שאמר יהושע? ומפרשים, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הטל עליהן צרכי ציבור\u0004 שיתעסקו בהם כשאר זקני ישראל, \u0003והן כלין מאיליהן\u0004 שאינם יכולים להמשיך בנבואה, שמתוך טורח הציבור לא יוכלו להיות גם נביאים.","שנינו במשנה: \u0003מניין להביא עוד שלשה.\u0004 במשנה מוכיחים שמספר הדיינים בסנהדרי קטנה הוא עשרים ושלושה, שהרי אין לחייב אדם למוות ברוב של דיין אחד בלבד, ומשום כך יש להוסיף לעשרים חברי הסנהדרי עוד שנים, וכדי שלא יהא בית דין שקול מוסיפים עוד אחד והרי עשרים ושלושה.","ומקשים: \u0003סוף סוף לרעה על פי שנים לא משכחת לה\u0004 \u0005[אין אתה מוצא אותה]\u0006 הזדמנות גם בעשרים ושלושה, כיצד? \u0003אי\u0004 \u0005[אם]\u0006 \u0003אחד עשר מזכין ושנים עשר מחייבין, אכתי חד הוא\u0004 \u0005[עדיין אחד הוא]\u0006 ואין כאן רוב של שנים, \u0003אי\u0004 \u0005[אם]\u0006 \u0003עשרה מזכין ושלשה עשר מחייבין, תלתא הוו\u0004 \u0005[שלושה הם]\u0006 ולא שנים, ושוב אין קיום הכתוב כלשונו! \u0003אמר ר' אבהו: אי\u0004 (אין) \u0003אתה מוצא\u0004 שיהא רוב של שנים \u0003אלא במוסיפין,\u0004 כשמוסיפים שני דיינים נוספים כשאחד מן הדיינים נמנע מן הדיון, ושאר הדיינים היו שקולים בדעותיהם, ושני אלה הצטרפו לדעה אחת, \u0003ו\u0004דבר זה הוא ל\u0003דברי הכל. ובסנהדרי גדולה\u0004 יכול שיארע בה דבר כעין זה, \u0003ואליבא\u0004 \u0005[ולשיטתו]\u0006 של \u0003ר' יהודה\u0004 ש\u0003אמר שבעים\u0004 הם חברי סנהדרי גדולה, ובמספר זוגי של אנשים יתכן שיהא רוב של שנים לחייב.","\u0003ואמר ר' אבהו: במוסיפין\u0004 כשמצריכים להוסיף לדיינים \u0003עושין בית דין שקול\u0004 אפילו \u0003לכתחילה.\u0004 ומקשים: \u0003פשיטא\u0004 \u0005[פשוט\u0006 הדבר\u0005],\u0006 הלא כך מובן מן המקורות, ומה החידוש בזה? ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003האי דקאמר\u0004 \u0005[זה שאמר]\u0006 \u0003\"איני יודע\" כמאן דאיתיה דמי\u0004 \u0005[כמי שישנו נחשב],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003אמר מילתא\u0004 \u0005[דבר]\u0006 אחר כך — \u0003שמעינן ליה\u0004 \u0005[שומעים אנו לו]\u0006 ומצרפים אף אותו למנין, ונמצא שיש מספר בלתי זוגי של דיינים, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 \u0003דהאי דקאמר\u0004 \u0005[שזה שאמר]\u0006 \u0003\"איני יודע\" כמאן דליתיה דמי\u0004 \u0005[כמי שאיננו\u0006 הוא \u0005נחשב],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003אמר טעמא\u0004 \u0005[טעם]\u0006 — \u0003לא שמעינן ליה\u0004 \u0005[אין אנו שומעים לו],\u0006 ולכן בית הדין הוא בלעדיו כבית דין שקול.","\u0003אמר רב כהנא: סנהדרי שראו כולן\u0004 דינו של אדם \u0003לחובה\u0004 — \u0003פוטרין אותו.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 — \u0003כיון דגמירי\u0004 \u0005[שלמדנו]\u0006 שיש צורך לעשות \u0003הלנת דין\u0004 שלא יפסקו דינו בו ביום כדי \u0003למעבד ליה זכותא\u0004 \u0005[לעשות,\u0006 למצוא, \u0005לו זכות]\u0006 לנידון, שמא במשך הלילה יעלו דבר מה בדעתם, \u0003והני תו\u0004 \u0005[ואלה\u0006 שכולם ראו לחובה \u0005שוב]\u0006 \u0003לא חזו ליה\u0004 \u0005[יראו לו\u0006 זכות\u0005],\u0006 שהרי לא יהיה מי שיהפך לזכותו.","\u0003אמר ר' יוחנן: אין מושיבין בסנהדרי אלא בעלי קומה\u0004 גבוהה, \u0003ובעלי חכמה, ובעלי מראה\u0004 (יפי תואר), \u0003ובעלי זקנה\u0004 שיכבדום אף מפני זקנתם, \u0003ו\u0004יהיו \u0003בעלי כשפים\u0004 שיהיו יודעים מה טיבו של כישוף אם יזדמן להם לדון במכשפים, \u0003ויודעים בשבעים לשון\u0004 כדי \u0003שלא תהא סנהדרי שומעת מפי המתורגמן\u0004 כשבאים עדים המדברים בשפה אחרת.","\u0003אמר רב יהודה אמר רב: אין מושיבין בסנהדרין אלא מי שיודע לטהר את השרץ מן התורה,\u0004 כלומר, אף שבתורה נאמר במפורש שהשרץ טמא הוא, צריכים בסנהדרין חכם מפולפל כל כך, שיוכל להוכיח מן הכתובים האחרים שהשרץ טהור. ורק חכם חריף עד כדי כך ראוי להיות בסנהדרין. ואגב הדברים \u0003אמר רב: אני אדון ואטהרנו,\u0004 כלומר, אני יכול להראות כיצד אפשר להוכיח הוכחה כזו:"],["\u0003ומה נחש ש\u0004הוא עצמו \u0003ממית ומרבה\u0004 על ידי כך \u0003טומאה,\u0004 בכל זאת \u0003טהור\u0004 נבלתו ואינו מטמא (שהרי אינו כלול ברשימת השרצים המטמאים), \u0003שרץ שאינו ממית ו\u0004אינו \u0003מרבה טומאה, אינו דין שיהא טהור?!\u0004 אם כן למדנו מקל וחומר שהשרץ טהור. את ה\"הוכחה\" הזו דוחים: \u0003ולא היא\u0004 (ואינו כן), \u0003מידי דהוה\u0004 \u0005[כמו ש\u0006הדבר \u0005הוא]\u0006 ב\u0003קוץ בעלמא\u0004 \u0005[סתם],\u0006 שאף הקוץ פעמים פוצע ועלול אף להמית ולהוסיף טומאה, ואין אומרים שיהא טמא בשל כך. משמע שאין טומאת עצמו קשורה בשיקול זה כלל.","\u0003אמר רב יהודה אמר רב: כל עיר שאין בה שנים\u0004 שיודעים \u0003לדבר\u0004 בשבעים לשון, \u0003ואחד\u0004 שיודע \u0003לשמוע\u0004 (להבין) — \u0003אין מושיבין בה סנהדרי,\u0004 משום שאמנם כל חברי הסנהדרין אינם צריכים לדעת כל הלשונות, אבל לפחות צריכים להיות שנים כאלה. \u0003ובביתר הוו\u0004 \u0005[היו]\u0006 \u0003שלשה\u0004 שהיו בקיאים בכל השפות, \u0003וביבנה\u0004 היו \u0003ארבעה\u0004 כאלה, והם: \u0003ר' אליעזר, ור' יהושע, ור' עקיבא, ושמעון התימני\u0004 שלא נסמך, היה \u0003דן לפניהם בקרקע\u0004 שלא בשורת החכמים.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו בברייתא: \u0003שלישית,\u0004 כלומר, סנהדרין שיש בה שלושה כאלה — היא סנהדרין \u0003חכמה, רביעית\u0004 — \u0003אין למעלה הימנה,\u0004 כלומר, אין צורך ביותר, ואולם משמע שצריכים להיות שלושה ולא רק שנים! ומשיבים: \u0003הוא,\u0004 רב יהודה בשם רב, ש\u0003אמר\u0004 דבריו, אמרם \u0003כי האי תנא\u0004 \u0005[כ\u0006שיטת \u0005תנא זה],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא אחרת\u0005]:\u0006 \u0003שניה\u0004 — \u0003חכמה, שלישית\u0004 — \u0003אין למעלה הימנה.\u0004","כיון שהזכרנו קודם ששמעון התימני היה דן לפניהם בקרקע, מביאים כמה מן הכינויים המקובלים שהיו לחכמים במשך הדורות. כאשר נאמר \u0003\"למידין לפני חכמים\"\u0004 — הכוונה היא שהיה זה החכם \u0003לוי\u0004 שישב לפני \u0003רבי\u0004 (ר' יהודה הנשיא). כשאומרים \u0003\"דנין לפני חכמים\"\u0004 הרי הם \u0003שמעון בן עזאי, ושמעון בן זומא, וחנן המצרי, וחנניא בן חכינאי.\u0004 ואילו \u0003רב נחמן בר יצחק מתני\u0004 \u0005[היה שונה]\u0006 כאן \u0003חמשה\u0004 שמות: \u0003שמעון\u0004 בן עזאי, \u0003שמעון\u0004 בן זומא, \u0003ושמעון\u0004 התימני, \u0003חנן\u0004 המצרי, \u0003וחנניה\u0004 בן חכינאי.","כשאומרים בתלמוד \u0003\"רבותינו שבבבל\"\u0004 הכוונה היא ל\u0003רב ושמואל.\u0004 כשאומרים \u0003\"רבותינו שבארץ ישראל\"\u0004 הכוונה היא ל\u0003ר' אבא.\u0004 אם נאמר \u0003\"דייני גולה\"\u0004 — הרי זה כינוי לחכם \u0003קרנא.\u0004 אם אומרים \u0003\"דייני דארץ ישראל\"\u0004 הרי אלה \u0003ר' אמי ור' אסי.\u0004 כשמזכירים את \u0003\"דייני דפומבדיתא\"\u0004 מדובר על \u0003רב פפא בר שמואל\u0004 העומד בראשם. \u0003\"דייני דנהרדעא\"\u0004 כוונתו לבית דין שבראשו עומד \u0003רב אדא בר מניומי. \"סבי\u0004 \u0005[זקני]\u0006 \u0003דסורא\"\u0004 הם \u0003רב הונא ורב חסדא. \"סבי\u0004 \u0005[זקני]\u0006 \u0003דפומבדיתא\"\u0004 הם \u0003רב יהודה ורב עינא.\u0004 אם מדברים על \u0003\"חריפי\u0004 \u0005[החריפים]\u0006 \u0003דפומבדיתא\"\u0004 הלא הם \u0003עיפה ואבימי בני רחבה.\u0004 וכשנזכרים \u0003\"אמוראי\u0004 \u0005[אמוראים]\u0006 \u0003דפומבדיתא\"\u0004 הרי הם \u0003רבה ורב יוסף. \"אמוראי\u0004 \u0005[אמוראים]\u0006 \u0003דנהרדעי\"\u0004 הכוונה ל\u0003רב חמא.\u0004","אם נאמר \u0003\"נהרבלאי מתנו\u0004 \u0005[שנו]\u0006 \u0003\"\u0004הכוונה היא ל\u0003רמי בר ברבי.\u0004 אם אומרים בתלמוד \u0003\"אמרי בי\u0004 \u0005[אומרים\u0006 בני \u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003רב\"\u0004 הכוונה היא ל\u0003רב הונא.\u0004 ומקשים: \u0003והאמר\u0004 \u0005[והרי\u0006 במקום אחד יודעים \u0005שאמר]\u0006 \u0003רב הונא: אמרי בי\u0004 \u0005[אומרים\u0006 בני \u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003רב,\u0004 משמע שרב הונא אינו זהה עם חכמי בית רב! \u0003אלא\u0004 \"אמרי בי רב\" הוא \u0003רב המנונא.\u0004 סתם \u0003\"אמרי במערבא\"\u0004 \u0005[אומרים בארץ ישראל]\u0006 הוא מדברי \u0003ר' ירמיה,\u0004 אם נאמר סתם \u0003\"שלחו מתם\u0004 \u0005[משם,\u0006 מארץ ישראל\u0005]\u0006 \u0003\",\u0004 הוא \u0003ר' יוסי בר חנינא.\u0004 ואם נאמר בתלמוד \u0003\"מחכו עלה במערבא\u0004 \u0005[צוחקים על דבר זה בארץ ישראל]\u0006 \u0003\"\u0004מתכוונים ל\u0003ר' אלעזר,\u0004 כשלא קיבל דעה מסויימת.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003שלחו מתם\u0004 \u0005[משם]\u0006 \u0003לדברי ר' יוסי בר חנינא\u0004 ההלכה היא כך וכך, משמע \"ששלחו מתם\" אינו ר' יוסי בר' חנינא עצמו! \u0003אלא איפוך\u0004 \u0005[הפוך\u0006 את הדברים\u0005],\u0006 ואמור כי \u0003\"שלחו מתם\u0004 \u0005[משם]\u0006 \u0003\"\u0004כוונתו ל\u0003ר' אלעזר. \"מחכו עלה במערבא\u0004 \u0005[צוחקים על דבר זה בארץ ישראל]\u0006 \u0003\"\u0004הוא \u0003ר' יוסי בר חנינא.\u0004","במשנה נידונה השאלה: \u0003וכמה\u0004 אנשים \u0003יהא\u0004 צריכים להיות \u0003בעיר\u0004 כדי ש\u0003תהא ראויה\u0004 שיעשו בה \u0003סנהדרין?\u0004 ושיטת חכמים היא שצריכים \u0003מאה ועשרים.\u0004 שואלים: \u0003מאה ועשרים מאי עבידתייהו\u0004 \u0005[מה מעשיהם]?\u0006 כלומר, מה טעמו של מספר זה? ומסבירים: \u0003עשרים ושלשה\u0004 צריך \u0003כנגד\u0004 מספר \u0003סנהדרי קטנה, ושלש שורות של עשרים ושלשה\u0004 תלמידים היושבים לפניהם ללמוד ופעמים גם ליעץ — \u0003הרי\u0004 בסך הכל \u0003תשעים ותרתי\u0004 \u0005[ושנים]\u0006 איש, \u0003ו\u0004עוד צריכים שיהיו בעיר \u0003עשרה בטלנין של בית הכנסת,\u0004 כלומר, אנשים הפנויים מעבודות דוחקות, ויושבים תמיד בבית הכנסת ודואגים לתיקונו ולשאר צרכי הציבור — \u0003הרי מאה ותרי\u0004 \u0005[ושנים].\u0006","\u0003ושני סופרים\u0004 בסנהדרין, \u0003ושני חזנין\u0004 (שמשים), \u0003ושני בעלי דינין\u0004 שיבואו להתדיין, \u0003ושני עדים\u0004 לצד אחד, \u0003ושני זוממין\u0004 שיאמרו שעדים ראשונים אלה לא היו בשעת המעשה, \u0003ושני זוממי זוממין\u0004 שיוכלו להכחיש את העדים המזימים. וכל זאת כדי שיוכל להתקיים דיון כפי שהוא מתואר בפרשת המשפט בספר דברים (יט, טו—כא) — \u0003הרי\u0004 בסך הכל \u0003מאה וארביסר\u0004 \u0005[וארבעה עשר]\u0006 איש בעיר.","\u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]:\u0006 \u0003כל עיר שאין בה עשרה דברים הללו אין תלמיד חכם רשאי לדור בתוכה,\u0004 ואלו הם: \u0003בית דין מכין ועונשין, וקופה של צדקה\u0004 ה\u0003נגבית\u0004 כפי הדין \u0003בשנים\u0004 (שני אנשים הממונים על כך) \u0003ומתחלקת\u0004 על פי \u0003שלשה,\u0004 אם כן לגבאי צדקה יש צורך בעוד שלושה אנשים — הרי מאה ושבעה עשר. \u0003ו\u0004יש צורך שיהא בעיר \u0003בית הכנסת, ובית המרחץ, ובית הכסא, רופא ואומן\u0004 (מקיז דם) שהוא כעין חובש עוזר לרופא המומחה, \u0003ולבלר\u0004 (סופר) לכתוב ספרי קודש ושטרות נחוצים, \u0003וטבח\u0004 (שוחט) \u0003ומלמד תינוקות\u0004 — הרי בסך הכל מאה ועשרים איש. \u0003משום\u0004 (בשם) \u0003ר' עקיבא אמרו:\u0004 צריך שיהיו בעיר שתלמיד חכם ראוי לדור בה \u0003אף מיני פירא\u0004 \u0005[פירות],\u0006 \u0003מפני שמיני פירא\u0004 \u0005[פירות]\u0006 \u0003מאירין את העינים.\u0004","במשנה שנינו ש\u0003ר' נחמיה אומר:\u0004 צריכים להיות בעיר מאתים ושלושים איש, כדי שתהא ראויה לסנהדרין, כנגד שרי עשרות. \u0003תניא\u0004 \u0005[שנינו\u0006 בתוספתא\u0005]\u0006 גם שיטה אחרת, \u0003רבי אומר:\u0004"],["\u0003מאתים ושבעים ושבעה,\u0004 שהוא מכיל את עיקר שיטתו של ר' נחמיה שצריכים להיות בעיר מאתים ושלושים, אלא שיש להוסיף עוד אנשים כדי להשלים את מספר דייני בית הדין לשבעים, שאם יקרה שחכמי בית דין יגיעו למצב שאינם יכולים להכריע בדין ויוסיפו זוגות זוגות דיינים, הרי צריך שתהיה אפשרות להוסיף עד שבעים.","ושואלים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 אחרת ש\u0003רבי אומר: מאתים שבעים ושמנה!\u0004 ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זו]\u0006 שאמר מאתים שבעים ושבעה — הרי זה כשיטת \u0003ר' יהודה,\u0004 שיש רק שבעים דיינים בסנהדרי גדולה. \u0003הא\u0004 \u0005[זו]\u0006 שאמר מאתים שבעים ושמונה — כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 שיש שבעים ואחד. ולכן יש להוסיף עוד אחד.","אגב שהובאה שיטת ר' נחמיה במינוי שררות בישראל \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר \u0003\"ושמת עליהם שרי אלפים שרי מאות שרי חמשים ושרי עשרת\"\u0004 (שמות יח, כא), ומסבירים שכך היו מספריהם: \u0003שרי אלפים\u0004 היו \u0003שש מאות\u0004 (לשש מאות אלף איש), \u0003שרי מאות\u0004 היו \u0003ששת אלפים, שרי חמשים\u0004 — \u0003שנים עשר אלף, שרי עשרות\u0004 — \u0003ששת ריבוא\u0004 (שישים אלף), \u0003נמצאו דייני ישראל\u0004 כולם \u0003שבעת ריבוא\u0004 (שבעים אלף) \u0003ושמונת אלפים ושש מאות,\u0004 ללמד שלכל התפקידים נמצאו אנשים המסוגלים למלא אותם.","","\u0003כהן גדול דן\u0004 אם ראוי הוא מצד חכמתו להיות דיין, \u0003ודנין אותו\u0004 כשעבר עבירה. וכן הוא \u0003מעיד\u0004 לפני בית דין \u0003ו\u0004אף \u0003מעידין אותו\u0004 כשיש להעיד על דברים הנוגעים אליו. \u0003חולץ\u0004 לאשת אחיו שמת בלא בנים, \u0003וחולצין לאשתו\u0004 אם מת הוא בלא בנים, \u0003ו\u0004אם מת בלא בנים אף \u0003מייבמין את אשתו\u0004 אם אחיו רוצה לעשות כן. \u0003אבל הוא אינו מייבם\u0004 את אשת אחיו שמת בלא בנים, \u0003מפני שהוא אסור באלמנה,\u0004 ולעולם אינו יכול לקיים מצות יבום שהרי היבמה היא בהכרח אלמנה.","אם \u0003מת לו מת\u0004 מקרוביו, כיון שלכהן הגדול אסור להיטמא אף לבני משפחתו, \u0003אינו יוצא אחר המטה\u0004 שבה המת מיד, \u0003אלא הן,\u0004 המלווים, \u0003נכסין\u0004 מן העין כשנכנסים לרחוב אחר, \u0003ו\u0004אז \u0003הוא נגלה\u0004 באותו רחוב, \u0003הן נגלין והוא נכסה, ו\u0004כך \u0003יוצא עמהן עד פתח שער העיר\u0004 ומשם מוציאים את המת, שלא היו קוברים מתים בירושלים, אלו \u0003דברי ר' מאיר.\u0004","","","","\u0003ר' יהודה אומר: אינו יוצא מן המקדש\u0004 כלל בזמן הלווית קרוביו, \u0003משום שנאמר: \"ומן המקדש לא יצא\u0004 ולא יחלל את מקדש אלהיו כי נזר שמן משחת אלהיו עליו\u0003\"\u0004 (ויקרא כא, יב). \u0003וכשהוא מנחם אחרים\u0004 באבלם כשחוזרים מלקבור את המת, \u0003דרך כל העם עוברין בזה אחר זה\u0004 והאבלים עומדים בשורה ומתנחמים, \u0003והממונה ממצעו\u0004 (עומד באמצע) \u0003בינו לבין העם. וכשהוא מתנחם מאחרים\u0004 כאשר הוא באבל, \u0003כל העם אומרים לו: \"אנו כפרתך\", והוא אומר להן: \"תתברכו מן השמים\". וכשמברין אותו\u0004 סעודת הבראה לאחר שמת אחד מקרוביו, \u0003כל העם מסובין על הארץ\u0004 כמקבלים על עצמם אבלותו, \u0003והוא מיסב על הספסל\u0004 מפני כבוד כהונתו. בדיני המלך יש דינים דומים ושונים מאלה של הכהן הגדול. \u0003המלך לא דן\u0004 בסנהדרין \u0003ולא דנין אותו, לא מעיד ולא מעידין אותו, לא חולץ ולא חולצין לאשתו, לא מייבם ולא מייבמין לאשתו,\u0004 שכל אלה אינם כבוד לו. \u0003ר' יהודה אומר:\u0004 דבר זה איננו גזירה אלא דבר רשות הוא, \u0003אם רצה לחלוץ או לייבם\u0004 — \u0003זכור לטוב,\u0004 ששחרר אשת אחיו מן העיגון. \u0003אמרו לו: אין שומעין לו,\u0004 שאין זה כבוד עצמו בלבד אלא כבוד המלכות. \u0003ואין נושאין אלמנתו\u0004 של המלך משום כבודו. \u0003ר' יהודה אומר: נושא המלך\u0004 הבא \u0003אלמנתו של מלך\u0004 אם אין איסור בכך מצד אחר, \u0003שכן מצינו בדוד שנשא אלמנתו של שאול, שנאמר: \"ואתנה לך את בית אדניך ואת נשי אדניך בחיקך\"\u0004 (שמואל ב' יב, ח), הרי שמותר הדבר.","שנינו במשנה ש\u0003כהן גדול דן.\u0004 ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 ומדוע נחשוב שיהא פסול לדון? ומשיבים: \u0003\"דנין אותו\" איצטריכא ליה\u0004 \u0005[נצרכה לו\u0006 לומר\u0005],\u0006 שבכך יש חידוש. ואומרים \u0003הא נמי פשיטא\u0004 \u0005[זה גם כן פשוט],\u0006 שכן \u0003אי לא דיינינן ליה\u0004 \u0005[אם אין אנו דנים אותו],\u0006 \u0003איהו היכי דיין\u0004 \u0005[הוא כיצד דן]?\u0006 \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"התקוששו וקושו\"\u0004 (צפניה ב, א), \u0003ואמר ריש לקיש,\u0004 פסוק זה מרמז לכלל מוסרי ומשפטי: \u0003קשט עצמך\u0004 תחילה, \u0003ואחר כך קשט אחרים,\u0004 ומכאן גם שמי שאינו יכול להיות נידון אף אינו רשאי להיות דיין, ואם כן אין בכך חידוש!","\u0003אלא\u0004 אומרים \u0003איידי\u0004 \u0005[על ידי,\u0006 מתוך\u0005]\u0006 \u0003דקא בעי למיתני\u0004 \u0005[שהוא רוצה לשנות]\u0006 בהמשך שה\u0003מלך לא דן ולא דנין אותו, תנא נמי\u0004 \u0005[שנה גם כן]\u0006 שה\u0003כהן גדול דן ודנין\u0004 אותו. \u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הסבר אחר: \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו],\u0006 \u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בתוספתא\u0005]:\u0006 \u0003כהן גדול שהרג את הנפש במזיד\u0004 — \u0003נהרג,\u0004 ואם \u0003בשוגג\u0004 — \u0003גולה, ועובר על\u0004 מצות \u0003\"עשה\" ועל\u0004 מצות \u0003\"לא תעשה\", והרי הוא כהדיוט לכל דבריו.\u0004","ומעתה מבארים את דברי התוספתא: \u0003במזיד נהרג, פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]!\u0006 ומדוע יהא דינו שונה משל כל אדם בישראל? ומשיבים: \u0003בשוגג גולה איצטריכא ליה\u0004 \u0005[צריך\u0006 היה \u0005לו\u0006 להשמיענו\u0005].\u0006","ותוהים: \u0003הא נמי פשיטא\u0004 \u0005[\u0006דבר \u0005זה גם כן פשוט]!\u0006 ומשיבים: \u0003איצטריך\u0004 \u0005[נצרך\u0006 הדבר\u0005]\u0006 להיאמר, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל וכתיב\u0004 \u0005[הואיל ונאמר]\u0006 לגבי מי שהרג בשגגה וגולה לעיר מקלט \u0003\"וישב בה עד מות הכהן הגדל\"\u0004 (במדבר לה, כה), \u0003אימא\u0004 \u0005[אמור]:\u0006 \u0003כל דאית ליה תקנתא\u0004 \u0005[שיש לו תקנה]\u0006 \u0003בחזרה\u0004 — \u0003ליגלי\u0004 \u0005[שיגלה],\u0006 \u0003דלית ליה תקנתא\u0004 \u0005[שאין לו תקנה]\u0006 \u0003בחזרה\u0004 — \u0003לא ליגלי\u0004 \u0005[יגלה],\u0006 והכהן הגדול אין לו תקנה זו, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006"],["\u0003ההורג כהן גדול, או כהן גדול שהרג את הנפש\u0004 — \u0003אינו יוצא משם,\u0004 ממקום גלותו, \u0003לעולם,\u0004 שכיון שבאותה שעה אין כהן גדול משמש, אין לו תקנה במותו של הכהן הגדול שיתמנה תחתיו, ומשום כך \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא ליגלי\u0004 \u0005[יגלה]\u0006 כלל, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שגולה. ושואלים: \u0003ואימא הכי נמי\u0004 \u0005[ואמור\u0006 ש\u0005כך הוא גם כן]\u0006 הדין וכהן גדול אכן לא יגלה? ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 שערי המקלט נועדו \u0003\"לנוס שמה כל רצח\"\u0004 (דברים יט, ג), \"כל\" לרבות \u0003אפילו כהן גדול במשמע.\u0004","שנינו בתוספתא שכהן גדול שהרג את הנפש במזיד \u0003עובר על\u0004 מצות \u0003\"עשה\" ועל\u0004 מצות \u0003\"לא תעשה\".\u0004 ותוהים על סגנון זה: וכי \u0003לא סגי דלא עבר\u0004 \u0005[וכי אין די שאינו עובר],\u0006 וכי חייב הוא לעבור על מצות \"עשה\" ועל \"לא תעשה\"? ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר,\u0006 כך יש להבין\u0005]:\u0006 \u0003אם עבר על \"עשה\" ועל \"לא תעשה\"\u0004 — \u0003הרי הוא כהדיוט לכל דבריו.\u0004","ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]!\u0006 ומשיבים: \u0003סלקא דעתך אמינא\u0004 \u0005[עולה על דעתך לומר],\u0006 \u0003הואיל ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]:\u0006 \u0003אין דנין לא את השבט ולא את נביא השקר, ולא את\u0004 ה\u0003כהן\u0004 ה\u0003גדול אלא על פי בית דין של שבעים ואחד. ואמר רב אדא בר אהבה\u0004 מקור לדין זה בכהן גדול: \u0003\"כל הדבר הגדל יביאו אליך\"\u0004 (שמות יח, כב), שפירשו: \u0003דבריו של גדול,\u0004 שגדול בישראל ככהן גדול, נידון בבית דין של שבעים ואחד, \u0003אימא\u0004 \u0005[אמור]\u0006 שהכוונה היא \u0003כל דבריו של גדול,\u0004 ואפילו נידון על עבירה שאין עונשה מיתה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 על שאר דברים שהריהו כהדיוט, ונידון אף בבית דין של שלושה.","ושואלים: \u0003ואימא הכי נמי\u0004 \u0005[ואמור\u0006 ש\u0005כך\u0006 הוא \u0005גם כן]\u0006 ויהיו כל דיניו בשבעים ואחד! ודוחים: \u0003מי כתיב\u0004 \u0005[האם נאמר]\u0006 \u0003\"דברי גדול\"? \"הדבר הגדל\" כתיב\u0004 \u0005[נאמר],\u0006 משמע: \u0003דבר גדול ממש,\u0004 כלומר, שזה דבר הקשור באדם גדול בישראל וגם בעונש גדול.","שנינו במשנה כי הכהן הגדול \u0003מעיד ומעידין אותו.\u0004 ותוהים: \u0003מעיד? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 על הכתוב במצות השבת אבידה \"לא תראה את שור אחיך או את שיו נדחים והתעלמת מהם השב תשיבם לאחיך\" (דברים כב, א), שמשינוי הסגנון שלא נאמר בו \"לא תתעלם\" נרמזת האפשרות של \u0003\"והתעלמת\",\u0004 ולמדו מכאן להלכה: \u0003פעמים שאתה מתעלם\u0004 מן האבידה \u0003ופעמים שאי\u0004 (אין) \u0003אתה מתעלם. הא\u0004 \u0005[הרי]\u0006 \u0003כיצד?\u0004","— היה המוצא \u0003כהן, והוא,\u0004 האבידה, \u0003בבית הקברות,\u0004 ואין הכהן רשאי להיכנס לשם, או שהיה המוצא \u0003זקן\u0004 וחשוב, \u0003ואינה\u0004 מסוג כזה שתהא \u0003לפי כבודו\u0004 לטלטלה ולטפל בה, \u0003או שהיתה מלאכה שלו מרובה משל חבירו\u0004 ונמצא מפסיד הרבה בטיפול באבידה זו, \u0003לכך נאמר \"והתעלמת\"!\u0004 ומהלכה זו אפשר ללמוד כי משום כבודו של אדם מתירים לו להתעלם ממצוה החלה על אחרים, ואף נאמר שמפני כבודו יכול הוא להתעלם מחובת העדות!","\u0003אמר רב יוסף:\u0004 כהן גדול \u0003מעיד למלך,\u0004 שבעדות כזו ודאי אין משום חילול כבודו. ומקשים: \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]\u0006 שהמלך \u0003לא דן ולא דנין אותו, לא מעיד ולא מעידין אותו,\u0004 ואם כן אין אפשרות להעיד למלך? \u0003אלא אמר ר' זירא:\u0004 הכוונה ש\u0003מעיד לבן מלך,\u0004 שאין דינו כמלך לענין שאינו נידון. ומקשים: \u0003בן מלך הדיוט הוא,\u0004 שכל עוד אינו מלך הוא ככל האדם ואין לו דין מיוחד, ואין מכבוד הכהן הגדול להעיד לו!","\u0003אלא\u0004 הכוונה היא שהוא \u0003מעיד בפני המלך\u0004 כאשר המלך יושב בבית הדין, ומפני כבוד המלכות שוב אין בכך ירידה בכבוד של הכהן הגדול כאשר הוא מעיד. ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 שנינו ש\u0003אין מושיבין מלך בסנהדרין!\u0004 ומסבירים שיש כאן רק סידור מיוחד ש\u0003משום יקרא\u0004 \u0005[כבודו]\u0006 של ה\u0003כהן\u0004 ה\u0003גדול אתא ויתיב\u0004 \u0005[בא\u0006 המלך \u0005ויושב]\u0006 בין הדיינים, ואז \u0003מקבלי ניהלי לסהדותיה\u0004 \u0005[מקבלים את עדותו]\u0006 של הכהן הגדול, ואחר כך \u0003קאי\u0004 \u0005[עומד]\u0006 \u0003הוא,\u0004 המלך, \u0003ואזיל ומעיינינא ליה אנן בדיניה\u0004 \u0005[והולך, ומעיינים אנו\u0006 הדיינים \u0005בדינו].\u0006","כיון שהוזכרה הלכה זו, מעירים: \u0003גופא\u0004 \u0005[לגופה]\u0006 של אותה הלכה אמרנו ש\u0003אין מושיבין מלך בסנהדרין, ולא מלך וכהן גדול\u0004 בבית הדין הדן \u0003בעיבור\u0004 ה\u0003שנה.\u0004 ומסבירים: לענין אי הכללת \u0003מלך בסנהדרין,\u0004 הטעם הוא \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"לא תענה על רב\"\u0004 (שמות כג, ב), והוא נדרש \u0003לא תענה על רב\u0004 (גדול), שאין ראוי להושיב בסנהדרין אדם כזה ששאר הדיינים יחששו להביע דעה הנוגדת את דעתו.","ולענין \u0003לא מלך וכהן גדול בעיבור שנה: מלך\u0004 אין דן — \u0003משום אפסניא,\u0004 הספקת מזון ומשכורת לצבא, שאין המלך מעוניין בתוספת חודש לשנה, שהוא הוספה גדולה בהוצאותיו. \u0003כהן גדול\u0004 — \u0003משום צינה\u0004 הוא מעונין שהטבילות שהוא טובל ביום הכיפורים ורצפת המקדש (שהרי הוא עובד יחף) יהיו חמים ככל האפשר. ויש לו גם נגיעה בשאלת העיבור שהרי רצונו שיהא יום הכיפורים בעונת שנת חמה.","\u0003אמר רב פפא: שמע מינה, שתא בתר ירחא אזיל\u0004 \u0005[למד מכאן\u0006 ש\u0005השנה הולכת אחר החדשים]\u0006 כלומר, שכל השינויים הקשורים במזג האויר, בהבשלת הפירות וכיוצא בהם, כולם תלויים בתקופת השנה ומשתנים עמה. שהרי הכהן הגדול רוצה שלא תהא צינת מרחשון בתשרי על ידי העיבור. ושואלים: \u0003איני\u0004 \u0005[וכי כן הוא]?\u0006 \u0003והא הנך\u0004 \u0005[והרי אותם]\u0006 \u0003שלשה רועי בקר דהוו קיימי\u0004 \u0005[שהיו עומדים]\u0006 פעם במקום אחד, \u0003ושמעינהו רבנן דקאמרי\u0004 \u0005[ושמעו אותם חכמים שהם אומרים]\u0006 ומדברים בסימני מזג האויר של השנה,","\u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: אם בכיר ולקיש כחדא יינץ\u0004 \u0005[\u0006התבואה \u0005הבכירה ו\u0006התבואה \u0005האפילה כאחת\u0006 הן \u0005צומחות]\u0006 — \u0003דין\u0004 \u0005[זה]\u0006 \u0003הוא אדר\u0004 באמת, \u0003ואם לאו\u0004 \u0005[לא]\u0006 — \u0003לית דין\u0004 \u0005[אין זה]\u0006 \u0003אדר\u0004 אלא עדיין שבט הוא. \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: אם תור בצפר בתלג\u0004 \u0005[השור בבוקר בשלג]\u0006 \u0003ימות,\u0004 כלומר, יהא עדיין קר מאד, \u0003ובטיהרא בטול\u0004 \u0005[ובצהרים בצל]\u0006 ה\u0003תאינה ידמוך\u0004 \u0005[יישן]\u0006 ויתחכך בה כחפץ מרוב חום \u0003ישלח משכיה\u0004 \u0005[לפשוט\u0006 את \u0005עורו]\u0006 — \u0003דין\u0004 \u0005[זה]\u0006 \u0003הוא אדר, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003לית דין\u0004 \u0005[אין זה]\u0006 \u0003אדר. וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: אם קידום תקיף לחדא יהא\u0004 \u0005[רוח קדים עזה תהיה],\u0006 ובכל זאת \u0003יפח בלועך נפיק לקיבליה\u0004 \u0005[\u0006הרוח שאתה \u0005נופח בפיך יוצאת לקראתו\u0006 ומבטלת אותה\u0005]\u0006 — \u0003דין\u0004 \u0005[זה]\u0006 \u0003הוא אדר, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003לית דין\u0004 \u0005[אין זה]\u0006 \u0003אדר,\u0004 ובאותה שנה לא היו סימנים אלה, \u0003ו\u0004אכן \u0003עברוה רבנן לההיא שתא\u0004 \u0005[חכמים לאותה שנה],\u0006 משמע שאין תקופת השנה גוררת אחריה את השינוי במזג האויר ובהבשלת הפירות.","ודוחים: \u0003ותסברא, רבנן ארעוותא סמוך\u0004 \u0005[ו\u0006כי \u0005סבור אתה\u0006 ש\u0005חכמים על הרועים סמכו]\u0006 ועל פי סימניהם עיברו את השנה?! \u0003אלא, רבנן אחושבנייהו סמוך\u0004 \u0005[חכמים על חשבונם סמכו]\u0006 והיו צריכים לעבר את השנה לפי חשבונם, \u0003ו\u0004אותם \u0003רועי\u0004 ה\u0003בקר איסתיועי\u0004 \u0005[סיוע]\u0006 \u0003הוא דאיסתייעא מילתייהו\u0004 \u0005[שהסתייע,\u0006 הצליח להם \u0005הדבר]\u0006 שסימניהם היו מכוונים להחלטת חכמים באותה שנה.","שנינו במשנה שהכהן הגדול \u0003חולץ וחולצין\u0004 לו, אבל בכל מקרה אינו מייבם את אשת אחיו. ושואלים: \u0003קא פסיק ותני\u0004 \u0005[פסק ושנה]\u0006 בהחלטיות ובלא לחלק שאין הכהן מייבם כלל, \u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 אם היתה זו אלמנה \u0003מן האירוסין\u0004 בלבד שהיא עדיין בתולה, \u0003ולא שנא\u0004 \u0005[ואינו שונה]\u0006 אם היתה זו אלמנה \u0003מן הנישואין.\u0004 ומעתה, \u0003בשלמא\u0004 \u0005[נניח]\u0006 שאינו מייבם, אלמנה \u0003מן הנישואין\u0004 שהרי \u0003הוי\u0004 \u0005[יש]\u0006 באשה זו שני איסורים לגבי הכהן הגדול, גם מצות \u0003\"עשה\"\u0004 של \"והוא אשה בבתוליה יקח\" (ויקרא כא, יג), \u0003ו\u0004גם מצות \u0003\"לא תעשה\"\u0004 של \"אלמנה וגרושה וחללה זונה את אלה לא יקח\" (ויקרא כא, יד),"],["\u0003ו\u0004כלל הוא ש\u0003אין\u0004 מצות \u0003עשה\u0004 (של \"יבמה יבא עליה ולקחה לו לאשה ויבמה\". דברים כה, ה) \u0003דוחה\u0004 את \u0003\"לא תעשה\" ו\"עשה\"\u0004 יחד. \u0003אלא\u0004 אם היתה זו אלמנה \u0003מן האירוסין\u0004 בלבד, \u0003אמאי\u0004 \u0005[מדוע]\u0006 לא ייבם אותה? \u0003יבא \"עשה\"\u0004 של \"יבמה יבא עליה\" \u0003וידחה\u0004 את \u0003\"לא תעשה\"\u0004 של אלמנה!","ומשיבים: \u0003גזירה ביאה ראשונה\u0004 שיש בה לכאורה דחיה זו של העשה, \u0003אטו\u0004 \u0005[משום]\u0006 \u0003ביאה שניה.\u0004 כי בביאה ראשונה שבא היבם על יבמתו הוא מקיים מצות עשה של יבום, ומצות \"עשה\" זו אכן דוחה את מצות \"לא תעשה\" של אלמנה, אבל בהמשך היחסים ביניהם שוב אין עוד קיום מצות יבום, וכאילו איסור אלמנה עומד בעינו, ולכן גזרו שלא ייבם אפילו בביאה ראשונה.","ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003אם קדמו\u0004 כהן גדול או שאר אנשים שיש איסור לא תעשה לגבי יבמתם \u0003ובעלו ביאה ראשונה\u0004 — \u0003קנו\u0004 את היבמה לאשה שקיימו את המצוה בכך, אבל \u0003אסור לקיימן\u0004 להשאירן כנשים \u0003בביאה שניה.\u0004","שנינו במשנה שאם \u0003מת לו,\u0004 לכהן הגדול, \u0003מת\u0004 אינו יוצא אחר מיטת המת כמלווה ממש. \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005],\u0006 מה שנאמר \u0003\"ומן המקדש לא יצא\u0004 ולא יחלל את מקדש אלהיו כי נזר שמן משחת אלהיו עליו\u0003\"\u0004 (ויקרא כא, יב), כוונתו: \u0003לא יצא עמהן\u0004 עם מלווי המיטה, \u0003אבל יוצא הוא אחריהן, כיצד?\u0004 — \u0003הן נכסין\u0004 מן העין \u0003ו\u0004אז \u0003הוא נגלה, הן ניגלין והוא נכסה.\u0004","שנינו במשנה שלדברי ר' מאיר \u0003יוצא\u0004 הכהן הגדול בלוויית המת \u0003עד פתח\u0004 העיר. ואילו ר' יהודה אומר כי אינו יוצא מן המקדש כלל, שנאמר: \"ומן המקדש לא יצא\". ושואלים: הלא \u0003שפיר קאמר\u0004 \u0005[יפה אמר]\u0006 \u0003ר' יהודה\u0004 וגם פשט הכתובים כדבריו, וכיצד מתרץ אותם ר' מאיר?","ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך\u0004 \u0003ר' מאיר: אי הכי\u0004 \u0005[אם כך],\u0006 שאתה מבין את הכתוב כמשמעו המילולי, \u0003לביתו נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 יצא אלא ישאר תמיד במקדש. \u0003אלא\u0004 בעל כרחך אתה חייב להבין את הביטוי בדרך השאלה, ו\u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003\"\u0004ו\u0003מן המקדש לא יצא\"\u0004 — כוונתו \u0003מקדושתו לא יצא, וכיון דאית ליה הכירא\u0004 \u0005[שיש לו היכר]\u0006 שאינו הולך עם מלווי המיטה, \u0003לא אתי למינגע\u0004 \u0005[יבוא לנגוע\u0006 במיטת המת ולהיטמא\u0005].\u0006","ושואלים: \u0003ור' יהודה\u0004 מה עונה הוא על טענה זו? ומשיבים: לדעתו יש בכל זאת לחשוש כי \u0003אגב מרריה\u0004 \u0005[מתוך מרירותו]\u0006 על מות המת, \u0003דילמא מקרי ואתי ונגע\u0004 \u0005[שמא יקרה שיבוא ויגע].\u0006","במשנה שנינו כיצד נוהג הכהן הגדול \u0003כשהוא מנחם\u0004 אחרים. \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בתוספתא\u0005]\u0006 בהרחבה מסויימת: \u0003כשהוא עובר בשורה לנחם את אחרים, סגן ומשוח שעבר\u0004 (מי שמילא תפקידו של כהן גדול באופן זמני ועבר ממינויו) נמצאים \u0003בימינו, וראש בית אב\u0004 (הממונה על אותו חלק ממשמר הכהנים המשמש באותו יום במקדש) \u0003ו\u0004כן \u0003אבלים וכל העם משמאלו. וכשהוא עומד בשורה\u0004 בין שאר אבלים \u0003ומתנחם מאחרים, סגן\u0004 נמצא \u0003מימינו, וראש בית אב וכל העם משמאלו.\u0004","ומעירים: \u0003אבל משוח שעבר לא אתי גביה\u0004 \u0005[אינו בא לפניו].\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 — \u0003חלשא דעתיה\u0004 \u0005[תחלש דעתו]\u0006 של הכהן הגדול, כלומר, יפגע ועשוי להצטער. \u0003סבר\u0004 \u0005[יחשוב]:\u0006 \u0003קא חדי\u0004 \u0005[\u0006הרי \u0005הוא שמח]\u0006 \u0003בי,\u0004 באסוני שהרי יש ביניהם איבה מסויימת, ועלול הדבר להתפרש שלא כהלכה. \u0003אמר רב פפא: שמע מינה מהא מתניתא תלת\u0004 \u0005[למד מכאן, מברייתא זו, שלושה\u0006 דברים\u0005].\u0006 \u0003שמע מינה\u0004 \u0005[למד מכאן]:\u0006 \u0003היינו\u0004 \u0005[זהו]\u0006 \u0003סגן\u0004 הכהן, \u0003היינו\u0004 \u0005[זהו]\u0006 ה\u0003ממונה,\u0004 שהרי בברייתא נאמר \"סגן\" ובמשנה נאמר \"ממונה\", לגבי אותו אדם עצמו. \u0003ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 שדרך הניחום בשורה היא ש\u0003אבלים עומדין וכל העם עוברין\u0004 ומנחמים אותם. \u0003ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 שהנוהג הוא שה\u0003אבלים לשמאל המנחמין הן עומדין.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003בראשונה היו אבלים עומדין, וכל העם עוברין\u0004 בזה אחר זה ומנחמים אותם, \u0003והיו שתי משפחות בירושלים מתגרות\u0004 (מתקוטטות) \u0003זו בזו, זאת אומרת: אני עוברת תחלה\u0004 שאנו מכובדים ומיוחסים יותר, \u0003וזאת אומרת: אני עוברת תחלה,\u0004 על כן \u0003התקינו שיהא העם עומדין ו\u0004ה\u0003אבלים עוברין,\u0004 וממילא לא יבואו לידי מחלוקת.","\u0003(חזר והלך וסיפר, סימן\u0004 לדברים שתיקן ר' יוסי בציפורי).","\u0003אמר רמי בר אבא: החזיר ר' יוסי את הדבר ליושנו,\u0004 למנהג הקדום, \u0003בציפורי\u0004 עירו, \u0003שיהיו אבלים עומדין וכל העם עוברין. ואמר רמי בר אבא: התקין ר' יוסי בציפורי שלא תהא אשה מהלכת בשוק ובנה אחריה,\u0004 אלא יהלך לפניה, \u0003משום מעשה שהיה\u0004 שחטפו את הילד וכתמורת שחרורו אילצו את האשה לזנות. \u0003ואמר רמי בר אבא: התקין ר' יוסי בציפורי שיהיו נשים מספרות\u0004 (משוחחות זו עם זו) \u0003בבית הכסא, משום ייחוד.\u0004 שבתי הכסא שלהם היו מחוץ לעיר ושמא ינצל אדם לחטא את מציאותה של האשה שם. וכיון שהיא משוחחת עם אחרת — לא יתכן הדבר.","\u0003אמר רב מנשיא בר עות: שאילית\u0004 \u0005[שאלתי]\u0006 \u0003את רבי יאשיה רבה\u0004 \u0005[הגדול]\u0006 \u0003בבית עלמין\u0004 של \u0003הוצל, ואמר לי\u0004 הלכה זו: \u0003אין שורה\u0004 של מנחמים \u0003פחותה מעשרה בני אדם, ואין\u0004 ה\u0003אבלים\u0004 עצמם \u0003מן המנין\u0004 של עשרה אלה, \u0003בין שאבלים עומדין וכל העם עוברין, בין שאבלים עוברין וכל העם עומדין.\u0004","שנינו במשנה: \u0003כשהוא מתנחם\u0004 אומרים לו: \"אנו כפרתך\". \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו: \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003מנחם הוא אחריני\u0004 \u0005[אחרים],\u0006 \u0003היכי אמר להו\u0004 \u0005[כיצד\u0006 הוא \u0005אומר להם]?\u0006 \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו: \u0003והוא אומר \"תתנחמו\". היכי דמי\u0004 \u0005[כיצד בדיוק הדבר]?\u0006 \u0003אילימא כי מנחמי אחריני לדידיה אמר להו איהו\u0004 \u0005[אם תאמר\u0006 ש\u0005כאשר מנחמים אחרים אותו\u0006 באבלו \u0005אומר להם הוא]\u0006 \u0003\"תתנחמו\",\u0004 ואולם דבר זה אינו מסתבר, \u0003נחשא קא רמי להו\u0004 \u0005[נחש,\u0006 קללה, \u0005הוא מטיל בהם]\u0006 שאומר להם שאף הם יצטרכו להתנחם?! \u0003אלא\u0004 יש להבין: \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003מנחם\u0004 הוא \u0003לאחריני אמר להו\u0004 \u0005[את האחרים אומר\u0006 הוא \u0005להם]:\u0006 \u0003\"תתנחמו\".\u0004 ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","שנינו במשנה כי \u0003מלך לא דן\u0004 ולא דנים אותו. \u0003אמר רב יוסף: לא שנו\u0004 הלכה זו \u0003אלא\u0004 ב\u0003מלכי ישראל,\u0004 שהם אלימים ואינם מצייתים לכל דברי התורה, \u0003אבל מלכי בית דוד\u0004 — \u0003דן\u0004 המלך \u0003ודנין אותן, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"בית דוד כה אמר ה' דינו לבקר משפט\u0004 והצילו גזול מיד עושק\u0003\"\u0004 (ירמיה כא, יב). \u0003ואי לא דיינינן ליה\u0004 \u0005[ואם אין אנו דנים אותו],\u0006 \u0003אינהו היכי דייני\u0004 \u0005[הם כיצד דנים]?\u0006 \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 \u0003\"התקוששו וקושו\"\u0004 (צפניה ב, א), \u0003ואמר ריש לקיש: קשט עצמך ואחר כך קשט אחרים.\u0004 שאם אדם אינו נידון אף אינו זכאי לדון אחרים. ומכאן שמעיקר הדין מלך הריהו ככל אדם מישראל, להידון ולדון.","ושואלים: \u0003אלא מלכי ישראל מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא\u0004 ידונו? ומסבירים: \u0003משום מעשה שהיה. דעבדיה\u0004 \u0005[שעבדו]\u0006 של \u0003ינאי מלכא\u0004 \u0005[המלך]\u0006 \u0003קטל נפשא\u0004 \u0005[הרג נפש\u0006 אדם\u0005],\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003שמעון בן שטח לחכמים: תנו עיניכם בו\u0004 בעבד, \u0003ונדוננו. שלחו ליה\u0004 \u0005[לו]\u0006 לינאי: \u0003עבדך קטל נפשא\u0004 \u0005[הרג נפש].\u0006 \u0003שדריה להו\u0004 \u0005[שלח אותו להם].\u0006 \u0003שלחו ליה\u0004 \u0005[לו]:\u0006 \u0003תא אנת נמי להכא\u0004 \u0005[בוא אתה גם כן לכאן],\u0006 כי לגבי שור שנגח והמית אדם אמרה התורה \"ואם שור נגח הוא מתמול שלשום \u0003והועד בבעליו\u0004 ולא ישמרנו והמית איש או אשה\" (שמות כא, כט), \u0003אמרה תורה: יבא בעל השור ויעמוד על שורו.\u0004","\u0003אתא ויתיב\u0004 \u0005[בא וישב].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003שמעון בן שטח: ינאי המלך, עמוד על רגליך ויעידו בך. ולא לפנינו אתה עומד\u0004 וחולק לנו כבוד, \u0003אלא לפני מי שאמר והיה העולם אתה עומד, שנאמר: \"ועמדו שני האנשים אשר להם הריב\u0004 לפני ה' לפני הכהנים והשופטים אשר יהיו בימים ההם\u0003\"\u0004 (דברים יט, יז). \u0003אמר לו\u0004 המלך: \u0003לא כשתאמר אתה\u0004 לי בלבד, \u0003אלא כמה שיאמרו חבריך,\u0004 ואם כל בית הדין סבור כן, אעמוד."],["\u0003נפנה\u0004 שמעון בן שטח \u0003לימינו\u0004 — \u0003כבשו\u0004 הדיינים \u0003פניהם בקרקע\u0004 מחמת אימה ולא אמרו דבר, \u0003נפנה לשמאלו\u0004 — \u0003וכבשו פניהם בקרקע\u0004 ולא אמרו דבר. \u0003אמר להן שמעון בן שטח: בעלי מחשבות אתם,\u0004 כלומר, עושים אתם חשבונות להנאתכם שלא לדבר עתה, \u0003יבא בעל מחשבות\u0004 (הקדוש ברוך הוא) \u0003ויפרע מכם. מיד בא גבריאל וחבטן\u0004 לאותם דיינים \u0003בקרקע, ומתו. באותה שעה\u0004 שראו שאין בידי הסנהדרין כוח לכוף את המלך, \u0003אמרו\u0004 חכמים: \u0003מלך לא דן ולא דנין אותו, לא מעיד ולא מעידין אותו\u0004 מפני הסכנה שבדבר.","שנינו במשנה כי המלך \u0003לא חולץ ולא חולצין\u0004 לאשתו. ור' יהודה אומר שהרשות בידו אם רצה. על דברי ר' יהודה מקשים: \u0003איני\u0004 \u0005[וכי כן הוא]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב אשי: אפילו למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 ש\u0003נשיא שמחל על כבודו\u0004 — \u0003כבודו מחול,\u0004 ואולם \u0003מלך שמחל על כבודו\u0004 — \u0003אין כבודו מחול, שנאמר: \"שום תשים עליך מלך\"\u0004 (דברים יז, טו), וכוונתו: \u0003שתהא אימתו עליך.\u0004 הרי שכבוד המלך הוא מן התורה ואינו ברשות המלך למחול עליו. ומשיבים: לענין \u0003מצוה שאני\u0004 \u0005[שונה],\u0006 ואין בכך משום בזיון המלך כשמוחל על כבודו לשם מצוה.","במשנה שנינו ש\u0003אין נושאין\u0004 אלמנתו של מלך, ור' יהודה אומר שמותר למלך לשאת אלמנת מלך אחר, וראיה לדבר מן האמור בדוד \"ואתנה לך את בית אדוניך ואת נשי אדוניך בחיקך\" (שמואל ב' יב, ח). \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמרו לו לר' יהודה:\u0004 הכוונה בפסוק היא ל\u0003נשים הראויות לו מבית המלך. ומאי נינהו\u0004 \u0005[ומי הן]?\u0006 — \u0003מירב ומיכל\u0004 בנות שאול.","כיון שהוזכר ענין זה, מוסרים כי \u0003שאלו תלמידיו את ר' יוסי: היאך נשא דוד שתי אחיות בחייהן? אמר להן: מיכל אחר מיתת מירב נשאה\u0004 ודבר זה מותר. \u0003ר' יהושע בן קרחה אומר:\u0004 לא כן, אלא \u0003קידושי טעות היו לו במירב\u0004 ונתבטלו הקידושין מעיקרם, וכיון שבטלו הקידושין הרי מיכל מותרת לו, \u0003שנאמר\u0004 בדברי דוד לאיש בושת בן שאול: \u0003\"תנה את אשתי את מיכל אשר ארשתי לי במאה ערלות פלשתים\"\u0004 (שמואל ב' ג, יד).","ושואלים: \u0003מאי תלמודא\u0004 \u0005[מה הלימוד],\u0006 כלומר, כיצד למדים מפסוק זה לענייננו? \u0003אמר רב פפא\u0004 כך יש לדייק: \u0003מיכל\u0004 היא \u0003אשתי ולא מירב\u0004 היא \u0003אשתי.\u0004","ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003קידושי טעות\u0004 היו בדבר? ומשיבים: \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 במלחמת ישראל בפלישתים ובגלית: \u0003\"והיה האיש אשר יכנו יעשרנו המלך עשר גדול\u0004 ואת בתו יתן לו\u0003\"\u0004 (שמואל א' יז, כה). \u0003אזל קטליה\u0004 \u0005[הלך\u0006 דוד ו\u0005הרגו\u0006 לגלית\u0005].\u0006 \u0003אמר לו\u0004 שאול: \u0003מלוה\u0004 (הלוואה) \u0003אית\u0004 \u0005[יש]\u0006 \u0003לך גבאי\u0004 \u0005[אצלי],\u0006 שהרי חייב אני לפרוע לך את העושר הגדול שהבטחתי, ובמחילת מלוה זה תתקדש לך בתי מירב לאשה. ודוד אכן מחל לו מתוך כוונה לקדש את מירב, אבל כסף ממש לא נתן לו. \u0003ו\u0004שנינו ש\u0003המקדש במלוה אינה מקודשת\u0004 ולכן לא התקיים קשר קידושין בין דוד למירב.","\u0003אזל יהבה\u0004 \u0005[הלך\u0006 שאול ו\u0005נתנה]\u0006 \u0003לעדריאל, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויהי בעת תת את מירב בת שאול לדוד\u0004 והיא ניתנה לעדריאל המחולתי לאשה\u0003\"\u0004 (שמואל א' יח, יט). \u0003אמר ליה\u0004 \u0005[לו]\u0006 שאול לדוד: \u0003אי בעית\u0004 \u0005[אם רוצה אתה]\u0006 ש\u0003אתן לך\u0004 את \u0003מיכל, זיל אייתי\u0004 \u0005[לך הבא]\u0006 \u0003לי מאה ערלות פלשתים\u0004 (\"ויאמר שאול כה תאמרו לדוד אין חפץ למלך במוהר כי במאה ערלות פלישתים להינקם באוייבי המלך\". שמואל א' יח, כה). \u0003אזל אייתי ליה\u0004 \u0005[הלך\u0006 ו\u0005הביא לו]\u0006 מאתיים ערלות (ראה שמואל א' יח, כז). \u0003אמר ליה\u0004 \u0005[לו]\u0006 שאול: גם לאחר הבאת הערלות אין הקידושין תופסים, שכן \u0003מלוה ופרוטה אית\u0004 \u0005[יש]\u0006 \u0003לך גבאי\u0004 \u0005[אצלי],\u0006 שהרי הבטיח לו עושר גדול, ונוסף לזה עוד נתן דוד דבר קל ערך (מבחינה כספית) שהוא ערלות פלשתים. וכאן יש מחלוקת בהלכה.","\u0003שאול סבר\u0004 שהמקדש ב\u0003מלוה ופרוטה\u0004 — \u0003דעתיה\u0004 \u0005[דעתו]\u0006 על ה\u0003מלוה\u0004 ולא על הפרוטה הנוספת, ומשום כך אין הקידושין תופסים. \u0003ו\u0004אילו \u0003דוד סבר\u0004 שהמקדש ב\u0003מלוה ופרוטה\u0004 \u0003—\u0004 \u0003דעתיה\u0004 \u0005[דעתו]\u0006 על ה\u0003פרוטה\u0004 ותפסו הקידושין.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003מלוה ופרוטה\u0004 — \u0003דעתיה\u0004 \u0005[דעתו]\u0006 על ה\u0003פרוטה,\u0004 ואולם \u0003שאול סבר\u0004 כי ערלות פלשתים \u0003לא חזו ולא מידי\u0004 \u0005[אינן ראויות לדבר]\u0006 ואינן שוות אפילו פרוטה, ואין מקום לקידושין לחול. \u0003ודוד סבר: חזו לכלבי ושונרי\u0004 \u0005[ראויות\u0006 הן \u0005לכלבים וחתולים]\u0006 כאוכל, ושוות הן פרוטה לפחות.","ושואלים: \u0003ור' יוסי\u0004 שפירש שנשא את מיכל אחר מות מירב, \u0003האי\u0004 \u0005[\u0006הדגשה \u0005זו]\u0006 \u0003\"תנה את אשתי את מיכל\"\u0004 (שמואל ב' ג, יד) \u0003מאי דריש ביה\u0004 \u0005[מה דורש\u0006 הוא \u0005בו]?\u0006 ומשיבים: \u0003ר' יוסי לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 בענין זה. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' יוסי היה דורש מקראות מעורבין,\u0004","\u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"ויקח המלך את שני בני רצפה בת איה אשר ילדה לשאול את ארמני ואת מפיבשת ואת חמשת בני מיכל אשר ילדה לעדריאל\u0004 בן ברזילי \u0003המחלתי\"\u0004 (שמואל ב' כא, ח). \u0003וכי לעדריאל נתנה\u0004 שאול? \u0003והלא לפלטי בן ליש נתנה! דכתיב\u0004 \u0005[שכן נאמר]\u0006 \u0003\"ושאול נתן את מיכל בתו אשת דוד לפלטי בן ליש\"\u0004 (שמואל א' כה, מד), הרי שמיכל לא נישאה כלל לעדריאל!","\u0003אלא מקיש\u0004 \u0005[משווה\u0006 הכתוב\u0005]\u0006 את \u0003קידושי מירב לעדריאל לקידושי מיכל לפלטי\u0004 בן ליש, \u0003מה קידושי מיכל לפלטי\u0004 לכל הדעות היו \u0003בעבירה,\u0004 שהרי כבר היתה נשואה לדוד, \u0003אף קידושי מירב לעדריאל בעבירה\u0004 היו. שעל פי דין היתה מקודשת לדוד.","ושואלים: \u0003ור' יהושע בן קרחה נמי\u0004 \u0005[גם כן]\u0006 \u0003הכתיב\u0004 \u0005[הרי נאמר]:\u0006 \u0003\"את חמשת בני מיכל בת שאול\"\u0004 (שמואל ב' כא, ח) \u0003אמר לך ר' יהושע\u0004 כך יש להבין: \u0003וכי מיכל ילדה\u0004 ילדים אלה? \u0003והלא מירב ילדה\u0004 אותם לעדריאל! אלא \u0003מירב ילדה\u0004 ומתה \u0003ומיכל גידלה\u0004 אותם בביתה, \u0003לפיכך נקראו\u0004 הילדים \u0003על שמה. ללמדך שכל המגדל יתום בתוך ביתו מעלה עליו הכתוב כאילו ילדו.\u0004","\u0003(חנינא קרא\u0004 — ר' חנינא מוכיח מן הפסוק \"ותקראנה\". \u0003ר'\u0004 \u0003יוחנן\u0004 מוכיח מן הפסוק המתחיל \u0003\"ואשתו\".\u0004 \u0003ר'\u0004 \u0003אלעזר וגאולה\u0004 מן הכתוב \"גאלת\". \u0003ו\u0004ר' \u0003שמואל\u0004 בר נחמני \u0003בלימודי\u0004 מענין המלמד בן חבירו, הם \u0003סימן\u0004 לראיות הבאות ולאומריהן) \u0003ר' חנינא אומר: מהכא\u0004 \u0005[מכאן,\u0006 מפסוק זה\u0005]\u0006 יש ראיה לדבר, שנאמר: \u0003\"ותקראנה לו השכנות שם לאמר ילד בן לנעמי\"\u0004 (רות ד, יז). \u0003וכי נעמי ילדה\u0004 את הילד? \u0003והלא רות ילדה! אלא רות ילדה ונעמי גידלה, לפיכך נקרא על שמה\u0004 שבן נולד לנעמי.","\u0003ר' יוחנן אמר: מהכא\u0004 \u0005[מכאן,\u0006 ממקור זה\u0005]\u0006 יש ראיה לדבר, נאמר: \u0003\"ואשתו היהדיה ילדה את ירד אבי גדור\u0004 ואת חבר אבי שוכו ואת יקותיאל אבי זנוח \u0003ואלה בני בתיה בת פרעה אשר לקח מרד\"\u0004 (דברי הימים א' ד, יח). \u0003\"מרד\" זה כלב, ולמה נקרא שמו מרד?\u0004 — \u0003שמרד בעצת מרגלים.\u0004 וירד אבי גדור וכו' הם לפי המדרש כולם כינויים למשה רבינו. \u0003וכי בתיה ילדה\u0004 את משה? \u0003והלא יוכבד ילדה! אלא יוכבד ילדה\u0004 אותו \u0003ובתיה גידלה\u0004 אותו, \u0003לפיכך נקרא על שמה\u0004 כאילו היא ילדתו.","\u0003ר' אלעזר אמר: מהכא\u0004 \u0005[מכאן]\u0006 ראיה לדבר, שנאמר: \u0003\"גאלת בזרוע עמך בני יעקב ויוסף סלה\"\u0004 (תהלים עז, טז). \u0003וכי יוסף ילד\u0004 את כל בני ישראל? \u0003והלא יעקב ילד! אלא יעקב ילד ויוסף כילכל, לפיכך נקראו על שמו\u0004 של יוסף, שכל ישראל קרויים גם בני יוסף.","\u0003אמר ר' שמואל בר נחמני אמר ר' יונתן: כל המלמד\u0004 את \u0003בן חבירו תורה, מעלה עליו הכתוב כאילו ילדו, שנאמר: \"ואלה תולדת אהרן ומשה\"\u0004 (במדבר ג, א), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 מיד אחר כך \u0003\"ואלה שמות בני אהרן\u0004 הבכר נדב ואביהוא אלעזר ואיתמר\u0003\"\u0004 (במדבר ג, ב), ולא נאמרו שמות בני משה, \u0003לומר לך:\u0004 אמנם \u0003אהרן ילד\u0004 את בניו, אבל \u0003משה לימד\u0004 אותם תורה, \u0003לפיכך נקראו\u0004 הבנים גם \u0003על שמו.\u0004","בקשר לענין זה מביאים את דרשת הכתוב \u0003\"לכן כה אמר ה' אל בית יעקב אשר פדה את אברהם\"\u0004 (ישעיה כט, כב). ויש לשאול: \u0003וכי היכן מצינו ביעקב שפדאו לאברהם? אמר רב יהודה: שפדאו מצער גידול בנים,\u0004 שלא היו לו לאברהם שנים עשר שבטים וצרותיהם כפי שהיו ליעקב, וקיבל יעקב על עצמו את הטורח לגדל את שבטי ישראל. \u0003והיינו דכתיב\u0004 \u0005[וזהו שנאמר]:\u0006 \u0003\"לא עתה יבוש יעקב\u0004 ולא עתה פניו יחורו\u0003\"\u0004 (ישעיה כט, כב), ונפרש: \u0003\"לא עתה יבוש יעקב\"\u0004 — \u0003מאביו, \"ולא עתה פניו יחורו\"\u0004 — \u0003מאבי אביו,\u0004 שקיבל על עצמו תפקיד שהיה מוטל גם עליהם.","בענין של פלטי בן ליש דרשו: \u0003כתיב\u0004 \u0005[נאמר]\u0006 במקום אחד \u0003\"פלטי\"\u0004 (שמואל א' כה, מד), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 במקום אחר \u0003\"פלטיאל\"\u0004 (שמואל ב' ג, טו). \u0003אמר ר' יוחנן: פלטי שמו\u0004 האמיתי, \u0003ולמה נקרא שמו פלטיאל?\u0004 ללמד \u0003שפלטו אל מן העבירה\u0004 ולא נגע כלל במיכל בת שאול, משום שהיה סבור שאסורה היא לו, שכן עודנה אשת דוד. \u0003מה עשה? נעץ חרב\u0004 במיטה \u0003בינו לבינה, אמר: כל העוסק בדבר זה\u0004 (תשמיש) \u0003ידקר בחרב זה.\u0004","ושואלים: \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 \u0003\"וילך אתה אישה\u0004 הלוך ובכה אחריה עד בחורים\" (שמואל ב', ג, טז), ואם כן הרי שאישה־בעלה היה! ומשיבים: \u0003שנעשה לה כאישה\u0004 לענין חיבה ודאגה לה. ושואלים: \u0003והכתיב\u0004 \u0005[והרי נאמר\u0006 שם\u0005]\u0006 \u0003\"הלוך ובכה\",\u0004 ואם מתחילה סבר שהיא אשת דוד, מפני מה בכה. ומשיבים: \u0003על המצוה דאזיל מיניה\u0004 \u0005[שהלכה ממנו]\u0006 משום שמעכשיו אינו יכול לקבל עוד שכר על כבישת יצרו. בהמשך הכתוב נאמר \u0003\"עד בחרים\",\u0004 ודורשים: \u0003שנעשו שניהם כבחורים,\u0004 כלומר, \u0003שלא טעמו טעם ביאה\u0004 כלל.","\u0003אמר ר' יוחנן:\u0004 מה שהוא \u0003תוקפו של יוסף,\u0004 כלומר, הדבר הגדול המסופר בכתוב בשבחו של יוסף — הוא \u0003ענוותנותו של בועז,\u0004 כלומר, דבר שאין נחשב לגבי בועז, \u0003ו\u0004מה שהוא \u0003תוקפו\u0004 וחשיבותו \u0003של בועז\u0004 — הוא \u0003ענוותנותו של פלטי בן ליש,\u0004 שגדול היה ממנו במעלת הפרישות. והיכן מצינו שבאותו דבר שהוא \u0003תוקפו של יוסף\u0004 הוא \u0003ענוותנותו של בועז?\u0004 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בבועז \u0003\"ויהי בחצי הלילה ויחרד האיש וילפת\u0004 והנה אשה שוכבת מרגלותיו\u0003\"\u0004 (רות ג, ח). \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"וילפת\"? אמר רב: שנעשה בשרו\u0004 (אברו) \u0003כראשי לפתות\u0004 (שנתקשה מפני התאוה), ואף על פי שפנויה היתה והיתה עימו במיטה אחת — פרש ממנה ולא בא עליה, ואילו ביוסף אשת פוטיפר אשת איש היתה ולא היתה עימו יחד."],["\u0003תוקפו של בועז\u0004 הוא \u0003ענוותנותו של פלטי בן ליש כדאמרן\u0004 \u0005[כפי שאמרנו],\u0006 כי לא לילה אחד בלבד (כבועז) אלא לילות רבים שלט ביצרו.","\u0003אמר ר' יוחנן: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"רבות בנות עשו חיל ואת עלית על כלנה\"\u0004 (משלי לא, כט)? \u0003\"רבות בנות עשו חיל\"\u0004 — \u0003זה יוסף ובועז. \"ואת עלית על כלנה\"\u0004 — \u0003זה פלטי בן ליש,\u0004 שמעלתו בענין זה למעלה משלהם.","\u0003אמר ר' שמואל בר נחמן אמר ר' יונתן: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"שקר החן והבל היפי\u0004 אשה יראת ה' היא תתהלל\u0003\"\u0004 (משלי לא, ל)? \u0003\"שקר החן\"\u0004 — \u0003זה\u0004 מעלתו של \u0003יוסף. \"והבל היפי\"\u0004 — \u0003זה\u0004 מעלתו של \u0003בועז. \"יראת ה' היא תתהלל\"\u0004 — \u0003זה פלטי בן ליש.\u0004","\u0003דבר אחר\u0004 נדרש כתוב זה: \u0003\"שקר החן\"\u0004 — \u0003זה דורו של משה\u0004 רבינו, שבדור זה שעשה עמם ה' נסים ונפלאות לעיני כל, אין עבודת ה' שלהם ראויה כל כך לשבח. \u0003\"והבל היפי\"\u0004 — \u0003זה דורו של יהושע\u0004 שנכבשה לפניו הארץ והראה ה' רוב נסים בדורו. \u0003\"יראת ה' היא תתהלל\"\u0004 — \u0003זה דורו של חזקיה,\u0004 שלמרות שהיו להם יסורי מלחמה וכיבוש נכרי, עסקו בתורה בכל מאודם.","\u0003דבר אחר: \"שקר החן\"\u0004 — \u0003זה דורו של משה ויהושע. \"והבל היפי\"\u0004 — \u0003זה דורו של חזקיה\u0004 שהרי נעשה לו נס בימי סנחריב ונושעה יהודה בזמנו. \u0003\"יראת ה' היא תתהלל\"\u0004 — \u0003זה דורו של ר' יהודה בר' אילעאי\u0004 שהיה לאחר גזירות אדרינוס והיה העם מדולדל ומדוכא. \u0003אמרו עליו על ר' יהודה בר' אילעאי שהיו ששה תלמידים מתכסין בטלית אחת\u0004 מפני עוניים ודחקם, \u0003ו\u0004בכל זאת \u0003עוסקין בתורה.\u0004","\u0003מת לו מת\u0004 למלך — \u0003אינו יוצא מפתח פלטרין\u0004 (ארמון) \u0003שלו,\u0004 שאין זה לכבודו ללוות את המת. \u0003ר' יהודה אומר: אם רוצה לצאת אחר המיטה\u0004 — \u0003יוצא, שכן מצינו בדוד\u0004 המלך \u0003שיצא אחר מיטתו של אבנר, שנאמר: \"והמלך דוד הלך אחר המטה\"\u0004 (שמואל ב', ג, לא). \u0003אמרו לו:\u0004 משם אין ראיה, כי \u0003לא היה הדבר אלא לפייס את העם\u0004 שלא יחשדו בדוד שבשליחותו נהרג אבנר. \u0003וכשמברין אותו\u0004 את המלך בזמן אבילותו \u0003כל העם מסובין על הארץ, והוא מיסב על הדרגש.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מקום שנהגו נשים לצאת אחר המיטה\u0004 של מת — \u0003יוצאות,\u0004 והגברים מהלכים לפני המיטה. ואם נהגו לצאת \u0003לפני המיטה\u0004 — \u0003יוצאות. ר' יהודה אומר:\u0004 אפשר להוכיח ש\u0003לעולם נשים לפני המיטה יוצאות\u0004 ולא לאחריה, \u0003שכן מצינו בדוד שיצא אחר מיטתו של אבנר, שנאמר: \"והמלך דוד הלך אחר המטה\"\u0004 (שמואל ב', ג, לא), ובוודאי לא הלך דוד המלך בין הנשים.","\u0003אמרו לו:\u0004 משם אין ראיה כי \u0003לא היה הדבר אלא לפייס את העם, ונתפייסו.\u0004 ומדוע? \u0003שהיה דוד יוצא מבין האנשים ונכנס לבין הנשים\u0004 המלוות, \u0003ויצא מבין הנשים ונכנס לבין האנשים, שנאמר: \"וידעו כל העם וכל ישראל\u0004 ביום ההוא \u0003כי לא היתה מהמלך להמית את אבנר\u0004 בן נר","\u0003\"\u0004(שמואל ב', ג, לז), ולכן עשה זאת בפרסום גדול. \u0003דרש רבא: מאי דכתיב \"ויבא כל העם להברות את דוד\"\u0004 (שמואל ב', ג,לה), \u0003כתיב\u0004 \u0005[כתוב]\u0006 \u0003\"להכרות\"\u0004 (ראה \"עיונים\"), \u0003וקרינן\u0004 \u0005[ואנו קוראים]\u0006 \u0003\"להברות\",\u0004 הכוונה: \u0003בתחלה\u0004 רצו \u0003להכרותו\u0004 (להכריתו, להשמידו) שחשדוהו שציוה להרוג את אבנר, \u0003ולבסוף\u0004 שראו שאף הוא מצטער בכל ליבו — נתכוונו \u0003להברותו.\u0004","\u0003אמר רב יהודה אמר רב: מפני מה נענש אבנר\u0004 ונהרג במיתה זו? \u0003מפני שהיה לו למחות בשאול\u0004 על הריגת נוב עיר הכהנים \u0003ולא מיחה. ר' יצחק אמר:\u0004 אין הדבר כן, אלא הוא אכן \u0003מיחה ו\u0004אולם \u0003לא נענה,\u0004 ולא משום כך נענש. \u0003ושניהן מקרא אחד דרשו,\u0004 שנאמר: \u0003\"ויקנן המלך אל אבנר ויאמר הכמות נבל ימות אבנר. ידך לא אסרות ורגליך לא לנחשתים הגשו\u0004 כנפול לפני בני עולה נפלת\u0003\"\u0004 (שמואל ב', ג, לג–לד).","\u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 \u0003לא מיחה, הכי קאמר\u0004 \u0005[כך אמר,\u0006 כך יש להבין את הכתוב\u0005]:\u0006 \u0003\"ידך לא אסרות ורגליך לא לנחשתים הגשו\",\u0004 אם כן \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא מחית\u0004 כשעשה שאול מעשה עוול זה? לכן \u0003\"כנפול לפני בני עולה נפלת\". ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 \u0003מיחה ולא נענה,\u0004 הוא מפרש, \u0003איתמהויי מתמה\u0004 \u0005[בתמיהה תמה]\u0006 דוד: \u0003\"הכמות נבל ימות\"?\u0004 הלא \u0003ידיך לא\u0004 היו \u0003אסורות ורגליך לא לנחשתים, מכדי מחויי מחית\u0004 \u0005[הרי מחית\u0006 בזמנו\u0005]\u0006 ואם כן \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003\"כנפול לפני בני עולה נפלת\"?\u0004","ושואלים: \u0003למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 ש\u0003מיחה\u0004 אבנר, אם כן \u0003מאי טעמא איענש\u0004 \u0005[מה טעם נענש]\u0006 במיתה זו? \u0003אמר רב נחמן בר' יצחק:\u0004 מפני \u0003ששהא מלכות בית דוד שתי שנים ומחצה,\u0004 שהרי הוא שהחזיק את תוקפה של מלכות איש בושת בן שאול במשך זמן זה.","שנינו במשנה ש\u0003כשמברין אותו,\u0004 את המלך, הוא יושב על הדרגש. ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"דרגש\"? אמר עולא: ערסא דגדא\u0004 \u0005[מיטה של מזל],\u0006 שהיו מייחדים בבתים מיטה לנוי בלבד, ולשם מזל, ולא היה איש יושב עליה. \u0003אמרו ליה רבנן\u0004 \u0005[לו חכמים]\u0006 \u0003לעולא: מי איכא מידי\u0004 \u0005[האם יש דבר]\u0006 ש\u0003עד האידנא\u0004 \u0005[עכשיו]\u0006 \u0003לא אותביניה\u0004 \u0005[הושבנו אותו]\u0006 עליו, \u0003והשתא מותבינן ליה\u0004 \u0005[ועכשיו\u0006 בזמן אבלו \u0005אנחנו מושיבים אותו]\u0006 עליו?","\u0003מתקיף לה\u0004 \u0005[הקשה על\u0006 קושיא \u0005זו]\u0006 \u0003רבא: מאי\u0004 \u0005[מה]\u0006 ה\u0003קושיא\u0004 שבדבר? \u0003דילמא מידי דהוה\u0004 \u0005[שמא\u0006 הוא \u0005כפי שהינו]\u0006 ביחס ל\u0003אכילה ושתיה,\u0004 ש\u0003עד האידנא\u0004 \u0005[עכשיו]\u0006 \u0003לא אכילניה\u0004 \u0005[האכלנוהו]\u0006 \u0003ולא אשקיניה\u0004 \u0005[השקינוהו],\u0006 \u0003השתא\u0004 \u0005[עכשיו]\u0006 באבילות \u0003קא מוכלינן ליה וקא משקינן ליה\u0004 \u0005[אנו מאכילים אותו ומשקים אותו],\u0006 שהרי זה עניינה של סעודת הבראה. \u0003אלא אי קשיא הא קשיא\u0004 \u0005[אם קשה\u0006 הדבר \u0005זה קשה]:\u0006 ששנינו: \u0003דרגש אינו צריך\u0004 האבל \u0003לכפותו\u0004 (להפכו) בזמן אבילות, \u0003אלא זוקפו\u0004 על צידו. \u0003ואי סלקא דעתך ערסא דגדא\u0004 \u0005[ואם עולה בדעתך\u0006 לומר כי זוהי \u0005מיטת המזל],\u0006 \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003אינו צריך לכפותו? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הכופה את מטתו\u0004 בזמן אבילות, \u0003לא מטתו בלבד הוא כופה, אלא כל\u0004 ה\u0003מטות שיש לו בתוך ביתו הוא כופה.\u0004","ודוחים: \u0003מאי קושיא\u0004 \u0005[מה הקושיה]\u0006 בכך? מה שאינו כופה מיטה זו, \u0003דילמא מידי דהוה\u0004 \u0005[שמא כשם שהוא\u0006 הדין\u0005]\u0006 ב\u0003מטה\u0004 שהיא \u0003מיוחדת לכלים. דקתני\u0004 \u0005[ששנינו]:\u0006 \u0003אם היתה\u0004 מיטה \u0003מיוחדת\u0004 \u0003ל\u0004הניח עליה \u0003כלים\u0004 ולא למשכב בני אדם — \u0003אינו צריך לכפותה. אלא, אי קשיא הא קשיא\u0004 \u0005[אם\u0006 קשה בענין הסבר זה, דבר \u0005זה קשה],\u0006 ששנינו, \u0003רבן שמעון בן גמליאל אומר: דרגש\u0004 אין צריך לכפותו, אלא \u0003מתיר\u0004 האבל את ה\u0003קרביטין\u0004 (הרצועות המחזקות אותו) \u0003והוא נופל מאיליו. ואי סלקא דעתך ערסא דגדא\u0004 \u0005[ואם עולה על דעתך\u0006 לומר \u0005שמדובר כאן ב\u0006\u0005מיטת המזל],\u0006 \u0003קרביטין מי אית ליה\u0004 \u0005[האם יש לו]?\u0006","\u0003אלא, כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין אמר: אמר לי ההוא מרבנן\u0004 \u0005[אחד החכמים],\u0006 \u0003ורב תחליפא שמיה\u0004 \u0005[שמו],\u0006 \u0003דהוה שכיח בשוקא דגילדאי\u0004 \u0005[שהיה מצוי בשוק הרצענים],\u0006 \u0003ואמר ליה\u0004 \u0005[לו]:\u0006 \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"דרגש\"?\u0004 — \u0003ערסא דצלא\u0004 \u0005[מיטה של עור].\u0006 \u0003אמר ר' ירמיה אמר ר' יוחנן:\u0004 ההבדל בין מיטה ודרגש הוא זה: \u0003דרגש\u0004 —"],["\u0003סירוגו מתוכו,\u0004 כלומר, הרצועות שמסרגים כדי לשים עליהן את המצעות, נקשרות בחורים שבתוך מוטות המיטה, ואילו \u0003מטה\u0004 — \u0003סירוגה מעל גבה,\u0004 שקושרים את הרצועות סביב המוטות.","על הסבר זה \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו: \u0003כלי עץ, מאימתי\u0004 הם נחשבים גמורים וראויים להיות \u0003מקבלין טומאה? המטה והעריסה\u0004 — \u0003משישופם\u0004 (ישפשף אותם) \u0003בעור הדג\u0004 הקשה כדי להחליק את העץ. \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003מטה מסורגת היא מעל גבה, למה לי\u0004 לשם מה הצורך ב\u0003שיפת עור הדג?\u0004 והלא הסירוג מכסה את חלק העץ של המיטה! \u0003אלא\u0004 עלינו לחזור בנו מההסבר הקודם ולומר: \u0003הא והא\u0004 \u0005[זה וזה]\u0006 דרגש ומיטה, סירוגם \u0003מתוכו,\u0004 אלא ההבדל הוא זה: \u0003מטה\u0004 — \u0003אעולי ואפוקי בבזיוני\u0004 \u0005[\u0006הרצועות \u0005נכנסות ויוצאות בנקבים שבתוך המוטות],\u0006 \u0003דרגש\u0004 — \u0003אעולי ואפוקי באבקתא\u0004 \u0005[\u0006הן \u0005נכנסות ויוצאות בלולאות].\u0006","\u0003אמר ר' יעקב אמר ר' יהושע בן לוי: הלכה כ\u0004שיטת \u0003רבן שמעון בן גמליאל\u0004 שדרגש אין צורך בכפייתו, אלא מתירים את נקליטיו והוא נופל מאליו. בקשר לענין זה \u0003אמר ר' יעקב בר אמי: מטה שנקליטיה\u0004 (המוטות שעליהם פורשים את הכילה) \u0003יוצאין\u0004 ובולטים החוצה, ואי אפשר לכפותה — \u0003זוקפה\u0004 בזמן האבילות, \u0003ודיו.\u0004","\u0003ו\u0004המלך \u0003מוציא\u0004 את העם \u0003למלחמת הרשות על פי בית דין של שבעים ואחד, ופורץ\u0004 גדרות של כל אדם \u0003לעשות לו דרך\u0004 לצרכיו השונים, \u0003ואין ממחה בידו. דרך המלך אין לו שיעור\u0004 לא לארכו ולא לרחבו, ואין לומר לו שדרך זו רחבה מצרכו. \u0003וכל העם בוזזין\u0004 במלחמה \u0003ונותנין לו, והוא נוטל חלק בראש\u0004 מכל שלל המלחמה.","שואלים: הרי כבר \u0003תנינא חדא זימנא\u0004 \u0005[שנינו\u0006 דבר זה \u0005פעם אחת]\u0006 בראש המסכת: \u0003אין מוציאין למלחמת הרשות אלא על פי בית דין של שבעים ואחד!\u0004 ומסבירים: \u0003איידי דתנא\u0004 \u0005[מתוך ששנה]\u0006 את \u0003כל מילי\u0004 \u0005[דבריו,\u0006 דיניו\u0005]\u0006 של ה\u0003מלך,\u0004 \u0003תנא נמי\u0004 \u0005[שנה גם כן]\u0006 ענין של \u0003מוציאין למלחמת הרשות.\u0004 ושם נשנה מפני דיני הסנהדרין.","בענין המלך וזכויותיו נחלקו דעות החכמים, \u0003אמר רב יהודה אמר שמואל: כל האמור בפרשת מלך\u0004 שבספר שמואל (שמואל א' ח, יא–יז) \u0003מלך מותר בו,\u0004 שיכול הוא לעשות את כל האמור שם, והוא חלק מזכויותיו המלכותיות. \u0003רב אמר: לא נאמרה פרשה זו אלא\u0004 כדי \u0003לאיים עליהם,\u0004 שיקבלו עליהם את מרותו של המלך באימה, \u0003שנאמר: \"שום תשים עליך מלך\"\u0004 (דברים יז, טו) — \u0003שתהא אימתו עליך.\u0004 אבל אין המלך רשאי לעשות כל מה שנאמר שם.","ומעירים, דבר זה הוא \u0003כתנאי\u0004 \u0005[כ\u0006מחלוקת \u0005תנאים]\u0006 שנחלקו באותו נושא. ש\u0003ר' יוסי אומר: כל האמור בפרשת מלך\u0004 — \u0003מלך מותר בו. ר' יהודה אומר: לא נאמרה פרשה\u0004 (המלך) \u0003זו אלא כדי לאיים עליהם, שנאמר: \"שום תשים עליך מלך\"\u0004 — \u0003שתהא אימתו עליך.\u0004","\u0003וכן היה ר' יהודה אומר: שלש מצות נצטוו ישראל בכניסתן לארץ\u0004 שאינן נוהגות בחוץ לארץ, ויש סדר מסויים לקיומן בארץ: \u0003להעמיד להם מלך, ולהכרית זרעו של עמלק\u0004 במלחמה בו, \u0003ולבנות להם בית הבחירה\u0004 (בית המקדש).","\u0003ר' נהוראי אומר: לא נאמרה פרשה זו אלא כנגד תרעומתן, שנאמר: \"ואמרת אשימה עלי מלך\u0004 ככל הגוים אשר סביבותי\u0003\"\u0004(דברים יז, יד), שאין העמדת מלך מצוה, ורצה שמואל להפחידם אולי יתחרטו ולא ירצו עוד במלך.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אליעזר אומר: זקנים שבדור\u0004 בזמנו של שמואל \u0003כהוגן שאלו, שנאמר: \"תנה לנו מלך לשפטנו\"\u0004 (שמואל א' ח, ו), שרצו שיהא מנהיג קבוע לעם במקום שמואל, \u0003אבל עמי הארץ שבהן קלקלו, שנאמר:\u0004 \"וימאנו העם לשמוע בקול שמואל ויאמרו לא כי אם מלך יהיה עלינו. \u0003והיינו גם אנחנו ככל הגוים ושפטנו מלכנו ויצא לפנינו\u0004 ונלחם את מלחמותנו\" (שמואל א' ח, כ).","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יוסי אומר: שלש מצות\u0004 \u0003נצטוו ישראל בכניסתן לארץ: להעמיד להם מלך, ולהכרית זרעו של עמלק, ולבנות להם בית הבחירה. ואיני יודע איזה מהן\u0004 חייבים לעשותה \u0003תחילה.\u0004","\u0003כשהוא אומר \"כי יד על כס יה מלחמה לה' בעמלק\u0004 מדר דר\u0003\"\u0004 (שמות יז, טז), \u0003הוי אומר: להעמיד להם מלך תחילה, ו\u0004לומדים זאת כך: \u0003אין \"כסא\" אלא\u0004 כינוי סמלי עבור \u0003מלך, שנאמר: \"וישב שלמה על כסא ה' למלך\"\u0004 (דברי הימים א' כט, כג), הרי שהמלך היושב על \"כס יה\".","\u0003ועדיין איני יודע אם\u0004 מצוה \u0003לבנות להם בית הבחירה תחלה, או להכרית זרעו של עמלק תחלה. כשהוא אומר \"והניח לכם מכל איביכם\u0004 מסביב וישבתם בטח \u0003והיה המקום אשר יבחר ה'\u0004 אלהיכם בו לשכן שמו שם שמה תביאו את כל אשר אנכי מצוה אתכם\u0003\"\u0004 (דברים יב, י–יא), \u0003הוי אומר: להכרית זרעו של עמלק\u0004 חייבים לעשות \u0003תחלה.\u0004","\u0003וכן בדוד הוא אומר: \"ויהי כי ישב המלך דוד בביתו וה' הניח לו מסביב\u0004 מכל אויביו\u0003\"\u0004 (שמואל ב' ז, א), \u0003וכתיב\u0004 \u0005[ו\u0006מיד אחר כך \u0005נאמר]\u0006 \u0003\"ויאמר המלך אל נתן הנביא ראה נא אנכי יושב בבית ארזים\u0004 וארון האלהים יושב בתוך היריעה\u0003\"\u0004 (שמואל ב' ז, ב).","אגב הזכרת הפסוק בדבר מלכות שלמה, מביאים את מה ש\u0003אמר ריש לקיש: בתחילה מלך שלמה\u0004 אף \u0003על\u0004 העולמות \u0003העליונים,\u0004 \u0003שנאמר: \"וישב שלמה על כסא ה' \"\u0004(דברי הימים א כט, כג), שהיתה מלכותו כמלכות ה' — בכל העולמות, \u0003ולבסוף\u0004 כאשר נשא נשים נכריות לא \u0003מלך\u0004 אלא \u0003על התחתונים\u0004 בלבד, \u0003שנאמר: \"כי הוא רדה בכל עבר הנהר מתפסח ועד עזה\"\u0004 (מלכים א' ה, ד).","בפירושו של פסוק זה נחלקו האמוראים \u0003רב ושמואל, חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: תפסח\u0004 הוא שם מקום \u0003בסוף העולם\u0004 כלומר, בקצה אחד של מלכותו, \u0003ועזה בסוף העולם. וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: תפסח ועזה בהדי הדדי הוו יתבו\u0004 \u0005[זו ליד זו היו יושבות],\u0006 \u0003ו\u0004בא הכתוב ללמד ש\u0003כשם שמלך על תפסח ועל עזה, כך מלך על כל העולם כולו,\u0004","\u0003ולבסוף\u0004 ירד ירידה נוספת ש\u0003לא מלך אלא על ישראל\u0004 בלבד, \u0003שנאמר: \"אני קהלת הייתי מלך על ישראל\u0004 בירושלים\u0003\"\u0004 (קהלת א, יב), \u0003ולבסוף לא מלך אלא על ירושלים, שנאמר: \"דברי קהלת בן דוד מלך בירושלם\"\u0004 (קהלת א, א), \u0003ולבסוף לא מלך אלא על מטתו, שנאמר: \"הנה מטתו שלשלמה\u0004 ששים גבורים סביב לה מגבורי ישראל\u0003\"\u0004(שיר השירים ג, ז),","\u0003ולבסוף\u0004 ירד עד כדי כך ש\u0003לא מלך אלא על מקלו, שנאמר: \"\u0004ו\u0003זה היה חלקי מכל עמלי\"\u0004 (קהלת ב, י). אף בענין זה נחלקו \u0003רב ושמואל, חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 כאשר אמר \"זה\" התכוון ל\u0003מקלו, וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 התכוון ל\u0003גונדו\u0004 \u0005[טליתו].\u0006","ושואלים: האם \u0003הדר\u0004 \u0005[חזר]\u0006 למלכותו לשלוט בעולם, כולו \u0003או לא הדר\u0004 \u0005[חזר]\u0006 לבסוף? \u0003רב ושמואל\u0004 נחלקו בכך, \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: הדר\u0004 \u0005[חזר],\u0006 \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: לא הדר\u0004 \u0005[חזר].\u0006 \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר\u0004 \u0003לא הדר\u0004 \u0005[חזר],\u0006 הרי לדעתו היה שלמה בתחילה \u0003מלך ו\u0004אחר כך \u0003הדיוט,\u0004 ולא שב יותר למלכותו, \u0003ומאן\u0004 \u0005[מי]\u0006 ש\u0003אמר הדר\u0004 \u0005[חזר],\u0006 לדעתו היה שלמה בתחילה \u0003מלך ו\u0004אחר כך \u0003הדיוט ו\u0004לבסוף שב להיות \u0003מלך.\u0004","שנינו במשנה כי המלך \u0003פורץ לעשות לו דרך.\u0004 \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003אוצרות מלכים\u0004 שלוקחים שלל במלחמה שייכים \u0003למלך, ושאר ביזה שבוזזין\u0004 במלחמה — \u0003מחצה למלך ומחצה לעם. אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב דימי, ואמרי לה\u0004 \u0005[ויש אומרים\u0006 שאמר זאת\u0005]\u0006 \u0003לרב אחא: בשלמא\u0004 \u0005[נניח]\u0006 הלכה זו ש\u0003אוצרות מלכים למלך\u0004 — כך הוא \u0003אורחא דמלתא\u0004 \u0005[דרך הדברים],\u0006 וראוי שישתמש המלך באוצרות המלכים שהוא כובש, \u0003אלא שאר ביזה שבוזזין\u0004 במלחמה, שהיא \u0003מחצה למלך ומחצה לעם, מנלן\u0004 \u0005[מנין לנו]\u0006 שמגיע למלך? ומשיבים: \u0003דכתיב\u0004 \u0005[שנאמר]\u0006"],["\"וימליכו שנית לשלמה בן דויד \u0003וימשחו לה' לנגיד ולצדוק\u0004 לכהן\" (דברי הימים א' כט, כב). בפסוק זה \u0003מקיש\u0004 (משווה) \u0003נגיד,\u0004 כלומר, את המלך \u0003לצדוק\u0004 הכהן הגדול, \u0003מה צדוק\u0004 שכל מתנות הכהונה בלחם הפנים — \u0003מחצה לו\u0004 לכהן גדול, \u0003ומחצה ל\u0004כל \u0003אחיו, אף נגיד\u0004 — \u0003מחצה לו ומחצה לאחיו.\u0004","ושואלים: \u0003וצדוק גופיה\u0004 \u0005[עצמו]\u0006 \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 שכהן גדול נוטל מחצה? ומשיבים: \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005],\u0006 \u0003רבי אומר:\u0004 נאמר בחלוקת לחם הפנים \u0003\"והיתה לאהרן ולבניו\u0004 ואכלהו במקום קדוש\u0003\"\u0004 (ויקרא כד, ט), ומכאן נלמד: \u0003מחצה לאהרן ומחצה לבניו.\u0004","\u0003לא ירבה לו\u0004 המלך \u0003נשים אלא שמנה עשרה\u0004 בלבד. \u0003ר' יהודה אומר: מרבה הוא לו\u0004 נשים כמה שירצה, \u0003ובלבד שלא יהו\u0004 כאלה ש\u0003מסירות את לבו\u0004 מיראת ה'. \u0003ר' שמעון אומר: אפילו אחת ומסירה את לבו\u0004 — \u0003הרי זה לא ישאנה. אם כן למה נאמר \"\u0004ו\u0003לא ירבה לו נשים\"\u0004 (דברים יז, יז)? ש\u0003אפילו כאביגיל,\u0004 שהיתה צדקת ומנעתו לדוד מעבירה (שמואל א' פרק כה) — אסור לו להרבות, שגזירת הכתוב היא.","שואלים: \u0003למימרא\u0004 \u0005[האם לומר]\u0006 ש\u0003ר' יהודה דריש טעמא דקרא\u0004 \u0005[דורש\u0006 את \u0005טעם הכתוב]\u0006 ומפרש את המצוה האמורה בכתוב על פי טעם ונימוק ידוע, ועל פיו קובע הלכה, \u0003ור' שמעון לא דריש טעמא דקרא\u0004 \u0005[אינו דורש\u0006 את \u0005טעם הכתוב]?\u0006 \u0003והא איפכא שמעינן להו\u0004 \u0005[והרי ההיפך שמענו אותם]\u0006 בכל מקום.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אלמנה, בין שהיא עניה בין שהיא עשירה\u0004 — \u0003אין ממשכנין אותה\u0004 כערבון להלוואה, \u0003שנאמר: \"\u0004ו\u0003לא תחבל בגד אלמנה\"\u0004 (דברים כד, יז), אלו \u0003דברי ר' יהודה. ר' שמעון אומר:\u0004 אלמנה \u0003עשירה\u0004 — \u0003ממשכנין אותה, ענייה\u0004 — \u0003אין ממשכנין אותה,\u0004 והטעם הוא משום שמאחר \u0003ו\u0004היא עניה \u0003אתה חייב להחזיר לה\u0004 את המשכון, \u0003ו\u0004נמצא ש\u0003אתה משיאה שם רע בשכנותיה.\u0004","\u0003ואמרינן\u0004 \u0005[ואומרים אנו]\u0006 באותו ענין: \u0003מאי קאמר\u0004 \u0005[מה אמר]\u0006 ר' שמעון, מה משמעות הדבר? ומסבירים, \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003מתוך שאתה ממשכנה אתה חייב להחזיר לה,\u0004 כאמור \"ואם איש עני הוא לא תשכב בעבוטו השב תשיב לו את העבוט כבוא השמש\" (דברים כד, יב–יג), \u0003ואתה משיאה שם רע בשכנותיה,\u0004 שהשכנות רואות שבא אדם בכל בוקר ובכל ערב לביתה של אותה אלמנה, וייצא עליה שם רע. \u0003אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003ר' יהודה לא דריש טעמא דקרא\u0004 \u0005[אינו דורש\u0006 את \u0005טעם הכתוב],\u0006 \u0003ור' שמעון דריש טעמא דקרא\u0004 \u0005[דורש\u0006 את \u0005טעם הכתוב]!\u0006","ומשיבים: אכן, \u0003בעלמא\u0004 \u0005[בכלל]\u0006 \u0003ר' יהודה לא דריש טעמא דקרא\u0004 \u0005[אינו דורש טעם הכתוב],\u0006 \u0003ושאני הכא\u0004 \u0005[ושונה כאן]\u0006 ש\u0003מפרש טעמא דקרא\u0004 \u0005[טעם הכתוב]\u0006 במקרא עצמו: \u0003מה טעם \"לא ירבה לו נשים\"?\u0004 — \u0003משום\u0004 שנאמר \u0003\"לא יסור לבבו\"\u0004 (דברים כד, יז, יז).","\u0003ור' שמעון אמר\u0004 \u0005[\u0006יכול היה לומר] \u0003לך: מכדי בעלמא דרשינן טעמא דקרא\u0004 \u0005[הרי בכלל דורשים אנו\u0006 את \u0005טעם הכתוב],\u0006 כשיטתו, ו\u0003אם כן לכתוב קרא\u0004 \u0005[שיאמר הכתוב]\u0006 רק \u0003\"לא ירבה לו נשים\" ולישתוק\u0004 \u0005[ושישתוק]\u0006 ולא יאמר עוד, \u0003ואנא אמינא\u0004 \u0005[ואני אומר]\u0006 מדעתי: \u0003מה טעם לא ירבה?\u0004 — \u0003משום\u0004 שנאמר \u0003\"לא יסור\".\u0004 ואם כן זה שבכל זאת נכתב הטעם של \u0003\"לא יסור\"\u0004 במפורש \u0003למה לי?\u0004 ללמדנו הלכה נוספת, ולא נימוק להלכה בלבד, ש\u0003אפילו\u0004 היתה אשה \u0003אחת ומסירה את לבו\u0004 — \u0003הרי זו לא ישאנה\u0004 מפני האמור \"ולא יסור\". \u0003אלא מה אני מקיים \"לא ירבה\"\u0004 — ש\u0003אפילו\u0004 נשים צדיקות \u0003כאביגיל\u0004 לא ירבה.","לגופה של ההלכה, \u0003הני\u0004 \u0005[אותן]\u0006 \u0003שמונה עשרה\u0004 נשים ששנינו במשנה שמותר למלך לשאת, \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 המספר? ומשיבים, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויולדו לדוד בנים בחברון ויהי בכורו אמנון לאחינעם היזרעאלת. ומשנהו כלאב לאביגיל אשת נבל הכרמלי והשלישי אבשלום בן מעכה\u0004 בת תלמי מלך גשור. \u0003והרביעי אדניה בן חגית והחמישי שפטיה בן אביטל. והששי יתרעם לעגלה אשת דוד אלה ילדו לדוד בחברון\"\u0004 (שמואל ב' ג, ב–ה),","\u0003וקאמר ליה\u0004 \u0005[ואמר לו]\u0006 ה\u0003נביא\u0004 נתן בתוכחתו: \u0003\"\u0004ואתנה לך את בית אדוניך ואת נשי אדוניך בחיקך ואתנה לך את בית ישראל ויהודה ו\u0003אם מעט ואספה לך כהנה וכהנה\"\u0004 (שמואל ב' יב, ח). \u0003\"כהנה\",\u0004 כלומר, כאותו מספר — הרי עוד \u0003שית\u0004 \u0005[שש],\u0006 \u0003\"וכהנה\"\u0004 — עוד פעם \u0003שית\u0004 \u0005[שש],\u0006 \u0003דהוו להו תמני סרי\u0004 \u0005[שהרי הן שמונה עשרה].\u0006","\u0003מתקיף לה\u0004 \u0005[מקשה עליה,\u0006 על שיטת הסבר זו\u0005]\u0006 \u0003רבינא:\u0004 \u0003אימא\u0004 \u0005[אמור]\u0006 לא כך, אלא \u0003\"כהנה\"\u0004 פירושו כמו שהן עוד פעם — הרי \u0003תרתי סרי\u0004 \u0005[שתים עשרה],\u0006 \u0003\"וכהנה\"\u0004 — כמו כולן יחד, הרי יחד \u0003עשרין וארבע!\u0004","ומעירים: אכן, \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]\u0006 כשיטה \u0005זו:\u0006 מה שנאמר \u0003\"לא ירבה לו נשים\"\u0004 הרי זה בא לומר שלא ירבה לו נשים \u0003יותר מעשרים וארבע.\u0004 ושואלים: \u0003למאן דדריש\u0004 \u0005[\u0006ו\u0005ל\u0006דעת \u0005מי שדורש]\u0006 \u0003וי\"ו,\u0004 וסבור כי זו לשון ריבוי והוספה, אם כן \"כהנה וכהנה\" בא להוסיף יותר, פי שתים מן האמור, ולשיטה זו \u0003ארבעים ושמנה הוו\u0004 \u0005[הן]?\u0006 ומעירים: אכן, \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]\u0006 כשיטה זו: \u0003\"לא ירבה לו נשים\"\u0004 — \u0003יותר מארבעים ושמנה.\u0004","ושואלים: \u0003ותנא דידן\u0004 \u0005[והתנא שלנו]\u0006 במשנתנו \u0003מאי טעמיה\u0004 \u0005[מה טעמו]\u0006 שהוא מגביל לשמונה עשרה? \u0003אמר רב כהנא: מקיש\u0004 (משווה) \u0003\"כהנה\" בתרא\u0004 \u0005[האחרון]\u0006 \u0003ל\"כהנה\" קמא\u0004 \u0005[הראשון],\u0006 \u0003מה \"כהנה\" קמא\u0004 \u0005[\u0006האמור \u0005ראשון]\u0006 כוונתו \u0003שית\u0004 \u0005[שש]\u0006 נוספות, \u0003אף \"כהנה\" בתרא\u0004 \u0005[האחרון]\u0006 — כוונתו \u0003שית\u0004 \u0005[שש]\u0006 ולא עוד.","ומקשים: והאם היו לדוד קודם רק שש נשים? \u0003והא הואי\u0004 \u0005[והרי היתה]\u0006 עוד אשה והיא \u0003מיכל,\u0004 ואם כן, לא שש כי אם שבע לפחות היו! \u0003אמר רב: עגלה\u0004 שנאמרה במנין הנשים \u0003זו\u0004 היא \u0003מיכל, ולמה נקרא\u0004 במקרא \u0003שמה עגלה?\u0004 משום \u0003ש\u0004היתה \u0003חביבה עליו כעגלה, וכן הוא אומר\u0004 ומכנה אשה אהובה בכינוי זה בשמשון, שאמר: \u0003\"לולי חרשתם בעגלתי\u0004 לא מצאתם חידתי","\u0003\"\u0004(שופטים יד, יח). ושואלים על זיהוי זה: \u0003ומי הוו\u0004 \u0005[והאם היו]\u0006 \u0003למיכל בני\u0004 \u0005[בנים]?\u0006 \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"ולמיכל בת שאול לא היה לה ולד עד יום מותה\"\u0004 (שמואל ב' ו, כג)! \u0003אמר רב חסדא,\u0004 כוונת הכתוב: \u0003עד\u0004 \u0003יום מותה\u0004 — \u0003לא היה לה\u0004 בנים, ואולם \u0003ביום מותה\u0004 — \u0003היה לה.\u0004","ומקשים: \u0003מכדי\u0004 \u0005[הרי]\u0006 \u0003בנים היכא קא חשיב להו\u0004 \u0005[היכן מונה הוא אותם]?\u0006 — \u0003בחברון,\u0004 שהרי היא נמנית עם נשי דוד שבחברון, \u0003ואילו מעשה\u0004 שהיה ב\u0003מיכל,\u0004 שעליו נאמר שלא היו לה בנים, \u0003בירושלים הוה\u0004 \u0005[היה]!\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ומיכל בת שאול נשקפה בעד החלון ותרא את המלך דוד מפזז ומכרכר לפני ה' ותבז\u0004 לו בלבה\u0003\"\u0004 (שמואל ב' ו, טז). \u0003ואמר רב יהודה ואיתימא\u0004 \u0005[ויש אומרים]\u0006 \u0003רב יוסף: שקלתה\u0004 \u0005[קיבלה]\u0006 \u0003מיכל למיטרפסה\u0004 \u0005[את עונשה]\u0006 מיד, ולכן לא היו לה בנים. \u0003אלא אימא\u0004 \u0005[אמור]\u0006 ופרש כך: \u0003עד אותו מעשה\u0004 — \u0003היה לה, מכאן ואילך\u0004 — \u0003לא היה לה\u0004 בנים.","ומקשים: וכי לא היו לדוד נשים נוספות? \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 \u0003\"ויקח דוד עוד פלגשים ונשים בירושל ם\u0004 אחרי בואו מחברון\u0003\"\u0004 (שמואל ב' ה, יג)! ומשיבים: כל אלה היו \u0003למלויי\u0004 \u0005[למלא]\u0006 למנין \u0003שמונה עשר\u0004 ולא יותר. ושואלים ביחס לפירוש זה: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"נשים\" ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"פלגשים\"? אמר רב יהודה אמר רב: נשים\u0004 — אלה שכותבים להן \u0003כתובה ו\u0004עושים להן \u0003קידושין, פלגשים\u0004 — \u0003בלא כתובה ובלא קידושין.\u0004","\u0003אמר רב יהודה אמר רב: ארבע מאות ילדים\u0004 (אנשים צעירים) \u0003היו לו לדוד\u0004 בצבאו, \u0003וכולן בני יפת תואר היו, ומגדלי בלוריות היו\u0004 כדרך הגויים, \u0003וכולן יושבין בקרונות של זהב, ומהלכין בראשי גייסות היו, והם היו בעלי אגרופין של בית דוד,\u0004 שבית דוד נסמך על נאמנותם של ארבע מאות בחורים אלה.","\u0003ואמר רב יהודה אמר רב: תמר בת יפת תואר היתה,\u0004 כלומר, היא היתה בת של אשה שנלקחה במלחמה כ\"אשת יפת תואר\", ונולדה לפני שנתגיירה אותה אשה גירות גמורה (ואז ילדה את אבשלום), ולא נחשבה כבתו של דוד. וראיה לדבר — ממה \u0003שנאמר\u0004 בה שאמרה לאמנון בן דוד: \u0003\"ועתה דבר נא על המלך כי לא ימנעני ממך\"\u0004 (שמואל ב' יג, יג). \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר כי \u0003בת נישואין הואי\u0004 \u0005[היתה],\u0006 אם כן, \u0003אחתיה מי הוה שריא ליה\u0004 \u0005[אחותו האם היתה מותרת לו]\u0006 שיתן דוד אותה לו לאשה? \u0003אלא שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003בת יפת תואר היתה,\u0004 והיתה איפוא נחשבת כבת אמה הגויה שנתגיירה לאחר מכן ואינה כבתו של דוד, ולכן יכול היה אמנון לשאת אותה לאשה. כיון שהוזכר פסוק זה דנים עוד במעשה אמנון ותמר.","נאמר שם \u0003\"ולאמנון רע ושמו יונדב בן שמעה אחי דוד ויונדב איש חכם\u0004 מאד\u0003\"\u0004 (שמואל ב' ו, ג). \u0003אמר רב יהודה אמר רב: איש חכם לרשעה.\u0004","\u0003\"ויאמר\u0004 לו \u0003מדוע אתה ככה דל בן המלך...\u0004 \u0003ויאמר לו יהונדב שכב על משכבך והתחל\" עד \"ועשתה לעיני את הבריה\"\u0004 (שמואל ב' ו ד–ה), \u0003\"ותקח\u0004 את \u0003המשרת ותצק לפניו\"\u0004 (שמואל ב' ו ט). \u0003אמר רב יהודה אמר רב:\u0004 פירושו, \u0003שעשתה לו מיני טיגון.\u0004","נאמר לבסוף \u0003\"וישנאה אמנון שנאה גדולה מאד\u0004 כי גדולה השנאה אשר שנאה מאהבה אשר אהבה\" (שמואל ב' ו טו), ושאלו: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 לשנאה עזה זו? \u0003אמר ר' יצחק: נימא\u0004 \u0005[שערה]\u0006 \u0003נקשרה לו\u0004 בשעת ביאה וחתכה מבשר אברו \u0003ועשאתו כרות שפכה.\u0004 ושואלים: \u0003וכי\u0004 אם אכן \u0003נקשרה לו, איהי מאי עבדה\u0004 \u0005[היא מה עשתה]\u0006 ומשום מה שנא אותה? \u0003אלא אימא\u0004 \u0005[אמור]\u0006 ש\u0003קשרה לו\u0004 בכוונה \u0003נימא, ועשאתו כרות שפכה\u0004 כדי לנקום בו, ועל כך שנאה.","ומקשים: \u0003איני\u0004 \u0005[וכי כן הוא]?!\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003דרש רבא: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"ויצא לך שם בגוים ביפיך\"\u0004 (יחזקאל טז, יד), ללמד \u0003שאין להן לבנות ישראל לא שער בית השחי ולא\u0004 שער \u0003בית הערוה,\u0004 ומנין היו שערות לתמר? ומשיבים: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003תמר,\u0004 ש\u0003בת יפת תואר הואי\u0004 \u0005[היתה],\u0006 ואם כן לא היתה אמה מישראל.","נאמר \u0003\"ותקח תמר אפר על ראשה ואת כתנת הפסים אשר עליה קרעה\"\u0004 (שמואל ב' יג, יט). \u0003תנא\u0004 \u0005[שנה]\u0006 החכם \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' יהושע בן קרחה: גדר גדול גדרה תמר באותה שעה\u0004 על ידי זעקתה בפומבי, שכן \u0003אמרו\u0004 הכל: אם \u0003לבנות מלכים\u0004 קרה \u0003כך, לבנות הדיוטות על אחת כמה וכמה\u0004 שיכול לקרות מעין זה, \u0003אם לצנועות\u0004 כתמר שלא רצתה קרה \u0003כך, לפרוצות\u0004 יותר — \u0003על אחת כמה וכמה. אמר רב יהודה אמר רב: באותה שעה גזרו\u0004"],["\u0003על הייחוד\u0004 שלא יתייחד אדם עם נשים האסורות עליו משום ערוה, \u0003ועל הפנויה.\u0004","ותוהים: גזרו על ה\u0003יחוד?\u0004 והלא איסור \u0003דאורייתא\u0004 \u0005[שמן התורה]\u0006 \u0003הוא,\u0004 שאסור להתייחד עם אשה האסורה לו משום ערוה. ש\u0003אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' שמעון בן יהוצדק: רמז לייחוד\u0004 שאסור \u0003מן התורה מניין? שנאמר: \"כי יסיתך אחיך בן אמך\"\u0004 (דברים יג, ז), ויש לתמוה: \u0003וכי בן אם מסית, בן אב אינו מסית?\u0004 ומשום מה לא נזכר שם? \u0003אלא לומר לך\u0004 כי רק ה\u0003בן מתייחד עם אמו,\u0004 ומשום כך מצויים שני הבנים בני אם אחת אצל אמם והם קרובים זה לזה, אבל \u0003אין אחר מתייחד עם כל עריות שבתורה.\u0004 ואף אסור לו לאדם להתייחד עם אשת אביו, ולכן אין בני אב אחד מצויים יחד כל כך. משמע שאיסור יחוד מן התורה הוא, וכיצד אמרו שנגזר בימי דוד?","\u0003אלא אימא\u0004 \u0005[אמור]:\u0006 \u0003גזרו על ייחוד\u0004 של \u0003פנויה,\u0004 שאפילו עם פנויה אסור להתייחד, שמא יארע כמעשה שאירע בתמר.","אגב המעשה באמנון מביאים עוד מה שנאמר בבן אחר של דוד: \u0003\"ואדניה בן חגית מתנשא לאמר אני אמלך\u0004 ויעש לו רכב ופרשים וחמישים איש רצים לפניו\u0003\"\u0004 (מלכים א' א, ה), \u0003אמר רב יהודה אמר רב\u0004 על המלה \"מתנשא\": \u0003מלמד שביקש להולמו\u0004 שתהא המלכות הולמת אותו \u0003ולא הולמתו.\u0004","\u0003\"ויעש לו רכב ופרשים וחמשים איש רצים לפניו\",\u0004 ושואלים: \u0003מאי רבותא\u0004 \u0005[מה הגדולה\u0006 שבדבר זה\u0005]?\u0006 והלא אנשים עשירים אחרים שאינם בני מלכים עושים כן! \u0003אמר רב יהודה אמר רב\u0004 מיוחדים היו אלה, \u0003כולן נטולי טחול, וחקוקי כפות רגלים היו,\u0004 שהורידו מהם את בשר כפות הרגלים, ועל ידי שני הניתוחים הללו יחד יכלו לרוץ בכל מקום במהירות רבה.","\u0003לא ירבה לו\u0004 המלך \u0003סוסים אלא כדי\u0004 הצריך ל\u0003מרכבתו\u0004 במלחמה ובשלום. \u0003\"וכסף וזהב לא ירבה לו מאד\" אלא כדי ליתן אספניא\u0004 (הספקה לחיילותיו). \u0003וכותב לו\u0004 המלך \u0003ספר תורה לשמו,\u0004 וספר תורה זה כש\u0003יוצא למלחמה\u0004 — \u0003מוציאה עמה. נכנס\u0004 — \u0003הוא מכניסה עמו. יושב בדין\u0004 — \u0003היא,\u0004 ספר התורה, \u0003עמו. מיסב\u0004 לאכול — \u0003היא כנגדו, שנאמר: \"והיתה עמו וקרא בו כל ימי חייו\"\u0004 (דברים יז, יט).","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 על הנאמר: \"רק \u0003לא ירבה לו סוסים\u0004 ולא ישיב את העם מצרימה למען הרבות סוס\" (דברים יז, טז). \u0003יכול\u0004 לא ירבה \u0003אפילו כדי מרכבתו ופרשיו\u0004 הצריכים לו? — \u0003תלמוד לומר: \"לו\"\u0004 — \u0003לו\u0004 לעצמו להנאתו הפרטית \u0003אינו מרבה, אבל מרבה הוא כדי רכבו ופרשיו. הא\u0004 \u0005[הרי]\u0006 \u0003מה אני מקיים \"סוסים\"\u0004 — כוונתו \u0003סוסים הבטלנין,\u0004 כלומר, שאינם משמשים למטרה מסויימת אלא רק להתפארות בלבד. \u0003מניין שאפילו סוס אחד והוא בטל שהוא\u0004 עובר עליו \u0003ב\"לא ירבה\"? תלמוד לומר: \"למען הרבות סוס\"\u0004 — אפילו אחד.","ושואלים: \u0003וכי מאחר\u0004 שלמדנו ש\u0003אפילו סוס אחד והוא בטל, קאי\u0004 \u0005[עומד]\u0006 עליו \u0003ב\u0004איסור \u0003\"לא ירבה\",\u0004 אם כן לשון הריבוי \u0003\"סוסים\" למה לי?\u0004 ומשיבים: כוונתו כדי \u0003לעבור ב\u0004איסור \u0003\"לא תעשה\" על כל סוס וסוס\u0004 לחוד.","ושואלים: \u0003טעמא דכתב רחמנא\u0004 \u0005[הטעם,\u0006 דווקא, \u0005שכתבה התורה]\u0006 \u0003\"\u0004לא ירבה \u0003לו\", הא לאו הכי הוה אמינא\u0004 \u0005[הרי\u0006 אם \u0005לא כך, הייתי אומר]\u0006 \u0003אפילו כדי רכבו ופרשיו נמי\u0004 \u0005[גם כן]\u0006 \u0003לא?\u0004 ודבר זה ודאי אינו מסתבר! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא \u0003לאפושי\u0004 \u0005[להרבות]\u0006 שיש לו רשות להוסיף סוסים לא רק כדי המספר ההכרחי, אלא שיהיה בידו גם עודף ידוע לשעות הצורך.","שנינו במשנה ש\u0003כסף וזהב לא ירבה לו אלא כדי ליתן אספניא. תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003\"וכסף וזהב לא ירבה לו\u0004 מאד\u0003\"\u0004 (דברים יז, יז), \u0003יכול\u0004 שלא ירבה \u0003אפילו כדי ליתן אספניא?\u0004 — \u0003תלמוד לומר \"לו\"\u0004 — \u0003לו\u0004 לעצמו להנאתו הפרטית \u0003אינו מרבה, אבל מרבה הוא כדי ליתן אספניא.\u0004","ותוהים: \u0003טעמא דכתב רחמנא\u0004 \u0005[הטעם,\u0006 דווקא, \u0005שכתבה התורה]\u0006 \u0003\"לו\", הא לאו הכי הוה אמינא\u0004 \u0005[הרי\u0006 אם \u0005לא כך, הייתי אומר]\u0006 \u0003אפילו כדי ליתן אספניא נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 ירבה כסף? והרי חייב הוא בתשלום שכר לצבאו! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא \u0003להרווחה,\u0004 שרשאי להוסיף קצת על הסכום המצומצם לצורך זה, שיהיה הממון מצוי לו בהרווחה.","ושואלים: \u0003השתא דאמרת\u0004 \u0005[עכשיו שאתה אומר]\u0006 כי \u0003\"לו\"\u0004 שכתוב בפרשתנו הוא לשון צמצום ודיוק, וכוונתו \u0003לדרשה\u0004 הלכה למעשה, מה שנאמר \u0003\"לא ירבה לו נשים\" מאי דרשת ביה\u0004 \u0005[מה אתה דורש בו]\u0006 למעט? ומשיבים: \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003הדיוטות\u0004 שאינם מלכים, שהאיסור להרבות נשים הוא במלך בלבד, וסתם אדם מישראל היכול לפרנס ולחיות עם כל הנשים שנושא — מותר לו לישא כמה שירצה.","\u0003רב יהודה רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005]:\u0006 \u0003כתיב\u0004 \u0005[נאמר]\u0006 בכתוב אחד \u0003\"ויהי לשלמה ארבעים אלף ארות סוסים מרכבתו\"\u0004 (מלכים א' ה, ו), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 במקום אחר: \u0003\"ויהי לשלמה ארבעת אלפים ארוות סוסים\u0004 ומרכבות\u0003\"\u0004 (דברי הימים ב' ט, כה), \u0003הא כיצד\u0004 יכולים אנו להשוות את הדברים? — \u0003אם ארבעים אלף איצטבלאות\u0004 (אורוות גדולות) \u0003היו, כל אחד ואחד\u0004 מהם \u0003היו בו ארבעת אלפים ארוות סוסים,\u0004 כלומר, שורות לסוסים, \u0003ואם ארבעת אלפים איצטבלאות היו, כל אחד ואחד היו בו ארבעים אלף ארוות סוסים,\u0004 ועל ידי כך מתיישבים שני הכתובים.","\u0003ר' יצחק רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005]:\u0006 \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"אין כסף נחשב בימי שלמה למאומה\"\u0004 (דברי הימים ב' ט, כ), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ויתן המלך את הכסף בירושל ם כאבנים\"\u0004 (מלכים א' י, כז), הרי שהכסף היה שווה בכל זאת משהו? ומשיבים: \u0003לא קשיא\u0004 \u0005[אינו קשה],\u0006 אפשר לתרץ: \u0003כאן\u0004 שכסף לא היה נחשב מאומה — הרי זה \u0003קודם ש\u0004חטא ו\u0003נשא שלמה את בת פרעה, כאן\u0004 שהיה הכסף חשוב — \u0003לאחר ש\u0004חטא ו\u0003נשא את בת פרעה.\u0004","\u0003אמר ר' יצחק: בשעה שנשא שלמה את בת פרעה, ירד\u0004 המלאך \u0003גבריאל ונעץ קנה בים, והעלה\u0004 אותו קנה במשך הזמן \u0003שירטון,\u0004 ונעשה מקום יבשה, \u0003ועליו נבנה כרך גדול שברומי,\u0004 כלומר, זו היתה התחלה, נקודה ראשונה, שממנה באה לבסוף מפלתם של ישראל וחורבנם בימי רומי.","\u0003ואמר ר' יצחק: מפני מה לא נתגלו טעמי תורה\u0004 ולא פירשה התורה מה היא מטרת המצוות — \u0003שהרי שתי מקראות נתגלו טעמן,\u0004 ו\u0003נכשל בהן גדול העולם\u0004 שלמה המלך. ואלו הן? — \u0003כתיב\u0004 \u0005[נאמר]\u0006 במלך: \u0003\"לא ירבה לו נשים\u0004 ולא יסור לבבו \u0003\",\u0004 \u0003אמר שלמה: אני ארבה,\u0004 שהרי אם זה הוא הטעם, משמע שמותר להרבות \u0003ולא אסור, ו\u0004בסופו של דבר \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"ויהי לעת זקנת שלמה נשיו הטו את לבבו\"\u0004 (מלכים א', יא, ד),","\u0003וכתיב\u0004 \u0005[ו\u0006כן \u0005נאמר]\u0006 \"רק \u0003לא ירבה לו סוסים\u0004 ולא ישיב את העם מצרימה\" (דברים יז, טז), \u0003ואמר שלמה: אני ארבה ולא אשיב, וכתיב\u0004 \u0005[ונאמר]\u0006 \u0003\"ותצא מרכבה ממצרים בשש\"\u0004 (מלכים א' י, כט), ללמדנו שלא רק שעשה דברים שנאסרו בתורה אלא גם נכשל בטעם שניתן להן בתורה. וזו ראיה כמה טוב שלא נכתב טעמן של המצוות, שאין אדם יכול לסמוך על חכמתו כדי לבטלן.","שנינו במשנה שהמלך \u0003כותב ספר תורה לשמו. תנא\u0004 \u0005[שנו\u0006 בתוספתא\u0005]:\u0006 \u0003ובלבד שלא יתנאה\u0004 המלך \u0003ב\u0004ספר תורה \u0003של אבותיו\u0004 לצורך זה.","\u0003אמר רבא: אף על פי שהניחו לו אבותיו לאדם ספר תורה,\u0004 יש עליו \u0003מצוה לכתוב\u0004 ספר \u0003משלו, שנאמר: \"ועתה כתבו לכם את השירה\u0004 הזאת ולמדה את בני ישראל\u0003\"\u0004 (דברים לא, יט), ללמדנו שיש מצות עשה בכתיבת התורה. \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי\u0004 ממה ששנינו: \u0003וכותב לו ספר תורה לשמו, שלא יתנאה בשל אחרים.\u0004 ונדייק: \u0003מלך\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 חייב לכתוב ספר תורה, אבל \u0003הדיוט\u0004 — \u0003לא!\u0004","ודוחים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא \u0003לשתי תורות,\u0004 כלומר, המלך מצווה לכתוב שני ספרי תורה — אחד ככל שאר ישראל, וספר נוסף משום היותו מלך. \u0003וכדתניא\u0004 \u0005[וכפי ששנינו\u0006 בברייתא\u0005],\u0006 שנאמר: \u0003\"וכתב לו את משנה\u0004 התורה הזאת על ספר מלפני הכהנים הלוים\u0003\"\u0004 (דברים יז, יח), מכאן ש\u0003כותב לשמו שתי תורות, אחת שהיא יוצאה ונכנסת עמו\u0004 בכל עת, \u0003ואחת שמונחת לו בבית גנזיו.\u0004","\u0003אותה שיוצאה ונכנסת עמו עושה אותה\u0004 קטנה מאד והיא לו \u0003כמין קמיע, ותולה\u0004 אותה \u0003בזרועו, שנאמר: \"שויתי ה' לנגדי תמיד כי מימיני בל אמוט\"\u0004 (תהלים טז, ח), \u0003אינו נכנס בה לא לבית המרחץ ולא לבית הכסא, שנאמר: \"והיתה עמו וקרא בו\"\u0004 (דברים יז, יט), וכוונתו: \u0003מקום\u0004 טהור \u0003הראוי לקראת בו.\u0004","\u0003אמר מר זוטרא, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003מר עוקבא: בתחלה ניתנה תורה לישראל בכתב עברי\u0004 שהוא הכתב הקדום \u0003ולשון הקודש, חזרה וניתנה להם בימי עזרא בכתב אשורית ולשון ארמי. ביררו להן לישראל כתב אשורית ולשון הקודש, והניחו להדיוטות כתב עברית ולשון ארמי.\u0004","ושואלים: \u0003מאן\u0004 \u0005[מי הם]\u0006 \u0003הדיוטות\u0004 אלה? \u0003אמר רב חסדא: כותאי\u0004 \u0005[הכותיים,\u0006 השומרונים\u0005].\u0006 ושואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003כתב עברית? אמר רב חסדא: כתב ליבונאה\u0004 שהוא הכתב העתיק.","\u0003תניא\u0004 \u0005[שנויה\u0006 תוספתא\u0005],\u0006 \u0003ר' יוסי אומר: ראוי היה עזרא\u0004 מצד גדולתו \u0003שתינתן תורה על ידו לישראל, אילמלא לא קדמו משה\u0004 ונתן את התורה לפניו. ש\u0003במשה הוא אומר \"ומשה עלה אל האלהים\"\u0004 (שמות יט, ג), ו\u0003בעזרא הוא אומר \"הוא עזרא עלה מבבל\u0004 והוא סופר מהיר בתורת משה אשר נתן ה' אלהי ישראל\u0003\"\u0004 (עזרא ז, ו), ויש כאן כעין לימוד גזירה שווה: \u0003מה\u0004 לשון \u0003\"עלייה\" האמור כאן\u0004 במשה כוונתו \u0003תורה, אף\u0004 לשון \u0003\"עלייה\" האמור להלן\u0004 בעזרא כוונתו \u0003תורה,\u0004 שהביא את התורה לישראל והיה ראוי ליתנה מתחילה.","\u0003במשה הוא אומר \"ואתי צוה ה' בעת ההוא ללמד אתכם חקים ומשפטים\"\u0004 (דברים ד, יד), ו\u0003בעזרא הוא אומר \"כי עזרא הכין לבבו לדרש את תורת ה' אלהיו ולעשת וללמד בישראל חק ומשפט\"\u0004 (עזרא ז, י), \u0003ואף על פי שלא ניתנה תורה\u0004 ממש \u0003על ידו,\u0004 בכל אופן \u0003נשתנה על ידו הכתב\u0004 של התורה, \u0003שנאמר:\u0004"],["\u0003\"וכתב הנשתון כתוב ארמית ומתרגם ארמית\"\u0004 (עזרא ד, ז), \"נשתוון\" — רמז שנשתנה הכתב. וראיה אחרת לכך, \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 כאשר כתבה היד על קיר היכלו של בלשאצר \u0003\"\u0004ו\u0003לא כהלין כתבא למקרא ופשרה להודעה למלכא\"\u0004 (דניאל ה, ח) \u0005[\u0006ו\u0005לא יכלו\u0006 החרטומים \u0005לקרוא\u0006 את \u0005הכתב ולהודיע את פשרו למלך],\u0006 ולא יכלו לקרוא בו משום שנכתב בכתב החדש שמסרו עזרא. \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"וכתב\u0004 לו \u0003את משנה התורה הזאת\"\u0004 (דברים יז, יח), \"משנה\" בא ללמדנו שהוא \u0003כתב הראוי להשתנות.\u0004","ושואלים: \u0003למה נקרא\u0004 כתב זה \u0003\"\u0004כתב \u0003אשורית\"?\u0004 ומשיבים: \u0003שעלה עמהם מאשור,\u0004 כלומר, מגלותם בבבל.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003רבי אומר: בתחלה בכתב זה\u0004 (שלנו, האשורי) \u0003ניתנה תורה לישראל, כיון שחטאו\u0004 — \u0003נהפך להן לרועץ\u0004 והתחילו לכתוב בכתב אחר, כתב ליבונאה, \u0003כיון שחזרו בהן\u0004 בתשובה — \u0003החזירו להם,\u0004 וחזרו לכתוב בכתב זה, \u0003שנאמר: \"שובו לבצרון אסירי התקוה גם היום מגיד משנה אשיב לך\"\u0004 (זכריה ט, יב), כלומר, שהשיב ה' לישראל את הכתב הזה שנשתנה (משנה).","אם כן שכתב זה עתיק הוא בישראל, \u0003למה נקרא שמה\u0004 של כתיבה זו \u0003\"אשורית\"?\u0004 — לפי \u0003ש\u0004היא \u0003מאושרת\u0004 (יפה ומיושרת) \u0003בכתב.\u0004","\u0003ר' שמעון בן אלעזר אומר משום\u0004 (בשם) \u0003ר' אליעזר בן פרטא שאמר משום ר' אלעזר המודעי: כתב זה לא נשתנה כל עיקר, שנאמר: \"ווי העמדים\"\u0004 (שמות כז, י). \u0003מה עמודים לא נשתנו, אף ווים לא נשתנו,\u0004 ונשארה צורתם דומה לצורת ווים. \u0003ו\u0004כן הוא \u0003אומר \"ואל היהודים ככתבם וכלשונם\"\u0004 (אסתר ח, ט), \u0003מה לשונם לא נשתנה\u0004 במשך הדורות והוא במשך כל הזמן עברית, \u0003אף כתבם לא נשתנה.\u0004","\u0003אלא מה אני מקיים \"את משנה התורה הזאת\"\u0004 האמור בספר דברים — \u0003לשתי תורות\u0004 שכותב המלך, \u0003אחת שיוצאה ונכנסת עמו, ואחת שמונחת לו בבית גנזיו. אותה שיוצאה ונכנסת עמו\u0004 — \u0003עושה אותה כמין קמיע, ותולה בזרועו, שנאמר: \"שויתי ה' לנגדי תמיד\".\u0004","ושואלים: \u0003ואידך\u0004 \u0005[והאחר]\u0006 שאיננו סבור שיש לכתוב ולתלות בזרועו, \u0003האי\u0004 \u0005[אותו]\u0006 \u0003\"שויתי\"\u0004 האמור \u0003מאי דריש ביה\u0004 \u0005[מה\u0006 הוא \u0005דורש בו]?\u0006 ומשיבים: הכתוב \u0003ההוא,\u0004 \"שיויתי ה' לנגדי תמיד\", \u0003מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 \u0003כ\u0004מו שאמר \u0003רב חנה בר ביזנא.\u0004 ש\u0003אמר רב חנה בר ביזנא אמר ר' שמעון חסידא\u0004 \u0005[החסיד]:\u0006 \u0003המתפלל צריך שיראה עצמו כאילו שכינה\u0004 עומדת \u0003כנגדו, שנאמר: \"שויתי ה' לנגדי תמיד\".\u0004","ושואלים: \u0003לר' שמעון,\u0004 ש\u0003אמר\u0004 ש\u0003כתב זה לא נשתנה\u0004 כלל, \u0003מאי\u0004 \u0005[מה\u0006 טעם\u0005]\u0006 \u0003\"לא כהלין כתבא למקרא\"\u0004 \u0005[יכלו לקרוא\u0006 את \u0005הכתב]?\u0006 \u0003אמר רב:\u0004 לא משום שהיה זה כתב חדש, אלא \u0003בגימטריא איכתיב להון\u0004 \u0005[נכתב להן],\u0006 כלומר, בכתב סתר, וכך נכתב: \u0003\"יטת יטת אידך פוגחמט\"\u0004 לפי סדר של החילופים א־ת, ב־ש וכו'.","\u0003מאי פריש להו\u0004 \u0005[מה פירש להם]?\u0006 \u0003מנא מנא תקל ופרסין\u0004 (דניאל ה, כה), ואמר: \u0003\"מנא\"\u0004 — \u0003מנא אלהא מלכותך והשלמת\u0004 \u0005[מנה אלוהים\u0006 את \u0005מלכותך והשלים אותה]\u0006 \u0003לך.\u0004 \u0003\"תקל\"\u0004 — \u0003תקלתא במאזניא והשתכחת חסיר\u0004 \u0005[שקול נשקלת במאזנים ונמצאת חסר].\u0006 \u0003\"פרסין\"\u0004 — \u0003פריסת\u0004 \u0005[נפרסה,\u0006 נשברה\u0005]\u0006 \u0003מלכותך ויהיבת\u0004 \u0005[וניתנה]\u0006 \u0003למדי ופרס\u0004 (דניאל ה, כו–כח).","\u0003ושמואל אמר:\u0004 הכל נכתב באותן אותיות אלא לא כסדרן, שנכתבו שם שלוש תיבות אחת מעל השניה \u0003\"ממתוס ננקפי אאלרן\"\u0004 והיה צורך לקרוא את הדברים מלמעלה למטה. \u0003ור' יוחנן אמר,\u0004 נכתבו בהיפוך: \u0003\"אנם אנם לקת ניסרפו\". רב אשי אמר,\u0004 נכתבו שלא כסדר כלל לפי הנוסח: \u0003\"נמא נמא קתל פורסין\".\u0004","\u0003אין רוכבין על סוסו\u0004 של המלך מפני כבודו, \u0003ואין יושבין על כסאו\u0004 של המלך, \u0003ואין משתמשין בשרביטו, ואין רואין אותו כשהוא מסתפר, ולא כשהוא ערום, ולא כשהוא בבית המרחץ.\u0004 וכל אלה מפני \u0003שנאמר: \"שום תשים עליך מלך\"\u0004 (דברים יז, טו), וכוונתו — \u0003שתהא אימתו עליך,\u0004 וכל קירבה יתירה מעין זו מבטלת אימת המלך.","\u0003אמר רב יעקב אמר ר' יוחנן: אבישג\u0004 השונמית \u0003מותרת\u0004 מצד הדין \u0003לשלמה,\u0004 אבל \u0003אסורה לאדניה\u0004 שרצה לשאתה. \u0003מותרת לשלמה\u0004 — ש\u0003מלך היה, ומלך משתמש בשרביטו של מלך,\u0004 ואף אבישג כשאר כלי תשמישו של מלך היתה, ואולם \u0003אסורה לאדניה\u0004 — ש\u0003הדיוט הוא\u0004 ואינו מלך.","ומבארים: סיפור \u0003אבישג מאי\u0004 \u0005[מה]\u0006 \u0003היא, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והמלך דוד זקן בא בימים... ויאמרו לו עבדיו יבקשו\"\u0004 (מלכים א' א, א–ב), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ויבקשו נערה יפה\"\u0004 (מלכים א' א, ג), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 \u0003\"והנערה יפה עד מאד ותהי למלך סכנת ותשרתהו\"\u0004 (מלכים א' א, ד), \u0003אמרה\u0004 לו אבישג לדוד: \u0003נינסבן\u0004 \u0005[שא אותי\u0006 לאשה\u0005]!\u0006 \u0003אמר לה: אסירת\u0004 \u0005[אסורה את]\u0006 \u0003לי\u0004 כיון שיש לי כבר שמונה עשרה נשים.","\u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003חסריה לגנבא, נפשיה לשלמא נקיט\u0004 \u0005[\u0006כאשר \u0005חסר לו לגנב\u0006 מה לגנוב, \u0005הוא עושה עצמו כאיש שלום],\u0006 ואף אתה כיון שאינך מסוגל לבעול אותי אינך רוצה לשאת אותי לאשה. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003קראו לי לבת שבע. וכתיב\u0004 \u0005[ונאמר]\u0006 \u0003\"ותבא בת שבע אל המלך החדרה\u0004 והמלך זקן מאד ואבישג השונמית משרת את המלך\u0003\"\u0004 (מלכים א' א, טו). \u0003אמר רב יהודה אמר רב: באותה שעה קינחה בת שבע בשלש עשרה מפות\u0004 (כמנין המילים בפסוק זה) אחרי שלוש עשרה בעילות, להראות שעדיין היה כוחו עימו.","\u0003אמר רב שמן בר אבא: בא וראה כמה קשין גירושין,\u0004 שלא התירום אלא מדוחק, \u0003שהרי דוד המלך התירו לו לייחד\u0004 עימו אשה בלא נישואין, \u0003ולא התירו לו לגרש\u0004 אחת מנשיו כדי שיוכל לשאת את אבישג.","\u0003אמר ר' אליעזר: כל המגרש את אשתו ראשונה, אפילו מזבח מוריד עליו דמעות, שנאמר: \"וזאת שנית תעשו כסות דמעה את מזבח ה' בכי ואנקה מאין עוד פנות אל המנחה ולקחת רצון מידכם\"\u0004 (מלאכי ב, יג), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ואמרתם על מה על כי ה' העיד בינך ובין אשת נעוריך אשר אתה בגדתה בה והיא חברתך ואשת בריתך\"\u0004 (מלאכי ב, יד).","\u0003אמר ר' יוחנן ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' אלעזר: אין אשתו של אדם מתה אלא אם כן מבקשין ממנו ממון\u0004 שהתחייב לתת \u0003ואין לו, שנאמר: \"ואם אין לך לשלם למה יקח משכבך מתחתיך\"\u0004 (משלי כב, כז), המתפרש כרמז שיקחו ממנו את אשתו.","\u0003ואמר ר' יוחנן: כל אדם שמתה אשתו ראשונה, כאילו חרב בית המקדש בימיו, שנאמר: \"בן אדם הנני לקח ממך את מחמד עיניך במגפה\u0004 ו\u0003לא תספד ולא תבכה ולוא תבוא דמעתך\"\u0004 (יחזקאל כד, טז), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ואדבר אל העם בבקר ותמת אשתי בערב\"\u0004 (יחזקאל כד, יח), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 באותו ענין: \u0003\"הנני מחלל את מקדשי גאון עזכם מחמד עיניכם\"\u0004 (יחזקאל כד, כא), נמצא שאשתו של אדם היא עבורו מחמד עיניים כמו המקדש לכללות ישראל.","\u0003אמר ר' אלכסנדרי: כל אדם שמתה אשתו בימיו, עולם חשך בעדו, שנאמר: \"אור חשך באהלו ונרו עליו ידעך\"\u0004 (איוב יח, ו), כלומר, כאשר האור חשך באהלו (ביתו זו אשתו) הרי נרו (אורו) עליו דועך. \u0003ר' יוסי בר חנינא אמר: פסיעותיו מתקצרות, שנאמר: \"יצרו צעדי אונו\"\u0004 (איוב יח, ז). \u0003ר' אבהו אמר: עצתו נופלת, שנאמר: \"ותשליכהו עצתו\"\u0004 (איוב יח, ז).","\u0003אמר רבה בר בר חנה אמר ר' יוחנן: קשה לזווגם\u0004 את האיש והאשה \u0003כקריעת ים סוף, שנאמר: \"אלהים מושיב יחידים ביתה מוציא אסירים בכושרות\"\u0004 (תהלים סח, ז), \u0003אל תיקרי \"מוציא אסירים\" אלא \"כמוציא אסירים\",\u0004 כלומר, להושיב אנשים בודדים (יחידים) ולעשות מהם משפחה (\"ביתה\"), קשה כמו להוציא את ישראל (\"כמוציא אסירים\"). ו\u0003אל תיקרי \"בכושרות\" אלא \"בכי ושירות\"\u0004 שהנישואין פעמים הם עצב ופעמים שמחה לבני הזוג.","ושואלים: \u0003איני\u0004 \u0005[וכי כן הוא]\u0006 שקשה למצוא זיווג? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב יהודה אמר רב: ארבעים יום קודם יצירת הולד בת קול יוצאת ואומרת: בת פלוני\u0004 היא תהיה אשתו של \u0003פלוני,\u0004 ואם כן הרי שאין קושי לזווגם, שהרי הם מוכנים לכך משעת בריאתם. ומשיבים: \u0003לא קשיא\u0004 \u0005[אינו קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמרנו שבת קול יוצאת, ומשמע שזיווגו של אדם מוכן לו עוד בטרם לידתו — הרי זה \u0003בזווג ראשון, הא\u0004 \u0005[זה]\u0006 שקשה לזווגם — \u0003בזווג שני.\u0004","\u0003אמר ר' שמואל בר נחמן: לכל\u0004 דבר שאבד \u0003יש תמורה, חוץ מאשת נעורים\u0004 שמתה, \u0003שנאמר: \"ואשת נעורים כי תמאס\"\u0004 (ישעיה נד, ו). \u0003מתני לה\u0004 \u0005[משנה,\u0006 מלמד, \u0005לו]\u0006 \u0003רב יהודה לרב יצחק בריה\u0004 \u0005[בנו]:\u0006 \u0003אין אדם מוצא קורת רוח אלא מאשתו ראשונה, שנאמר: \"יהי מקורך ברוך ושמח מאשת\u0004"],["\u0003נעוריך\"\u0004 (משלי ה, יח), \u0003אמר לו\u0004 רב יצחק בנו: \u0003כגון מאן\u0004 \u0005[מי]?\u0006 \u0003אמר לו: כגון אמך.\u0004","ותוהים: \u0003איני\u0004 \u0005[וכי כן הוא]?\u0006 \u0003והא מקרי ליה\u0004 \u0005[והלא קרא לו]\u0006 פעם \u0003רב יהודה לרב יצחק בריה\u0004 \u0005[בנו]\u0006 מן הכתוב: \u0003\"ומוצא אני מר ממות את האשה אשר היא מצודים וחרמים\"\u0004 (קהלת ז, כו), \u0003ואמר לו\u0004 רב יצחק: \u0003כגון מאן\u0004 \u0005[מי]?\u0006 \u0003ואמר לו\u0004 רב יהודה: \u0003כגון אמך!\u0004 ומשיבים: אין זו סתירה, אמנם \u0003מיתקף תקיפא\u0004 \u0005[קשה\u0006 היא וכועסת\u0005]\u0006 ואולם אחר כך \u0003עיבורי מעברא במלה\u0004 \u0005[מעבירה\u0006 היא \u0005על מדותיה],\u0006 ואם כך היא גם מרה ממוות וגם נוחה לו.","\u0003אמר רב שמואל בר אוניא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: אשה גולם היא,\u0004 כלומר, כלי שאינו גמור, \u0003ואינה כורתת ברית\u0004 ונעשית קשורה באמת \u0003אלא למי שעשאה כלי\u0004 על ידי בעילה, \u0003שנאמר: \"כי בעליך עשיך ה' צבאות שמו\"\u0004 (ישעיה נד, ה).","\u0003תנא\u0004 \u0005[שנה]\u0006 החכם: \u0003אין איש מת אלא לאשתו,\u0004 כלומר, היא סובלת את עיקר הכאב והצער, \u0003ו\u0004כן \u0003אין אשה מתה אלא לבעלה.\u0004 וראיות לדברים מן המקרא — \u0003אין איש מת אלא לאשתו, שנאמר: \"וימת אלימלך איש נעמי\"\u0004 (רות א, ג), שמייחס את מיתתו לגבי אשתו ולא לבניו. \u0003ואין אשה מתה אלא לבעלה, שנאמר: \"ואני בבאי מפדן מתה עלי רחל\"\u0004 (בראשית מח, ז), ואינו אומר שמתה על ילדיה.","שנינו במשנה ש\u0003אין רואין אותו,\u0004 את המלך, כשהוא מסתפר. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מלך מסתפר בכל יום. כהן גדול\u0004 מסתפר \u0003מערב שבת לערב שבת. כהן הדיוט אחד לשלשים יום.\u0004 ומסבירים: \u0003מלך מסתפר בכל יום, שנאמר: \"מלך ביפיו תחזינה עיניך\"\u0004 (ישעיה לג, יז), וצריך לדאוג בכל יום שייראה יפה. \u0003כהן גדול מערב שבת\u0004 לערב שבת, \u0003אמר רב שמואל בר נחמן אמר ר' יוחנן: הואיל ומשמרות\u0004 של כהונה \u0003מתחדשות\u0004 (מתחלפות) בכל שבוע בערב שבת, ולכך צריך הוא להסתפר כדי להיראות בכבודו בפני המשמרת החדשה. \u0003כהן הדיוט\u0004 מסתפר \u0003אחד לשלשים יום, דכתיב\u0004 \u0005[שנאמר]\u0006 בכהנים: \u0003\"וראשם לא יגלחו ופרע לא ישלחו כסום יכסמו את ראשיהם\"\u0004 (יחזקאל מד, כ), \u0003ויליף\u0004 \u0005[ולמד]\u0006 \u0003\"פרע\" \"פרע\"\u0004 בגזירה שווה \u0003מנזיר. כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 בכהן \u0003\"פרע לא ישלחו\", וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 בנזיר \u0003\"גדל פרע שער ראשו\"\u0004 (במדבר ו, ה), \u0003מה להלן\u0004 בנזיר גידול שערות של נזירות הוא לפחות \u0003שלשים\u0004 יום, \u0003אף כאן שלשים,\u0004 וצריך לספר שערו לפני שיגיע להיקרא \"פרע\", \u0003ותנן נמי\u0004 \u0005[ושנינו גם כן]\u0006 במשנה: \u0003סתם נזירות שלשים יום.\u0004","","","ושואלים: \u0003והתם מנא לן\u0004 \u0005[ושם\u0006 בנזיר \u0005מנין לנו]\u0006 שזה שיעור הזמן? \u0003אמר רב מתנה,\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"קדש יהיה\"\u0004 — \"יהיה\" \u0003בגימטריא תלתין הוו\u0004 \u0005[שלושים הם].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי: אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא לירבו\u0004 \u0005[יגדלו]\u0006 הכהנים שערות \u0003כלל\u0004 ויגלחו ראשיהם! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אי כתיב\u0004 \u0005[אילו היה נאמר]\u0006 \u0003\"לא ישלחו פרע\"\u0004 — הייתי אומר \u0003כדקאמרת\u0004 \u0005[כפי שאמרת],\u0006 \u0003השתא דכתיב\u0004 \u0005[עכשיו שנאמר]\u0006 \u0003\"ופרע\"\u0004 — כוונתו \u0003פרע\u0004 במקצת \u0003ליהוי\u0004 \u0005[שיהיה],\u0006 \u0003שלוחי\u0004 \u0005[לשלח\u0006 ממש\u0005]\u0006 בשערות גדולות \u0003לא לישלחו\u0004 \u0005[ישלחו].\u0006","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שדבר זה הוא מצוה הנובעת מן הכתובים ולא רק תקנה לשעתה, \u0003האידנא נמי\u0004 \u0005[עכשיו גם כן]\u0006 לאחר החורבן יצטרכו הכהנים להסתפר אחת לשלושים יום! ומשיבים: האיסור לכהן בגידול שערו פרע הוא \u0003דומיא\u0004 \u0005[בדומה]\u0006 לאיסורו בשתיית \u0003יין. מה יין,\u0004 דווקא \u0003בזמן ביאה\u0004 למקדש — \u0003הוא\u0004 ש\u0003אסור\u0004 לכהנים לשתות, אבל \u0003שלא בזמן ביאה\u0004 — \u0003שרי\u0004 \u0005[מותר],\u0006 \u0003אף פרועי ראש\u0004 (מגודלי שיער), \u0003בזמן ביאה\u0004 — \u0003אסור, שלא בזמן ביאה\u0004 — \u0003שרי\u0004 \u0005[מותר].\u0006 ומקשים: \u0003ו\u0004כי \u0003יין שלא בזמן ביאה שרי\u0004 \u0005[מותר]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005],\u0006 \u0003רבי אומר: אומר אני\u0004 שבאמת \u0003כהנים אסורין לשתות יין לעולם\u0004 גם בזמן הזה, \u0003אבל מה אעשה שתקנתו\u0004 — \u0003קלקלתו,\u0004 כלומר, חורבן הבית שהרס ובילבל כל סדרי הכהונה (קלקלתו) הוא שתיקן והתיר להם לשתות. \u0003ואמר אביי: כמאן שתי כהני חמרא האידנא\u0004 \u0005[כ\u0006שיטת \u0005מי שות הכהנים יין כעת]?\u0006 — \u0003כ\u0004שיטת \u0003רבי.\u0004 ומכאן נסיק: \u0003מכלל\u0004 הדברים אתה למד \u0003דרבנן אסרי\u0004 \u0005[שחכמים אוסרים\u0006 בכלל\u0005]!\u0006","","ומשיבים: \u0003התם היינו טעמא\u0004 \u0005[שם זהו הטעם]\u0006 שכן \u0003מהרה יבנה בית המקדש, ובעינן\u0004 \u0005[וצריכים אנו]\u0006 \u0003כהן הראוי לעבודה,\u0004 \u0003וליכא\u0004 \u0005[ו\u0006אם ישתו הכהנים יין הרי \u0005אין],\u0006 ולכן צריכים שלא ישתו הכהנים יין כלל כדי שיהיו ראויים לכך. ושואלים: אם כן \u0003הכא נמי\u0004 \u0005[כאן גם כן],\u0006 בענין גידול שיער, \u0003בעינא\u0004 \u0005[צריך אני]\u0006 שלעת היבנות המקדש יהיה \u0003כהן הראוי לעבודה, וליכא\u0004 \u0005[ואין]!\u0006","ומשיבים: \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003אפשר דמספר ועייל\u0004 \u0005[שיסתפר ויכנס למקדש].\u0006 ומקשים: \u0003התם נמי\u0004 \u0005[שם גם כן],\u0006 \u0003אפשר דניים פורתא ועייל\u0004 \u0005[שישן מעט ויכנס],\u0006 שהרי \u0003אמר רב אחא:\u0004 הילוך \u0003דרך\u0004 של \u0003מיל,\u0004 או \u0003שינה כל שהוא מפיגין את היין\u0004 ששתה אדם! ומשיבים: \u0003ולאו איתמר עלה\u0004 \u0005[וכי לא נאמר עליה]\u0006 על אימרה זו, \u0003אמר רב נחמן אמר רבה בר אבוה: לא שנו\u0004 שהיין מופג בכגון זה \u0003אלא ששתה כדי רביעית\u0004 בלבד, \u0003אבל\u0004 שתה \u0003יותר מכדי רביעית\u0004 — אין הדבר מועיל, כי \u0003כל שכן\u0004 ש\u0003דרך טורדתו\u0004 ומפריעה לו \u0003ושינה משכרתו\u0004 יותר, אלא אם כן ישן די צרכו.","\u0003רב אשי אמר:\u0004 החילוק בין שתיית יין וגידול שיער הוא זה: כהנים \u0003שתויי יין דמחלי\u0004 \u0005[שמחללים]\u0006 \u0003עבודה\u0004 כאשר הם נכנסים שתויים — \u0003גזרו בהו רבנן\u0004 \u0005[בהם חכמים],\u0006 \u0003פרועי ראש דלא מחלי\u0004 \u0005[שאינם מחללים]\u0006 \u0003עבודה\u0004 — \u0003לא גזרו בהו רבנן\u0004 \u0005[בהם חכמים].\u0006","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על הסבר זה, שהרי שנינו, \u0003ואלו\u0004 הן \u0003ש\u0004נידונין \u0003במיתה\u0004 בידי שמים: כהנים שנכנסו למקדש \u0003פרועי ראש, ושתויי יין.\u0004","ומעירים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003שתויי יין\u0004 שהם חייבים מיתה בבואם כך אל הקודש נאמר במפורש, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"יין ושכר אל תשת אתה ובניך\u0004 אתך בבואכם אל אהל מועד \u0003ולא תמתו\u0004 חוקת עולם לדורותיכם\u0003\"\u0004 (ויקרא י, ט). \u0003אלא פרועי ראש מנא לן\u0004 \u0005[מנין לנו]\u0006 שחייבים מיתה?","ומשיבים: \u0003דאיתקש\u0004 \u0005[שהושוו]\u0006 במקרא \u0003שתויי יין לפרועי ראש,\u0004 שכן \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"וראשם לא יגלחו ופרע לא ישלחו\"\u0004 (יחזקאל מד, כ), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 מיד אחר כך: \u0003\"ויין לא ישתו\u0004 כל כהן בבואם אל החצר הפנימית\u0003\"\u0004 (יחזקאל מד, כא), והשוואה זו נלמד: \u0003מה שתויי יין במיתה, אף פרועי ראש במיתה.\u0004","ואם כן \u0003ומינה\u0004 \u0005[וממנה,\u0006 מהשוואה זו\u0005]\u0006 עצמה תלמד: \u0003מה שתויי יין דמחלי\u0004 \u0005[שמחללים]\u0006 \u0003עבודה, אף פרועי ראש דמחלי\u0004 \u0005[שמחללים]\u0006 \u0003עבודה,\u0004 ואם כן קשה לשיטת רב אשי! ואומרים: אכן, \u0003קשיא\u0004 \u0005[קשה]\u0006 הדבר.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי: האי\u0004 \u0005[זה]\u0006 הדין \u0003עד\u0004 ש\u0003לא אתא\u0004 \u0005[בא]\u0006 \u0003יחזקאל\u0004 ולמדו \u0003מאן אמרה\u0004 \u0005[מי אמר אותו]?\u0006 ותוהים: \u0003וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 ש\u0003אמר רב חסדא: דבר זה מתורת משה רבינו לא למדנו,\u0004 שלא נאמר בה הדבר, \u0003עד שבא יחזקאל ולימדנו.\u0004 ומהו הדבר — \u0003\"כל בן נכר ערל לב וערל בשר לא יבוא אל מקדשי לשרתני\"\u0004 (יחזקאל מד, ט), ו\u0003עד\u0004 ש\u0003לא בא יחזקאל מאן אמרה\u0004 \u0005[מי אמר אותה]\u0006 הלכה זו שכהנים ערלים ומומרים אסורים בעבודה? \u0003אלא\u0004 צריכים לומר כך: דבר זה \u0003גמרא גמירי לה\u0004 \u0005[במסורת למודים אנו אותה]\u0006 וכך היו נוהגים במשך הדורות, \u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003יחזקאל ואסמכה אקרא\u0004 \u0005[והסמיך\u0006 את הדברים \u0005על הכתוב]\u0006 וכתבם. \u0003הכא נמי\u0004 \u0005[כאן גם כן],\u0006 \u0003גמרא גמירי לה\u0004 \u0005[במסורת למודים היו בו].\u0006 \u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003יחזקאל ואסמכה אקרא\u0004 \u0005[והסמיכו לכתוב].\u0006","ומעירים: \u0003וכי גמרי\u0004 \u0005[וכאשר למודים היו]\u0006 \u0003הלכה\u0004 זו — \u0003ל\u0004למד שהעושה כן חייב \u0003מיתה\u0004 בידי שמים, אבל \u0003ל\u0004ענין \u0003אחולי\u0004 \u0005[חילול]\u0006 \u0003עבודה\u0004 — \u0003לא גמירי\u0004 \u0005[למדו].\u0006","ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 משמעו של \u0003\"כסום יכסמו את ראשיהם\"\u0004 (יחזקאל מד, כ)? \u0003תנא\u0004 \u0005[שנה]\u0006 החכם: \u0003כמין תספורת לוליינית.\u0004 ושאלו: \u0003מאי\u0004 \u0005[מה\u0006 היא\u0005]\u0006 \u0003\"תספורת לוליינית\"? אמר רב יהודה אמר שמואל: תספורתא יחידאה\u0004 \u0005[תספורת יחידה],\u0006 כלומר, מיוחדת במינה. \u0003היכי דמי\u0004 \u0005[כיצד היא בדיוק]?\u0006 \u0003אמר רב אשי: ראשו של\u0004 שיער בשורה \u0003זה בצד עיקרו של זה\u0004 שבשורה השניה.","\u0003שאלו את רבי: איזהו תספורת של כהן גדול? אמר להן: צאו וראו מתספורת של בן אלעשה,\u0004 שהיה חתנו של רבי, ותספורתו זו היא תספורת של כהן גדול. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003רבי אומר: לא על חנם פיזר בן אלעשה את מעותיו\u0004 בתספורותיו, \u0003אלא כדי להראות בו\u0004 עצמו \u0003תספורת של כהן גדול.\u0004",""],["\u0003דיני ממונות בשלשה\u0004 דיינים. \u0003זה\u0004 (צד אחד) — \u0003בורר לו\u0004 דיין \u0003אחד וזה בורר לו אחד, ושניהן בוררין להן עוד אחד.\u0004 אלו \u0003דברי\u0004 \u0003ר' מאיר. וחכמים אומרים: שני דיינין בוררין להן עוד אחד.\u0004","ועוד: \u0003זה פוסל דיינו של זה וזה פוסל דיינו של זה,\u0004 אלו \u0003דברי\u0004 \u0003ר' מאיר. וחכמים אומרים: אימתי\u0004 יכול לפסול — \u0003בזמן שמביא עליהן ראיה שהן קרובין\u0004 לאחד מן הצדדים או זה לזה \u0003או פסולין\u0004 מטעם אחר, \u0003אבל אם היו כשרין או מומחין מפי בית דין\u0004 — \u0003אינו יכול לפוסלן.\u0004","ועוד: \u0003זה פוסל עדיו של זה וזה פוסל עדיו של זה,\u0004 אלו \u0003דברי\u0004 \u0003ר' מאיר, וחכמים אומרים: אימתי\u0004 יכול לפסול — \u0003בזמן שמביא עליהן ראיה שהן קרובין או פסולין, אבל אם היו\u0004 העדים \u0003כשרין\u0004 — \u0003אינו יכול לפוסלן.\u0004","בתחילה הבינו כי \"זה בורר לו אחד\" משמעו כל אחד מן הצדדים בורר לו בית דין שלם ושני בתי הדין בוררים עוד בית דין והם בסך הכל תשעה דיינים. ושואלים: \u0003מאי\u0004 \u0005[\u0006לשם \u0005מה]\u0006 \u0003זה בורר לו\u0004 בית דין \u0003אחד\u0004 \u0003ו\u0004כן \u0003זה\u0004 האחר \u0003בורר לו אחד\u0004 עד שיהיו ביחד תשעה דיינים? והלא \u0003בתלתא סגי\u0004 \u0005[בשלשה\u0006 דיינים \u0005די]!\u0006","ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003כשזה בורר לו בית דין אחד,\u0004 כשאחד מן הצדדים אומר שרצונו להתדיין בפני שלושה אלה, \u0003וזה בורר לו בית דין אחד\u0004 שאינו רוצה לידון בפני בית הדין שבחר חבירו, אזי \u0003שניהן בוררין להן עוד אחד,\u0004 כלומר, צריכים להגיע לפשרה ולהחליט על הרכב של בית דין שירצו להידון בפניו. שהרי מדובר כאן בכל שלושה הדיוטות שיש להם רשות לדון.","ותוהים: \u0003אפילו לוה מצי מעכב\u0004 \u0005[יכול לעכב]\u0006 ולומר שאיננו רוצה להתדיין בפני בית דין זה? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' אלעזר: לא שנו אלא מלוה\u0004 שיכול לסרב לבית הדין שברר הלווה ורצונו בבית דין חשוב, \u0003אבל לוה כופין אותו ודן בעירו!\u0004","ומשיבים: \u0003כדאמר\u0004 \u0003ר' יוחנן\u0004 בענין אחר: \u0003בערכאות\u0004 (בתי דין) \u0003שבסוריא שנו,\u0004 כלומר, בבתי דין של הדיוטות המצויים בסוריה, ובהם גם הלווה רשאי לסרב ולומר שאינם מומחים ואינם ראויים, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003בערכאות שבסוריא שנו. אבל\u0004 אם היה בית דין של \u0003מומחין\u0004 — \u0003לא,\u0004 אין הלווה יכול לסרב לבוא בפני בית דין של מומחים.","\u0003רב פפא אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 שמדובר בבית דין של \u0003מומחין,\u0004 אלא כאן מדברים \u0003כגון בי דינא\u0004 \u0005[בית הדין]\u0006 של \u0003רב הונא\u0004 ושל \u0003רב חסדא,\u0004 ששניהם מומחים ושניהם במקום אחד, \u0003דקאמר ליה\u0004 \u0005[שאומר לו]\u0006 הלווה למלוה, \u0003מי קא מטרחנא לך\u0004 \u0005[האם אני מטריח אותך]\u0006 בשינוי מקום? הרי שניהם נמצאים במקום אחד, ואולם מטעמים שלי אינני רוצה להתדיין בפני אחד מהם אלא בפני חבירו.","\u0003תנן\u0004 \u0005[שנינו]\u0006 במשנה: \u0003וחכמים אומרים שני דיינין בוררין להן עוד אחד. ואי סלקא דעתך כדקאמרינן\u0004 \u0005[ואם עולה על דעתך\u0006 לפרש את המשנה \u0005כפי שאמרנו]\u0006 קודם, שהכוונה היא שבררו להם בית דין שלם, \u0003בית דין, בתר דפסלי להו, אזלו ובררו להו בי דינא אחריני\u0004 \u0005[\u0006חברי \u0005בית הדין לאחר שפסלו אותם,\u0006 הם \u0005הולכים ובוררים להם בית דין אחר]?\u0006","\u0003ועוד: מאי\u0004 \u0005[מה,\u0006 איך משמעות\u0005]\u0006 זו נכנסת במילים \u0003\"זה בורר לו אחד וזה בורר לו אחד\"?\u0004","\u0003אלא הכי קאמר\u0004 \u0005[כך אמר]\u0006 במשנה, כך יש להבין: \u0003כשזה בורר לו דיין אחד\u0004 שהוא רוצה להידון בפניו \u0003וזה\u0004 הצד האחר \u0003בורר לו דיין אחד, שניהן בוררין להן עוד אחד.\u0004","שואלים: \u0003מאי שנא דעבדי הכי\u0004 \u0005[מה שונה,\u0006 מה טעם הם \u0005עושים כך]?\u0006 \u0003אמרי במערבא משמיה\u0004 \u0005[אומרים בארץ ישראל משמו]\u0006 של \u0003ר' זירא: מתוך שזה בורר לו דיין אחד וזה בורר לו דיין אחד ושניהן בוררין להן עוד אחד, יצא הדין לאמיתו.\u0004 שכל אחד מהם מניח שהדיין שהוא בירר בוודאי איננו נוטר לו שנאה, והוא מקבל עליו את פסקו.","שנינו במשנה ש\u0003חכמים אומרים\u0004 ששני הדיינים הם הבוררים להן עוד דיין אחד. ומציעים: \u0003נימא\u0004 \u0005[האם נאמר]\u0006 שבדברי \u0003רב יהודה אמר רב קמיפלגי\u0004 \u0005[נחלקו]?\u0006","ש\u0003אמר רב יהודה אמר רב: אין העדים חותמין על השטר אלא אם כן יודעים מי חותם עמהן,\u0004 שאין אדם רוצה לחתום על שטר עד שידע אם החותמים עמו הגונים הם. \u0003ר' מאיר לית ליה\u0004 \u0005[אין לו]\u0006 אינו מקבל את שיטת \u0003רב יהודה אמר רב\u0004 ולדעתו יכולים הצדדים לבחור להם דיין נוסף, ואין חוששים שמא לא ירצו הדיינים הקודמים לשבת עמו. \u0003ורבנן אית להו\u0004 \u0005[וחכמים יש להם,\u0006 הם מקבלים\u0005]\u0006 את שיטת \u0003רב יהודה אמר רב,\u0004 ולכן הדיינים עצמם צריכים לברור להם שלישי.","ודוחים: \u0003לא, דכולי עלמא אית להו\u0004 \u0005[לדעת הכל יש להם,\u0006 הם מקבלים\u0005]\u0006 את מה ש\u0003אמר רב יהודה אמר רב, ודעת הדיינין\u0004 — \u0003כולי עלמא לא פליגי דבעינן\u0004 \u0005[הכל אינם חלוקים שצריכים]\u0006 לשאול דעתם אם רוצים לישב זה עם זה, \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 היה זה אם צריך \u0003דעת בעלי דינין\u0004 גם כן, ש\u0003ר' מאיר סבר: דעת בעלי דינין נמי בעינן\u0004 \u0005[גם כן צריכים אנו]\u0006 \u0003ורבנן סברי: דעת הדיינין\u0004 — \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 ואולם \u0003דעת בעלי דינין\u0004 — \u0003לא בעינן\u0004 \u0005[אין אנו צריכים].\u0006","כיון שהזכרנו את הענין דנים בו גם \u0003גופא\u0004 \u0005[לגופו].\u0006 \u0003אמר רב יהודה אמר רב: אין העדים חותמים על השטר\u0004 אלא אם כן יודעים מי חותם עמהם. \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך],\u0006 \u0003כך היו נקיי הדעת\u0004 (אנשים בעלי תבונה והגינות) \u0003שבירושלים עושין: לא היו חותמין על השטר אלא אם כן\u0004 היו \u0003יודעין מי חותם עמהן\u0004 אם אינו פסול או מגונה. \u0003ולא היו יושבין בדין אלא אם כן היו יודעין מי יושב עמהן. ולא היו נכנסין בסעודה אלא אם כן יודעין מי מסב עמהן.\u0004","במשנה נאמר כי לדעת ר' מאיר \u0003זה פוסל דיינו\u0004 של זה וזה פוסל דיינו של זה, שיכול כל צד לפסול את דיינו של הצד השני. ותוהים: \u0003כל כמיניה דפסיל דייני\u0004 \u0005[\u0006וכי \u0005הכל בכוחו\u0006 ש\u0005הוא יכול לפסול את הדיינים],\u0006 ולומר: איני רוצה בדיין זה?","\u0003אמר\u0004 \u0003ר' יוחנן: בערכאות שבסוריא שנו\u0004 שאינן מומחים לדין והם רק הדיוטות העוסקים בכך, ולכן יכול הוא לומר שאין חפצו בהן, \u0003אבל\u0004 דיינים \u0003מומחים\u0004 הוא \u0003לא\u0004 יכול לפסול.","ושואלים: \u0003הא מדקתני סיפא\u0004 \u0005[הרי מ\u0006מה \u0005ששנינו בסופה\u0006 של אותה הלכה\u0005]\u0006 \u0003וחכמים אומרים: אימתי\u0004 יכול לפסול — \u0003בזמן שמביא ראיה שהן קרובין או פסולין. אבל אם היו כשרין או מומחין מפי בית דין\u0004 — \u0003אינו יכול לפוסלן,\u0004 הרי \u0003מכלל\u0004 הדברים אתה למד ש\u0003ר' מאיר מומחין נמי קאמר\u0004 \u0005[גם כן אמר]\u0006 שאפשר לפסול אותם, ועל כן חלקו חכמים!","ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003אבל אם היו כשרין\u0004 — \u0003נעשו כמומחין מפי בית דין, ו\u0004שוב \u0003אינו יכול לפוסלן.\u0004","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון להבנת המשנה. \u0003אמרו לו לר' מאיר: לא כל הימנו\u0004 \u0005[הכל ממנו],\u0006 לא הכל בכוחו שיוכל להיות \u0003פוסל דיין שמומחה לרבים.\u0004 משמע שאפילו במומחים חלק ר' מאיר.","ומשיבים: \u0003אימא\u0004 \u0005[אמור]\u0006 תקן: \u0003לא כל הימנו שפוסל דיין שהמחוהו רבים עליהם\u0004 כגון ערכאות שבסוריא.","\u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003לעולם פוסל והולך\u0004 את הדיינים, \u0003עד שיקבל עליו בית דין שמומחה לרבים,\u0004 אלו \u0003דברי\u0004 \u0003ר' מאיר,\u0004 ומשמע שאף ר' מאיר מסכים כי בית דין המומחה לרבים אי אפשר לפוסלו.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003עדים כמומחין דמי\u0004 \u0005[\u0006הם \u0005נחשבים],\u0006 שהרי העד איננו צריך הסמכה ודיו שהיה עד למעשה עליו הוא מעיד, ובכל זאת \u0003אמר\u0004 \u0003ר' מאיר: זה פוסל עדיו של זה וזה פוסל עדיו של זה!\u0004","ומשיבים: \u0003הא איתמר עלה\u0004 \u0005[הרי\u0006 כבר \u0005נאמר עליה],\u0006 על הלכה זו, ש\u0003אמר ריש לקיש:\u0004 וכי \u0003פה קדוש יאמר דבר זה,\u0004 כלומר, וכי ר' מאיר שהיה גדול בחכמה ובקדושה יאמר דבר תמוה כזה שיכול אדם לומר שאינו מסכים לעד מסויים? אלא \u0003תני\u0004 \u0005[שנה]\u0006 \u0003\"עדו\",\u0004 לאמור זה פוסל עדו היחיד של חבירו, שיכול הוא לומר על עד אחד שאינו רוצה לקבל את דבריו.","ומבררים: \u0003עדו למאי\u0004 \u0005[לאיזו\u0006 ענין\u0005]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003לממון\u0004 לענין שיוציאו ממון מן הנתבע על ידי עד זה, ואולם אז לשם מה לפסול אותו? \u0003רחמנא פסליה\u0004 \u0005[התורה\u0006 כבר \u0005פסלתו]\u0006 מלהעיד, שהלא מן התורה אין עד אחד נאמן! \u0003אי\u0004 \u0005[אם]\u0006 לחייב את הנתבע ב\u0003שבועה\u0004 שישבע שאינו אשם, הלא בזה \u0003הימוני מהימן כבי תרי\u0004 \u0005[\u0006הרי הוא \u0005נאמן כשנים]\u0006 שאמרה התורה שאם עד אחד מסייע לטענת התובע צריך הנתבע להשבע שאיננו חייב.","ומשיבים: \u0003לעולם\u0004 מדובר כאן בענין \u0003ממון,\u0004 \u0003לא צריכא\u0004 \u0005[נצרכה\u0006 לומר\u0005]\u0006 אלא לאופן \u0003דקבליה עליה כבי תרי\u0004 \u0005[ש\u0006קודם \u0005קיבל\u0006 את העד הזה \u0005על עצמו כ\u0006אילו היה \u0005שנים]\u0006 ואמר שאדם זה נאמן עליו, ועדותו חשובה כעדות שני עדים, ולאחר מכן התחרט ואמר שאינו מוכן לקבל עד יחיד.","ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]\u0006 בכך — \u0003דמצי הדר ביה\u0004 \u0005[ש\u0006הוא \u0005יכול לחזור בו]\u0006 מהסכמה כגון זו, ולומר שאינו נידון אלא כדין תורה, ואולם דבר זה כבר \u0003תנינא\u0004 \u0005[שנינו]\u0006 במקור אחר: \u0003אמר לו\u0004 צד אחד לחבירו \u0003\"נאמן עלי אבא\u0004 שלי שיוכל להיות דיין \u0003\",\u0004 או \u0003\"נאמן עלי אביך\",\u0004 או \u0003\"נאמנין עלי שלשה רועי בקר\u0004 שלא שנו ולא למדו \u0003\",\u0004 \u0003ר' מאיר אומר: יכול\u0004 אחר כך \u0003לחזור בו\u0004 ולומר שאינו דן אלא כדין תורה, וכאלה פסולים לדון מדין תורה. \u0003וחכמים אומרים\u0004 כי כיון שכבר מקבל עליו, \u0003אינו יכול לחזור בו.\u0004"],["\u0003ואמר רב דימי בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נחמן בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יוסף:\u0004 מדובר באופן מסויים ו\u0003כגון דקבליה עליה בחד\u0004 \u0005[שקיבל עליו\u0006 את הקרוב הזה \u0005כאחד\u0006 הדיינים\u0005]\u0006 ועמו שנים אחרים כשרים. ואם כבר נחלקו ר' מאיר וחכמים בענין חזרה כזו מדוע שנו במשנתנו דין שהוא דומה בכל דבר להלכה זו?","ומשיבים: \u0003צריכא\u0004 \u0005[נצרכה]\u0006 לומר בשני המקרים: \u0003דאי תנא\u0004 \u0005[שאילו\u0006 היה \u0005שונה]\u0006 רק \u0003\"אבא\" ו\"אביך\"\u0004 — הייתי אומר כי רק \u0003בהא קאמרי רבנן דלא מצי הדר ביה\u0004 \u0005[בזה אמרו חכמים שאינו יכול לחזור בו]\u0006 \u0003משום\u0004 ש\u0003אבא ואביך חזו לעלמא\u0004 \u0005[ראויים\u0006 הם \u0005בכלל],\u0006 שהרי כשרים הם מכל בחינה ורק בדין זה אינם רשאים לדון מפני קרבתם, \u0003אבל\u0004 לעשות \u0003חד\u0004 \u0005[אחד]\u0006 שיהיה נאמן \u0003כבי תרי\u0004 \u0005[כשנים],\u0006 \u0003דלעלמא לא חזי\u0004 \u0005[שבכלל איננו ראוי]\u0006 — \u0003אימא\u0004 \u0005[אמור]:\u0006 \u0003מודו ליה\u0004 \u0005[\u0006ש\u0005מודים\u0006 הם \u0005לו]\u0006 \u0003לר' מאיר\u0004 שבזה יוכל לחזור בו מהסכמתו. ולכן היה צורך לשנות את משנתנו.","ולהיפך, \u0003ואי אשמעינן בהא\u0004 \u0005[ואילו היה משמיע לנו\u0006 רק \u0005בזה],\u0006 בעד אחד שהאמינוהו כשנים, היינו אומרים כי דווקא \u0003בהא קאמר\u0004 \u0005[בזה אמר]\u0006 \u0003ר' מאיר\u0004 שיכול לחזור, \u0003אבל בההיא\u0004 \u0005[באותו\u0006 ענין\u0005]\u0006 של אבא ואביך — \u0003אימא\u0004 \u0005[אמור]:\u0006 שמא \u0003מודו להו לרבנן\u0004 \u0005[מודה\u0006 הוא \u0005להם, לחכמים],\u0006 על כן \u0003צריכא\u0004 \u0005[נצרכה]\u0006 לומר שניהם.","את הקושי הזה תירצנו, ואולם על עיקר ההסבר מקשים: \u0003הא מדקתני רישא\u0004 \u0005[הרי מ\u0006מה \u0005ששנינו בתחילה]\u0006 בלשון יחיד, \"זה פוסל \u0003דיינו\u0004 של זה\", \u0003וסיפא\u0004 \u0005[וסופו]\u0006 של הענין שנינו בלשון רבים, \u0003\"עדיו\", אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003דוקא\u0004 בדיוק \u0003קתני\u0004 \u0005[שנה]\u0006 ואין לתקן \"עדו\" במקום \"עדיו\".","\u0003אמר\u0004 \u0003ר' אלעזר:\u0004 כאן מדובר \u0003בבא הוא,\u0004 כלומר, אחד הצדדים \u0003ו\u0004עוד אדם \u0003אחר\u0004, \u0003לפוסלן\u0004 את העדים משום פסול שבהם.","ותוהים: \u0003כל כמיניה\u0004 \u0005[וכי הכל בכוחו]?!\u0006 והלא \u0003נוגע בעדותו הוא\u0004 וכיצד נאמין לו לפוסלם כשהוא מסייע על ידי כך לעצמו?","\u0003אמר רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא: כגון שקרא עליו ערער,\u0004 כלומר, שאיננו פוסלם בדברים סתם אלא הוא מצא מקום לערער על כשרותו ולכן אפשר לחשוב שעדותו תצטרף.","ושואלים: \u0003ערער דמאי\u0004 \u0005[של מה,\u0006 באיזה ענין\u0005]?\u0006 \u0003אילימא ערער\u0004 \u0005[אם תאמר]\u0006 \u0003דגזלנותא\u0004 \u0005[של גזלנות]\u0006 שהוא מעיד עליו שחטא בגזל או בעבירה אחרת שמחמתה הוא פסול — \u0003כל כמיניה\u0004 \u0005[וכי הכל ממנו]\u0006 וכי יכול הוא לעשות זאת? הרי \u0003נוגע בעדותו הוא\u0004 ואינו נאמן.","\u0003אלא: ערער\u0004 של \u0003פגם משפחה,\u0004 שהוא אומר שהוא פסול לעדות משום פגם שבמשפחתו, וכגון שמעיד עליו שהוא ממשפחת עבדים, ובענין זה נחלקו: \u0003ר' מאיר סבר\u0004 \u0005[סבור]:\u0006 כי \u0003הני\u0004 \u0005[אלה],\u0006 גם המתדיין וגם העד שעמו — על ה\u0003משפחה\u0004 של העד האחר \u0003קמסהדי\u0004 \u0005[הם מעידים],\u0006 שהיא משפחה פסולה, \u0003ואיהו\u0004 \u0005[והוא,\u0006 העד\u0005]\u0006 \u0003ממילא קפסיל\u0004 \u0005[נפסל]\u0006 ואין זו איפוא עדות הנוגעת ישירות למשפטו של המתדיין, \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]\u0006 כי \u0003סוף סוף נוגע בעדותו הוא,\u0004 וכיון שכך אי אפשר להאמין לו לענין דין זה.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל, \u0003אמר\u0004 בשם \u0003ר' יוחנן:\u0004 ה\u0003מחלוקת\u0004 כאן היא \u0003בשתי כיתי\u0004 \u0005[כיתות,\u0006 קבוצות\u0005]\u0006 \u0003עדים,\u0004 שאחד הצדדים אומר שיש שתי קבוצות עדים המעידות לטובתו, והצד השני טוען שקבוצה אחת של עדים פסולה היא, ובמקרה זה איננו נוגע בדבר שכן יש עדים אחרים כנגדו,","שלדעת \u0003ר' מאיר: צריך לברר\u0004 מראש אם באמת מצויים כל העדים שבעל הדין טוען שישנם, ומאחר ואכן נמצאים עדים אלה, וגם יש עדים נוספים — אין נפגע הצד המביא אותם אם נפסלת עדות של קבוצה אחת (תוס'). ואילו \u0003רבנן סברי\u0004 \u0005[חכמים סבורים]\u0006 ש\u0003אינו צריך לברר\u0004, ולכן יכול לקרות שלא יבואו העדים האחרים ובינתיים יפסיד צד אחד במשפט מפני טעם זה. \u0003אבל בכת אחת\u0004 של עדים \u0003ל\u0004\u0003דברי הכל אין יכול לפוסלן.\u0004 \u0003דאמרו\u0004","\u0003לפניו רב אמי ורב אסי\u0004 לפני ר' יוחנן: אם \u0003אין שם אלא כת אחת\u0004 של עדים \u0003מהו\u0004 הדין בכגון זה?","על שאלה זו תוהים: \u0003אין שם אלא כת אחת? והאמרת\u0004 \u0005[והרי\u0006 כבר \u0005אמרת]:\u0006 \u0003אבל בכת אחת\u0004 — \u0003דברי הכל אין יכול לפוסלן! אלא\u0004 יש לומר כי השאלה היתה זו: אם לאחר זמן אין שם אלא כת אחת וכגון ש\u0003נמצאת כת שניה קרובין או פסולין מהו?\u0004 האם יכול אותו אדם לטעון כי לא היה בעל הדין רשאי לפסול את העדים המעידים כנגדו, שהרי נתברר שאלה היו עדים יחידים?","\u0003אמר להן: כבר העידו עדים הראשונים\u0004 ונתקבלה עדותם ושוב אי אפשר לבטל עדות זו. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 כי \u0003אמר\u0004 דבר זה \u0003רב אשי\u0004 ולא ר' יוחנן: \u0003כבר העידו עדים הראשונים.\u0004","ושואלים: \u0003נימא\u0004 \u0005[האם נאמר]\u0006 כי ר' מאיר וחכמים \u0003בפלוגתא\u0004 \u0005[במחלוקת]\u0006 של \u0003רבי ורבן שמעון בן גמליאל קמיפלגי\u0004 \u0005[נחלקו]?!\u0006","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הבא לידון בשטר ובחזקה,\u0004 שהיה אדם מחזיק בקרקע וטענו כנגדו שאין הקרקע שלו, והוא טוען שנמצא בידו שטר המכירה, וטוען עוד כי כבר יש לו חזקה של שלוש שנים על הקרקע (ואינו זקוק עוד לשטר כראיה) — הריהו \u0003נידון בשטר,\u0004 שיש לברר את מהותו של שטר זה אם אמיתי הוא אם לאו, \u0003דברי רבי\u0004. \u0003ורבן שמעון בן גמליאל אומר:\u0004 הריהו \u0003נידון בחזקה.\u0004","\u0003והוינן\u0004 \u0005[ועסקנו]\u0006 \u0003בה\u0004 בהלכה זו, ותהינו: האם אמר רבן שמעון בן גמליאל שנידון \u0003בחזקה ולא בשטר,\u0004 שאינו רשאי לדון בשטר?! \u0003אלא אימא\u0004 \u0005[אמור]\u0006 כי כוונתו היא ש\u0003אף בחזקה\u0004 נידונים שיכול לסמוך על כל טענה שירצה,","\u0003וקיימא לן\u0004 \u0005[ומוחזק בידינו]\u0006 שבסיס המחלוקת הוא בשאלה האם \u0003צריך לברר פליגי\u0004 \u0005[נחלקו],\u0006 שלדעת רבי כיון שיש שטר יש לברר את היסוד הראשון של החזקה — והוא השטר, ולדעת רבן שמעון בן גמליאל יכול המחזיק בקרקע לטעון שאין צורך לברר אם השטר אמיתי שכן די בחזקה, ואין צריך לדון כלל בשטר.","ודוחים: \u0003לא,\u0004 אין שתי המחלוקות זהות, \u0003אליבא\u0004 \u0005[לשיטתו]\u0006 של \u0003רבן שמעון בן גמליאל כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים]\u0006 שאין צריך לברר, \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה \u0003אליבא\u0004 \u0005[על פי\u0006 שיטתו\u0005]\u0006 של \u0003רבי,\u0004 ש\u0003ר' מאיר\u0004 סבור \u0003כ\u0004שיטת \u0003רבי,\u0004","\u0003ורבנן אמרי\u0004 \u0005[\u0006היו יכולים \u0005לומר]\u0006 \u0003לך\u0004 כי \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003רבי התם\u0004 \u0005[שם]\u0006 שצריך לברר \u0003אלא בחזקה,\u0004 ש\u0003מכח שטרא קאתי\u0004 \u0005[השטר\u0006 היא \u0005באה],\u0006 שהרי חזקה סתם בלא טענה המסבירה כיצד הגיע לחזקה זו אין לה תוקף, \u0003אבל הכא דהני\u0004 \u0005[כאן שאלה]\u0006 ה\u0003עדים לאו\u0004 \u0005[לא]\u0006 \u0003מכח\u0004 ה\u0003עדים אחריני קאתו\u0004 \u0005[האחרים באו]\u0006 \u0003אפילו רבי מודה\u0004 ש\u0003אין צריך לברר\u0004 דברים שאין בהם צורך לענין משפט זה.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל, \u0003אמר\u0004 בשם \u0003ר' יוחנן\u0004 מסורת שונה: \u0003רישא\u0004 \u0005[בתחילה]\u0006 מדובר"],["\u0003בעדים פסולין ודיינין כשרין,\u0004 שבעל הדין טען שהעדים והדיינים פסולים והוכיח דבריו לגבי העדים, \u0003מיגו דפסלי\u0004 \u0005[מתוך שפסולים]\u0006 ה\u0003עדים,\u0004 שהרי הוכיח שצדק, \u0003פסלי נמי דייני\u0004 \u0005[פסולים גם הדיינים]\u0006 \u0003סיפא\u0004 \u0005[בסופו]\u0006 מדובר \u0003בדיינין פסולין ועדים כשרין,\u0004 שלגבי הדיינים הוכיח דבריו \u0003דמיגו דפסלי\u0004 \u0005[שמתוך שנפסלו]\u0006 ה\u0003דיינין פסלי נמי\u0004 \u0005[נפסלו גם כן]\u0006 ה\u0003עדים.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה עליה,\u0006 על סברה זו \u0005]\u0006 \u0003רבא: בשלמא\u0004 \u0005[נניח]\u0006 מה שאמרת \u0003מיגו דפסלי\u0004 \u0005[מתוך שנפסלו]\u0006 ה\u0003עדים פסלי נמי דייני\u0004 \u0005[נפסלו גם כן הדיינים],\u0006 טענה זו אפשר לקבל שכן אין בכך פגם שאין לו תקנה, שהרי \u0003איכא בי דינא אחרינא\u0004 \u0005[יש בית דין אחר],\u0006 שאפשר בקלות למצוא דיינים אחרים, \u0003אלא מיגו דפסלי דייני פסלי נמי\u0004 \u0005[מתוך שפסולים הדיינים, פסולים גם כן]\u0006 ה\u0003עדים\u0004 בלא הוכחה ו\u0003הא\u0004 \u0005[הרי]\u0006 \u0003עדים תו ליכא\u0004 \u0005[אין עוד],\u0006 וכל הדין כולו מתבטל רק משום טענת \"מיגו\" זו!","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא לאופן \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003כת אחרת\u0004 של עדים, שאותם לא פסל, ומשום כך שאין הבדל לענין הדיון פוסלים את אלה.","ושואלים: \u0003הא ליכא\u0004 \u0005[הרי\u0006 אם \u0005אין]\u0006 \u0003כת אחרת\u0004 של עדים, \u0003מאי\u0004 \u0005[מה\u0006 יהא הדין\u0005]\u0006 \u0003הכי נמי דלא מצי פסלי\u0004 \u0005[כך גם כן\u0006 תאמר \u0005שאינם יכולים לפסול],\u0006 אם כן \u0003היינו\u0004 \u0005[זהו]\u0006 בדיוק מה שאמר \u0003רב דימי\u0004 שמדובר בשתי כתות עדים.","ומסבירים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל למעשה לענין \u0003מיגו\u0004 זה, \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 רבין \u0005סבור]\u0006 ש\u0003אמרינן\u0004 \u0005[אומרים אנו]\u0006 \u0003מיגו,\u0004 שמתוך שנמצאו דבריו נכונים בדבר אחד הריהם מן הסתם נכונים גם בטענה אחרת. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 רב דימי, \u0005סבור]\u0006 ש\u0003לא אמרינן\u0004 \u0005[אומרים אנו]\u0006 \u0003מיגו,\u0004 אלא צריך להוכיח דבריו בכל דבר לגופו.","ודנים עוד \u0003גופא\u0004 \u0005[\u0006ל\u0005גופם]\u0006 של דברים \u0003אמר ריש לקיש:\u0004 וכי \u0003פה קדוש יאמר דבר זה,\u0004 כלומר, וכי ר' מאיר שהיה גדול בחכמה ובקדושה יאמר דבר תמוה כזה שיכול אדם לומר שאינו מסכים לעד מסויים? אלא \u0003תני\u0004 \u0005[שנה]\u0006 \u0003\"עדו\"\u0004 בלשון יחיד.","ומקשים: \u0003איני\u0004 \u0005[וכי כן]\u0006 בלשון זו של ענוה והתבטלות דיבר ריש לקיש?! \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003עולא: הרואה את ריש לקיש\u0004 עוסק בתורה \u0003בבית המדרש\u0004 נדמה הוא לו \u0003כאילו עוקר הרים וטוחנן זה בזה,\u0004 משמע שאדם גדול וחריף ביותר היה!","\u0003אמר רבינא:\u0004 בדבר זה אין קושי, \u0003והלא כל הרואה\u0004 את \u0003ר' מאיר בבית המדרש\u0004 נדמה הוא לו \u0003כאילו עוקר הרי הרים וטוחנן זה בזה,\u0004 שר' מאיר גדול היה בחכמה מריש לקיש וראוי שריש לקיש יטרח ויישב את דבריו!","ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר],\u0006 לא שריש לקיש גדול יותר, אלא \u0003בא וראה כמה מחבבין זה את זה,\u0004 שאף שהיה ריש לקיש גדול בתורה וחריף מאד לא דיבר על ר' מאיר אלא בלשון כבוד זו.","וכיוצא בו \u0003כי הא\u0004 \u0005[כמו\u0006 מעשה \u0005זה]\u0006 \u0003דיתיב\u0004 \u0005[שישב]\u0006 \u0003רבי וקאמר\u0004 \u0005[ואמר]:\u0006 \u0003אסור להטמין את הצונן\u0004 בשבת במקום צונן שלא יתחמם בו, משום שהוא נראה כמטמין את החמין, שיש בכך חשש בישול בשבת. \u0003אמר לפניו\u0004 \u0003ר' ישמעאל בר' יוסי: אבא,\u0004 ר' יוסי, \u0003התיר להטמין את הצונן. אמר להם\u0004 רבי לשואלים: \u0003כבר הורה זקן,\u0004 כלומר, יש כבר לפנינו הוראה של ר' יוסי, ואני מבטל את דברי מפני דבריו.","ועל כך העיר \u0003רב פפא: בא וראה כמה מחבבין זה את זה.\u0004 ש\u0003אילו\u0004 היה \u0003ר' יוסי קיים\u0004 (חי), הרי אף הוא \u0003היה כפוף\u0004 בהכנעה \u0003ויושב לפני רבי\u0004 כתלמיד, \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003ר' ישמעאל ב\u0004\u0003ר' יוסי ממלא מקום אבותיו הוה,\u0004 כלומר, גדול היה כאביו בחכמה \u0003והיה כפוף ויושב לפני רבי\u0004, ובכל זאת \u0003קא אמר\u0004 \u0005[אמר]\u0006 רבי: \u0003כבר הורה זקן\u0004 מפני חיבתו וכבודו של ר' יוסי.","וביטויים אלה מתקשרים במה ש\u0003אמר\u0004 \u0003ר' אושעיא: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"ואקח לי שני מקלות לאחד קראתי נעם ולאחד קראתי חבלים\"\u0004 (זכריה יא, ז) \u0003\"נועם\"\u0004 — \u0003אלו תלמידי חכמים שבארץ ישראל שמנעימין זה לזה בהלכה,\u0004 שאף בשעת ויכוח נוהגים הם כבוד וחיבה זה בזה, וכפי שראינו. \u0003\"חובלים\"\u0004 — \u0003אלו תלמידי חכמים שבבבל שמחבלים זה לזה בהלכה,\u0004 שבשעת הויכוח הם חריפים וקשים ואינם נוחים זה לזה.","וכעין זה נאמר שם: \u0003\"ויאמר אלה שני בני היצהר העמדים\u0004 על אדון כל הארץ\u0003\"\u0004 (זכריה ד, יד), ונאמר: \u0003\"ושנים זיתים עליה\u0004 אחד מימין הגולה ואחד על שמאלה\" (זכריה ד, ג) \u0003\"יצהר\"\u0004 — \u0003אמר ר' יצחק: אלו תלמידי חכמים שבארץ ישראל שנוחין זה לזה בהלכה כשמן זית\u0004 שאיננו חריף. \u0003\"ושנים זיתים עליה\"\u0004 — \u0003אלו תלמידי חכמים שבבבל שמרורין זה לזה בהלכה כזית.\u0004","כיון שהוזכרו פסוקי ספר זכריה מביאים מה שנאמר שם עוד: \u0003\"ואשא עיני וארא והנה שתים נשים יוצאות ורוח בכנפיהם ולהנה כנפים ככנפי החסידה ותשנה האיפה בין השמים ובין הארץ. ואמר אל המלאך הדבר בי אנה המה מולכות את האיפה. ויאמר אלי לבנות לה בית בארץ שנער\"\u0004 (זכריה ה, ט –יא). \u0003אמר\u0004 \u0003ר' יוחנן משום\u0004 (בשם) \u0003ר' שמעון בן יוחאי:\u0004 \"איפה\" \u0003זו\u0004 משמעה \u0003חנופה וגסות הרוח שירדו לבבל.\u0004","ושואלים: \u0003ו\u0004כי \u0003גסות הרוח\u0004 \u0003לבבל נחית\u0004 \u0005[ירדה]?\u0006 \u0003והאמר מר\u0004 \u0005[והרי אמר החכם]\u0006 \u0003עשרה קבין גסות\u0004 הרוח \u0003ירדו לעולם תשעה נטלה עילם ואחת כל העולם כולו!\u0004","ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 בתחילה גסות הרוח \u0003לבבל נחית\u0004 \u0005[ירדה]\u0006 \u0003ואישתרבובי דאישתרבב\u0004 \u0005[השתרבבה\u0006 ויצאה\u0005]\u0006 \u0003לעילם\u0004 ולא נשארה בבבל. ומעירים: \u0003דיקא נמי\u0004 \u0005[מדוייק גם כן],\u0006 \u0003דכתיב \"לבנות לה בית בארץ שנער\"\u0004 (זכריה ה, ט –יא) כלומר: זו היתה הכוונה, אבל בפועל לא בנתה שם אלא במקום אחר. ומסכמים, אכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","ושואלים: \u0003והאמר מר\u0004 \u0005[והרי\u0006 כבר \u0005אמר החכם]\u0006 \u0003סימן לגסות הרוח\u0004 — \u0003עניות, ו\u0004הרי \u0003עניות לבבל נחית\u0004 \u0005[ירדה]!\u0006 ומשיבים: \u0003מאי\u0004 \u0005[מה\u0006 היא\u0005]\u0006 אותה \u0003עניות\u0004 שהיא סימן לגסות הרוח — \u0003עניות תורה,\u0004 ודבר זה היה בעילם ולא בבבל. וכן דרשו על הכתוב \u0003\"אחות לנו קטנה ושדים אין לה\"\u0004 (שיר השירים ח, ח) \u0003אמר\u0004 \u0003ר' יוחנן:\u0004 \u0003זו עילם שזכתה ללמוד,\u0004 שהיו בה אמנם תלמידים שלמדו תורה \u0003ולא זכתה ללמד,\u0004 שלא הגיעו למעלה שיוכלו להיות מרביצי תורה ברבים.","ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 מדרש המלה \u0003\"בבל\" אמר\u0004 \u0003ר' יוחנן:\u0004 שהיא מלאה דברים מעולים — \u0003בלולה במקרא, בלולה במשנה, בלולה בתלמוד,\u0004 וכל זה לשבחה של בבל היהודית וחכמיה. ואולם חכמים אחרים ראו את הענין אחרת ועל הכתוב \u0003\"במחשכים הושיבני כמתי עולם\"\u0004 (איכה ג, ו) \u0003אמר\u0004 \u0003ר' ירמיה: זה תלמודה של בבל,\u0004 שלדעתו איננו בהיר ומחוור כתלמודה ולימודה של ארץ ישראל.","\u0003אמר לו\u0004 מתדיין אחד לחבירו: \u0003נאמן עלי אבא\u0004 לדון אותי, או \u0003נאמן עלי אביך,\u0004 או \u0003נאמנים עלי שלשה רועי בקר.\u0004 \u0003ר' מאיר אומר: יכול לחזור בו\u0004 לאחר זמן, ולומר: איני דן אלא כדין תורה ואלה אינם כשרים מן התורה לדון בדין זה. \u0003וחכמים אומרים: אינו יכול לחזור בו.\u0004","וכיוצא בדבר מי ש\u0003היה חייב לחבירו שבועה\u0004 על פי דין תורה, שהיא על ידי החזקת חפץ של קדושה ושבועה עליו, \u0003ואמר לו:\u0004 במקום שבועה די אם \u0003דור\u0004 (נדור) \u0003לי בחיי ראשך,\u0004 \u0003ר' מאיר אומר: יכול לחזור בו\u0004 ולומר שאינו מקבל נדר זה כראיה ורצונו בשבועה כדינה, \u0003וחכמים אומרים: אין יכול לחזור בו,\u0004 אלא כיון שקיבל על עצמו אינו יכול לחזור.","\u0003אמר רב דימי בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נחמן בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יוסף\u0004 מה ששנינו במשנתנו \"נאמן עלי אבא ואביך\", מדובר \u0003כגון דקבליה עליה בחד\u0004 \u0005[שקיבל אותו עליו ב\u0006דיין \u0005אחד],\u0006 ששנים אחרים, כשרים, מצטרפים לו ולא שקיבלו שהוא לבדו ידון כשלושה.","\u0003אמר רב יהודה אמר שמואל: מחלוקת\u0004 ר' מאיר וחכמים \u0003ב\u0004אומר לו \u0003\"מחול לך\",\u0004 כלומר, כאשר התובע הוא שמציע שיהא נאמן עלי אבא, ואם תשמע לדבריו — הרי מחול לך אם יזכוך מן התביעה. \u0003אבל ב\u0004אומר לו \u0003\"אתן לך\",\u0004 שהנתבע אומר: אני מוכן לקבל על עצמי את דינם של דיינים ואתן לך ככל שישיתו עלי בפסק דינם, בכגון זה \u0003דברי הכל יכול לחזור בו. ור' יוחנן אמר: ב\"אתן לך\" מחלוקת.\u0004","דברי ר' יוחנן לא היו ברורים דיים, ולכן \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 מה שאמר ר' יוחנן כי \u0003ב\"אתן לך\" מחלוקת,\u0004 האם כוונתו לומר: \u0003אבל ב\"מחול לך\"\u0004 — \u0003דברי הכל אין יכול לחזור בו, או דילמא\u0004 \u0005[שמא]\u0006 התכון ר' יוחנן לומר ש\u0003בין בזו ובין בזו מחלוקת?\u0004","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ש\u0003אמר רבא: מחלוקת ב\"אתן לך\", אבל ב\"מחול לך\"\u0004 — \u0003דברי הכל אין יכול לחזור בו.\u0004","ולכאורה \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 שר' יוחנן אמר כי \u0003ב\"אתן לך\" מחלוקת אבל ב\"מחול לך\"\u0004 ל\u0003דברי הכל אין יכול לחזור בו,\u0004 הרי נמצא ש\u0003רבא\u0004 הוא ש\u0003אמר כר' יוחנן. אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שר' יוחנן התכוון לומר כי \u0003בין בזו ובין בזו מחלוקת,\u0004 אם כן \u0003רבא\u0004 ש\u0003אמר כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]?\u0006 — לא כשמואל ולא כר' יוחנן!","ודוחים: אין מכאן ראיה, ושמא \u0003רבא טעמא דנפשיה קאמר\u0004 \u0005[טעם של עצמו אמר],\u0006 שיטה שאינה כדברי האמוראים שקדמוהו.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב אחא בר תחליפא לרבא\u0004 מאותו ענין ששנינו: מי ש\u0003היה חייב לחבירו שבועה ואמר לו: \"דור לי בחיי ראשך\".\u0004 \u0003ר' מאיר אומר: יכול לחזור בו\u0004 ולומר ששוב אין רצונו בנדר זה אלא בשבועה כדינה, \u0003וחכמים אומרים: אין יכול לחזור בו.\u0004"],["\u0003מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר כאן \u0003באותן הנשבעין ולא משלמין,\u0004 כלומר, באותם מקרים כאשר הנתבע צריך להשבע שאין התביעה נכונה והוא נפטר, \u0003דהוה ליה\u0004 \u0005[שהרי זה]\u0006 איפוא עוסק במקרה של \u0003\"מחול לך\".\u0004","ודוחים: \u0003לא,\u0004 מדובר כאן \u0003באותן הנשבעין ונוטלין,\u0004 שיש מקרים מסוימים בהם אדם נשבע על טענתו ונוטל ממון, \u0003דהוה ליה\u0004 \u0005[שהרי הוא]\u0006 ענין של \u0003\"אתן לך\".\u0004","ושואלים: \u0003והא תנא ליה רישא\u0004 \u0005[והרי\u0006 כבר \u0005שנה בתחילה]\u0006 דין זה, לענין דיינים, ואם ב\"אתן לך\" מדובר מה איפוא החידוש שבדבר?","ומשיבים: \u0003תנא\u0004 \u0005[שנה]\u0006 כאן \u0003תולה בדעת אחרים,\u0004 בדעת אבא או אביך, \u0003ותנא\u0004 \u0005[ושנה]\u0006 גם \u0003תולה בדעת עצמו,\u0004 כלומר, בצד השני.","ומסבירים \u0003וצריכא\u0004 \u0005[ונצרכו]\u0006 שני הדברים, \u0003דאי תנא\u0004 \u0005[שאילו שנה]\u0006 רק \u0003תולה בדעת אחרים,\u0004 היינו אומרים כי דווקא \u0003בהא קאמר\u0004 \u0005[בזה אמר]\u0006 \u0003ר' מאיר דמצי הדר ביה\u0004 \u0005[שיכול לחזור בו]\u0006 \u0003משום\u0004 ש\u0003לא גמר\u0004 בלבו \u0003ומקני\u0004 \u0005[והקנה]\u0006 את הדבר, שלא הסכים הסכמה גמורה ומלאה לויתור, ש\u0003אמר מי יימר דמזכי ליה\u0004 \u0005[מי יאמר שיזכה אותו]?\u0006 ולא היה כאן ויתור מראש על זכויותיו, \u0003אבל תולה בדעת עצמו\u0004 שהוא אומר במפורש: עשה כך וכך והפטר \u0003אימא מודי להו לרבנן\u0004 \u0005[אמור\u0006 ש\u0005מודה\u0006 הוא \u0005להם לחכמים]\u0006 שכיון שגמר וויתר על זכויותיו אינו יכול עוד לחזור בו.","ולהיפך, \u0003ואי אשמעינן בהא\u0004 \u0005[ואילו היה משמיע לנו בזה],\u0006 בתולה בדעת עצמו, היינו אומרים: \u0003בהא קאמרי רבנן\u0004 \u0005[בזה אמרו חכמים]\u0006 שאינו יכול לחזור בו, \u0003אבל בההיא\u0004 שתולה בדעת אחרים — \u0003אימא מודו ליה רבנן\u0004 \u0005[אמור\u0006 ש\u0005מודים לו חכמים]\u0006 \u0003לר' מאיר,\u0004 על כן \u0003צריכא\u0004 \u0005[נצרכה]\u0006 לומר בשני המקרים.","\u0003אמר ריש לקיש: מחלוקת\u0004 זו בין ר' מאיר וחכמים אם יכול או אינו יכול לחזור, היא \u0003לפני גמר דין,\u0004 שלדעת ר' מאיר עדיין יכול לחזור בו. \u0003אבל לאחר גמר דין\u0004 שנתחייב בדינו \u0003דברי הכל אין יכול לחזור בו. ור' יוחנן אמר: לאחר גמר דין מחלוקת.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 האם כוונת ר' יוחנן לומר כי \u0003לאחר גמר דין מחלוקת, אבל לפני גמר דין דברי הכל\u0004 אפילו לדעת חכמים \u0003יכול לחזור בו, או דילמא\u0004 \u0005[שמא]\u0006 כוונתו היתה: \u0003בין בזו ובין בזו מחלוקת?\u0004","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ש\u0003אמר רבא:\u0004 מי ש\u0003קיבל עליו קרוב או פסול\u0004 כדיין או כעד, אם היה זה \u0003לפני גמר דין\u0004 — \u0003יכול לחזור בו, לאחר גמר דין\u0004 — \u0003אין יכול לחזור בו.\u0004","ונצרף את הדברים: \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 כי \u0003לאחר גמר דין מחלוקת,\u0004 אבל \u0003לפני גמר דין דברי הכל יכול לחזור בו,\u0004 הרי ש\u0003רבא\u0004 \u0003אמר\u0004 כשיטת \u0003ר' יוחנן ואליבא דרבנן\u0004 \u0005[ועל פי שיטת חכמים]\u0006 וכן מסתבר לפסוק. \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 כי \u0003בין בזו בין בזו מחלוקת, רבא\u0004 ש\u0003אמר כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 אמר דבריו?","\u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 כי \u0003לאחר גמר דין מחלוקת\u0004 ולא לפני כן. ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן].\u0006","\u0003שלח ליה רב נחמן בר רב חסדא לרב נחמן בר יעקב\u0004 שאלה זו: \u0003ילמדנו רבינו, לפני גמר דין מחלוקת או לאחר גמר דין מחלוקת, והלכה כדברי מי? שלח ליה\u0004 רב נחמן בר יעקב בתשובה: \u0003לאחר גמר דין מחלוקת, והלכה כדברי חכמים.\u0004","\u0003רב אשי\u0004 היתה לו מסורת אחרת ולפיה \u0003הכי\u0004 \u0005[כך]\u0006 \u0003שלח ליה\u0004 \u0005[לו],\u0006 בשאלה: האם \u0003ב\"אתן לך\" מחלוקת או ב\"מחול לך\" מחלוקת, והלכה כדברי מי?\u0004 ו\u0003שלח ליה\u0004 \u0005[לו]\u0006 בתשובה: \u0003ב\"אתן לך\" מחלוקת, והלכה כדברי חכמים.\u0004","\u0003בסורא מתני הכי\u0004 \u0005[היו שונים כך]\u0006 כפי הדברים שלמדנו עד כאן. ואילו \u0003בפומבדיתא מתני הכי\u0004 \u0005[\u0006היו \u0005שונים כך],\u0006 \u0003אמר ר' חנינא בר שלמיה: שלחו ליה מבי\u0004 \u0005[לו מבית\u0006 מדרשו\u0005]\u0006 של \u0003רב\u0004 \u0003לשמואל,\u0004 \u0003ילמדנו רבינו\u0004 אם היה זה \u0003לפני גמר דין,\u0004 אבל \u0003קנו מידו\u0004 של אחד הצדדים ועשה מעשה של קנין שבו הקנה את הזכויות שיש לו, \u0003מאי\u0004 \u0005[מה\u0006 הדין\u0005],\u0006 האם יכול לחזור בו, או לא? \u0003שלח להו\u0004 \u0005[להם]\u0006 שמואל בתשובה: \u0003אין לאחר קניין כלום,\u0004 שכל העושה קנין שוב אינו יכול לחזור בו בכל מקרה.","\u0003ואלו הן הפסולין\u0004 לעדות ולדון מפני מעשיהם הרעים, שהם בגדר \"עד חמס\" הפסול להעיד: \u0003המשחק בקוביא והמלוה בריבית ומפריחי יונים וסוחרי שביעית.\u0004","\u0003אמר\u0004 \u0003ר' שמעון: בתחילה היו קורין אותן \"אוספי שביעית\", משרבו האנסין חזרו לקרותן \"סוחרי שביעית\".\u0004","\u0003אמר\u0004 \u0003ר' יהודה: אימתי\u0004 פסולים כל אלה שמנינו — \u0003בזמן שאין להן אומנות אלא הוא\u0004 ואינם עוסקים בכל מקצוע אחר, \u0003אבל\u0004 אם \u0003יש להן אומנות\u0004 אחרת \u0003שלא הוא\u0004 — הרי אלה \u0003כשרין.\u0004","ומבררים את מה ששנינו במשנתנו: \u0003משחק בקוביא מאי קא עביד\u0004 \u0005[מה\u0006 הוא \u0005עושה],\u0006 מה טעם יפסל לעדות בשל כך? \u0003אמר רמי בר חמא: משום דהוה\u0004 \u0005[שהוא]\u0006 \u0003אסמכתא.\u0004 כלומר, הבטחה לתת דברים שאין הקנאתם בשלמות מתוך ידיעה ברורה, אלא מתוך הנחה שלא יצטרך בסופו של דבר לתת מה שהבטיח. \u0003ואסמכתא לא קניא\u0004 \u0005[אינה קונה],\u0006 שהרי הנותן לא גמר בלבו לתת מה שנתן. ומי שמרוויח כספים במשחקי מזל, הריהו נהנה מכסף שאינו שלו על פי דין, והוא נחשב כגזלן.","\u0003רב ששת אמר: כל כי האי גוונא לאו\u0004 \u0005כל\u0006 דבר \u0005כעין זה לא]\u0006 \u0003אסמכתא היא,\u0004 שבמשחק בקוביה שני הצדדים מוותרים זה לזה מראש וביודעים על מה שהם עלולים להפסיד, שהרי אינם יכולים להניח שרק אחד מהם ירוויח. \u0003אלא\u0004 הטעם הוא \u0003לפי שאין עסוקין ביישובו של עולם,\u0004 בעבודה יצרנית ומועילה וכספם בא להם בקלות יתירה בלא טורח, ואנשים כאלה אף אינם מקפידים על ממונם של אחרים, ואין לסמוך על עדותם.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל למעשה \u0005ביניהם],\u0006 בין רמי בר חמא ורב ששת? ומסבירים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005]\u0006 באופן \u0003דגמר אומנותא אחריתי\u0004 \u0005[שלמד אומנות אחרת]\u0006 והוא עוסק גם בה.","\u0003ותנן\u0004 \u0005[ו\u0006כן \u0005שנינו\u0006 במשנתנו\u0005],\u0006 \u0003אמר\u0004 \u0003ר' יהודה: אימתי\u0004 הם פסולים — \u0003בזמן שאין להם אומנות אלא הוא, אבל\u0004 אם \u0003יש להן אומנות שלא הוא\u0004 — \u0003הרי זה כשרים, אלמא\u0004 \u0005[מכאן]\u0006 \u0003טעמא דמתניתין\u0004 \u0005[טעם משנתנו]\u0006 \u0003משום יישובו של עולם הוא\u0004 ולא משום פסול שבעצם המעשה. ואומרים: אם כן, \u0003קשיא\u0004 \u0005[קשה]\u0006 הדבר \u0003ל\u0004שיטת \u0003רמי בר חמא,\u0004","\u0003וכי תימא פליגי רבנן עליה\u0004 \u0005[ואם\u0006 \u0003תאמר\u0004 ש\u0005חלוקים חכמים עליו]\u0006 על \u0003ר' יהודה\u0004 ודעתם שונה מדעתו, \u0003והאמר ר' יהושע בן לוי: כל מקום שאמר ר' יהודה\u0004"],["\u0003\"אימתי\"\u0004 או \u0003\"במה\u0004 דברים אמורים \u0003\"\u0004במשנה — \u0003אינו אלא לפרש דברי חכמים,\u0004 שאין דעתו שונה מדעת התנא הראשון אלא רק לפרש דבריו ויש להבין את המשנה כולה כיחידה אחת, ואילו","\u0003ר' יוחנן אמר:\u0004 כשאומר \u0003\"אימתי\"\u0004 — הרי הוא בא \u0003לפרש\u0004 את דברי חכמים, ואילו כשאומר \u0003\"במה\u0004 דברים אמורים \u0003\"\u0004הרי הוא בא \u0003לחלוק. ו\u0004על כל פנים \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003\"אימתי\" לפרש הוא,\u0004 ודברי ר' יהודה במשנתנו זהים לדברי התנא הראשון, וקשה לרמי בר חמא!","ודוחים: וכי \u0003גברא אגברא קא רמית\u0004 \u0005[\u0006מ\u0005אדם על אדם אתה משליך,\u0006 מראה סתירה\u0005],\u0006 כלומר, אין להקשות משיטתו של אמורא אחד על חבירו. שכן יתכן לומר כי \u0003מר סבר פליגי\u0004 \u0005[חכם זה,\u0006 רמי בר חמא, \u0005סבור\u0006 ש\u0005חלוקים],\u0006 ר' יהודה וחכמים אף כשנוקט ר' יהודה בלשון \"אימתי\", \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' יהושע בן לוי ור' יוחנן, \u0005סבור]\u0006 ש\u0003לא פליגי\u0004 \u0005[חלוקים].\u0006","ושואלים: \u0003ולא פליגי\u0004 \u0005[וכי\u0006 באמת \u0005אין חלוקים]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003בין שיש לו אומנות\u0004 אחרת \u0003שלא הוא, בין שאין לו אומנות\u0004 אחרת \u0003אלא הוא\u0004 — \u0003הרי זה פסול,\u0004 הרי שיש חכם הסבור שעצם העיסוק בדברים אלה פוסל, וכדברי רמי בר חמא!","ומשיבים: הברייתא \u0003ההיא\u0004 לא כדעת חכמים שבמשנתנו היא, אלא כשיטת \u0003ר' יהודה\u0004 שאמר \u0003משום\u0004 (בשם) \u0003ר' טרפון. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 היו שני אנשים מתערבים על דבר מה ואומרים שאם ימצאו דבריהם בלתי נכונים הריהם מקבלים על עצמם נזירות, \u0003ר' יהודה אומר משום\u0004 \u0003ר' טרפון:\u0004 \u0003לעולם אין אחד מהם נזיר, לפי שלא נתנה נזירות אלא להפלאה.\u0004 כלומר, הנזירות צריכה להיות מבוררת (\"מופלאה\", מופלית, ברורה) ואם היה נדרו שלא במלוא הוודאות והבהירות — שוב אין כאן נזירות. ולפי אותה שיטה אף בדיני קניינים סבור ר' טרפון שאדם יכול לקנות מחבירו רק דבר שהקנה לו בוודאות ובהחלטה גמורה. והמשחקים בקוביה, כיון שאין בידם וודאות זו, שהרי כל אחד מהם סבור שירוויח — הרי זו אסמכתא שאינה קונה, והנהנה ממנה הרי הוא כגזלן. אבל דעת יחיד היא.","שנינו במשנה כי ה\u0003מלוה ברבית\u0004 פסול לעדות. \u0003אמר רבא: לוה ברבית פסול לעדות\u0004 שכן גם הוא שותף לעבירה, הלוואה בריבית. ושואלים: \u0003והאנן תנן\u0004 \u0005[והרי אנחנו שנינו]\u0006 כי \u0003מלוה ברבית\u0004 פסול, משמע: רק הוא בלבד! ומשיבים: הכוונה היא \u0003מלוה הבאה\u0004 \u0003ברבית\u0004 וכל השותפים בהלוואה הבאה בריבית כולם פסולים.","מסופר: \u0003בר ביניתוס אסהידו ביה תרי סהדי\u0004 \u0005[העידו בו שני עדים]\u0006 \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: קמי דידי אוזיף בריביתא\u0004 \u0005[לפני\u0006 היה המעשה ש\u0005הלוה בריבית]\u0006 \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: לדידי אוזפי בריביתא\u0004 \u0005[לי הלווה בריבית].\u0006 \u0003פסליה\u0004 \u0005[פסלו]\u0006 \u0003רבא לבר ביניתוס\u0004 לעדות ולדין.","ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רבא הוא\u0004 ש\u0003אמר\u0004 שה\u0003לוה ברבית פסול לעדות, והוה ליה\u0004 \u0005[והרי הוא]\u0006 מכאן \u0003רשע,\u0004 \u0003והתורה אמרה \"אל תשת רשע עד\"\u0004 (ראה שמות כג, א), ולכן אותו עד שהעיד שבר ביניתוס הלווה לו בריבית העיד ממילא גם על עצמו שהוא רשע, וכיצד אפשר לקבל את עדותו?","ומשיבים: \u0003רבא\u0004 הולך \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר רבא: אדם קרוב אצל עצמו\u0004 וכדין קרוב, \u0003ואין אדם משים עצמו רשע,\u0004 ולכן את אותו חלק העדות שנוגע בעצמו — אין אנו מקבלים, אבל אנו מקבלים את חלק העדות הנוגע לאחרים.","\u0003ההוא טבחא דאישתכח דנפקא טריפתא מתותי ידיה\u0004 \u0005[שוחט אחד שנמצא שיצאה טריפה מתחת ידו]\u0006 וחס על ממונו ולא הכריז שטריפה היא, \u0003פסליה\u0004 \u0005[פסלו]\u0006 \u0003רב נחמן\u0004 לעדות \u0003ועבריה\u0004 \u0005[\u0006\u0005והעבירו]\u0006 מלהיות שוחט עוד. \u0003אזל רבי מזיה וטופריה\u0004 \u0005[הלך\u0006 ו\u0005גידל\u0006 את \u0005צפרניו ושערותיו]\u0006 מתוך חרטה כדרך אדם העושה תשובה גדולה. \u0003סבר\u0004 \u0005[חשב]\u0006 \u0003רב נחמן לאכשוריה\u0004 \u0005[להכשירו],\u0006 שכיון שעשה אדם תשובה חזר לכשרותו הראשונה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא\u0004 לרב נחמן: \u0003דילמא איערומי קא מערים\u0004 \u0005[להערים הוא שמערים]\u0006 משום שרצה שיחזירוהו לתפקידו הקודם ולא חזר באמת בתשובה.","שאלו רב נחמן: ו\u0003אלא מאי תקנתיה\u0004 \u0005[מה\u0006 תהא \u0005תקנתו]\u0006 להוכיח שחוזר בתשובה גמורה? ומשיבים: אין דרך אלא כפי שאמר \u0003רב אידי בר אבין.\u0004 ש\u0003אמר רב אידי בר אבין: החשוד על הטריפות\u0004 שמא מכר טריפות לאחרים, \u0003אין לו תקנה\u0004 להכשירו \u0003עד שילך למקום שאין מכירים אותו ויחזיר אבידה\u0004 שמצא \u0003בדבר חשוב,\u0004 שרואים שחזר בו ומוכן לוותר על הממון משום מצוה, \u0003או שיוציא טריפה מתחת ידו בדבר חשוב משלו,\u0004 שמוכן להפסיד דמיה ובכך מראה שאינו מערים, אבל במקום שמכירים אותו אין לסמוך, שכן שמא הוא מערים כדי להראות שחזר בתשובה.","עוד שנינו במשנה ש\u0003מפריחי יונים\u0004 אף הם פסולים לעדות. ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 הם\u0005]\u0006 \u0003\"מפריחי יונים\"? הכא תרגומה\u0004 \u0005[כאן תרגמו,\u0006 הסבירו\u0005]\u0006 זאת שהוא עושה מירוצי יונים \u0003אי תקדמיה יונך ליון\u0004 \u0005[אם תקדים יונתך את יונתי].\u0006 \u0003ר' חמא בר אושעיא\u0004 \u0003אמר: ארא\u0004 (שמלמד את יוניו לצוד ולהביא יונים משל אחרים).","ושואלים: \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר\u0004 שההסבר הוא \u0003אי תקדמיה יונך ליון\u0004 \u0005[אם תקדים יונתך ליוני],\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא\u0004 \u0003אמר ארא?\u0004","\u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך: ארא\u0004 — \u0003מפני דרכי שלום בעלמא\u0004 \u0005[בלבד]\u0006 הוא, ואינה גזל ממש, שאין לו לבעל היונים ביוניו בעלות גמורה, שהיונים גדלות מאליהן בביתו\u0005.\u0006","\u0003ומאן\u0004 \u0005[ומי]\u0006 ש\u0003אמר ארא מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא\u0004 \u0003אמר\u0004 שההסבר הוא \u0003אי תקדמיה יונך ליון\u0004 \u0005[אם תקדים יונתך ליוני]?\u0006 \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך:\u0004 בכך אין חידוש כי \u0003היינו\u0004 \u0005[זהו]\u0006 אותו דבר כ\u0003משחק בקוביא,\u0004 כלומר, זהו אותו פסול של כל משחקי המזל.","\u0003ואידך\u0004 \u0005[והאחר]\u0006 מה עונה הוא על קושי זה?","— לדעתו יש לחלק ולומר כי \u0003תנא\u0004 \u0005[שנה]\u0006 גם \u0003תולה בדעת עצמו\u0004 כשמשחק בעצמו בקוביא וסבור שירוויח \u0003ותנא תולה בדעת יונו.\u0004","ומסבירים: \u0003וצריכא\u0004 \u0005[ונצרכו\u0006 שניהם\u0005]\u0006 להיאמר. כיצד? — \u0003דאי תנא\u0004 \u0005[שאם\u0006 היה \u0005שונה]\u0006 \u0003תולה בדעת עצמו,\u0004 היינו אומרים: \u0003התם\u0004 \u0005[שם]\u0006 \u0003הוא דלא גמר ומקני\u0004 \u0005[שאינו גומר ומקנה]\u0006 ומשחק עמו ש\u0003אמר\u0004 \u0005[שאומר\u0006 בלבו\u0005]\u0006"],["\u0003\"קים לי בנפשאי דידענא טפי\"\u0004 \u0005[מובטח אני בעצמי שאני יודע יותר]\u0006 את דרכי וכללי המשחק, ואנצח בו. \u0003אבל תולה בדעת יונו אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא,\u0004 שהרי אינו יכול להבטיח את התוצאות.","ולהיפך, \u0003ואי תנא\u0004 \u0005[ואילו שנה]\u0006 רק \u0003תולה בדעת יונו\u0004 היינו אומרים ש\u0003אמר בנקשא תליא מילתא\u0004 \u0005[בנקישה תלוי הדבר],\u0006 שהיו מקישים על עצים וכיוצא בהם, לזרז את היונים, \u0003ואנא ידענא לנקושי טפי\u0004 \u0005[ואני יודע לנקש טוב יותר]\u0006 \u0003אבל\u0004 \u0003תולה בדעת עצמו אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא,\u0004 שוודאי ענין של מזל הוא, ואינו יודע אם ירויח, על כן \u0003צריכא\u0004 \u0005[נצרכה]\u0006 לומר בשני המקרים.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו: \u0003המשחק בקוביא\u0004 — \u0003אלו הן המשחקים בפיספסים\u0004 שהם קוביות של שיש וכיוצא בהן. \u0003ולא בפיספסים בלבד אמרו\u0004 שהמשחק בהם פסול לעדות, \u0003אלא אפילו\u0004 משחק ב\u0003קליפי אגוזים וקליפי רמונים\u0004 פוסל.","\u0003ואימתי חזרתן\u0004 שיחשבו שחזרו בתשובה? — \u0003משישברו את פיספסיהן ויחזרו בהן חזרה גמורה,\u0004 ומהי חזרה גמורה — ש\u0003אפילו בחנם,\u0004 למשחק בלבד בלא להרוויח כספים, \u0003לא עבדי\u0004 \u0005[אינם עושים,\u0006 משחקים\u0005].\u0006","\u0003מלוה בריבית, אחד המלוה ואחד הלוה\u0004 פסולים, \u0003ואימתי חזרתן?\u0004 — \u0003משיקרעו את שטריהן ויחזרו בהן חזרה גמורה\u0004 עד כדי כך ש\u0003אפילו לגוי\u0004 הם \u0003לא מוזפי\u0004 \u0005[מלווים\u0006 עוד\u0005]\u0006 בריבית, שבכך יעזבו לגמרי מקצוע זה.","\u0003ומפריחי יונים\u0004 — \u0003אלו שממרין את היונים,\u0004 שמאמנים אותן לתחרויות. \u0003ולא\u0004 ב\u0003יונים בלבד אמרו אלא אפילו\u0004 בשאר \u0003בהמה חיה ועוף\u0004 אמרו. \u0003ואימתי חזרתן\u0004 בתשובה? — \u0003משישברו את פגמיהן\u0004 שעליהם מעמידים את בעלי החיים המתחרים, \u0003ויחזרו בהן חזרה גמורה\u0004 ש\u0003אפילו במדבר\u0004 במקום שאין בני אדם \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003לא עבדי\u0004 \u0005[יעשו\u0006 כן\u0005].\u0006","\u0003סוחרי שביעית אלו\u0004 הם \u0003שנושאין ונותנין בפירות שביעית. ואימתי חזרתן\u0004 בתשובה? — \u0003משתגיע שביעית אחרת ויבדלו\u0004 מפירות שביעית.","\u0003ואמר ר' נחמיה: לא חזרת דברים בלבד אמרו\u0004 שיהא די לאדם לומר \"חוזר אני בי ממה שעשיתי\" \u0003אלא חזרת ממון. כיצד?\u0004 — \u0003אומר\u0004 החוזר בתשובה: \u0003אני פלוני בר פלוני כינסתי\u0004 והרווחתי \u0003מאתים זוז בפירות שביעית\u0004 בשנה מסויימת, \u0003והרי הן נתונין\u0004 כעת \u0003במתנה לעניים,\u0004 שהרי לא כדין הרוחתי אותם.","ולענייננו \u0003קתני מיהת\u0004 \u0005[שנינו על כל פנים]\u0006 לענין מפריחי יונים גם\u0003 בהמה\u0004. \u0003בשלמא למאן\u0004 \u0005[ל\u0006שיטת \u0005מי]\u0006 ש\u0003אמר\u0004 שמדובר כאן במירוץ \u0003אי תקדמיה יונך ליון\u0004 — \u0003היינו דמשכחת לה\u0004 \u0005[זהו שאתה יכול למצוא\u0006 אפשרות \u0005כזו]\u0006 ב\u0003בהמה\u0004 שעשה תחרות בין בהמות. \u0003אלא למאן\u0004 \u0005[ל\u0006שיטת \u0005מי]\u0006 ש\u0003אמר\u0004 \u0003ארא,\u0004 וכי \u0003בהמה בת הכי\u0004 \u0005[\u0006אפשרות \u0005כזו]\u0006 \u0003היא,\u0004 האם היא מסוגלת לפתות בהמות אחרות?","ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 וכאן מדובר \u0003ב\u0004פיתוי \u0003שור הבר\u0004 שאינו בהמת בית גמורה, ועשויים לפתותו, לעבור לבית אחר. \u0003וכמאן\u0004 \u0005[וכ\u0006שיטת \u0005מי]\u0006 ש\u0003אמר\u0004 \u0003שור הבר\u0004 — \u0003מין בהמה הוא.\u0004 שבאותו נושא היתה מחלוקת: \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 שיש מי שאומר ש\u0003שור הבר\u0004 — \u0003מין בהמה הוא, ור' יוסי אומר:\u0004 אינו אלא \u0003מין חיה.\u0004","\u0003תנא\u0004 \u0005[שנה]\u0006 החכם בתוספתא: \u0003הוסיפו עליהן,\u0004 על הפסולים הללו את \u0003הגזלנין והחמסנין.\u0004","ותוהים: \u0003גזלן\u0004 מה מקום יש להוסיפו לרשימה זו הלא \u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003הוא\u0004 פסול! ומשיבים: \u0003לא נצרכא\u0004 \u0005[נצרכה]\u0006 \u0003אלא ל\u0004גוזל \u0003מציאת חרש שוטה וקטן,\u0004 שמן התורה, כיון שאין להם דעת, אין להם גם זכיה, ואם גזל מהם איננו נחשב כעבריין מן התורה.","\u0003מעיקרא סבור\u0004 \u0005[מתחילה סברו]\u0006 כי \u0003מציאת חרש שוטה וקטן\u0004 \u0003לא שכיחא\u0004 \u0005[אינה מצויה]\u0006 ולכן אין לפסול מאדם שפעם אירע שגזל מהם. \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 הטעם שמשאירים את מציאתם של אלה בידם הוא \u0003מפני דרכי שלום בעלמא\u0004 \u0005[בלבד]\u0006 ואין בכך פסול גזילה. \u0003כיון דחזו\u0004 \u0005[שראו]\u0006 ש\u0003סוף סוף ממונא\u0004 \u0005[ממון]\u0006 \u0003הוא דקא שקלי\u0004 \u0005[שהם לוקחים\u0006 וחוטפים\u0005]\u0006 ומגיעים לידי גזלנות ממש — על כן \u0003פסלינהו רבנן\u0004 \u0005[פסלום חכמים].\u0006","וכן לגבי \u0003החמסנין,\u0004 שהם אנשים הכופים אחרים למכור להם. \u0003מעיקרא סבור\u0004 \u0005[מתחילה סברו]\u0006 כי כיון ש\u0003דמי קא יהיב\u0004 \u0005[כסף הם נותנים]\u0006 הרי \u0003אקראי בעלמא\u0004 \u0005[מקרה בלבד]\u0006 \u0003הוא,\u0004 שהם מכריחים למכור להם ואין לפוסלם משום כך. \u0003כיון דחזו דקא חטפי\u0004 \u0005[שראו שהם חוטפים]\u0006 בקביעות \u0003גזרו בהו רבנן\u0004 \u0005[בהם חכמים]\u0006 לפוסלם.","\u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003עוד הוסיפו עליהן,\u0004 על הפסולים לעדות אף את \u0003הרועים,\u0004 שרועים את בהמותיהם בשדות אחרים והם כגזלנים, וכן את \u0003הגבאין\u0004 שגובים את מיסי המלכות ולוקחים יותר מן הקצוב לפי החוק, \u0003ו\u0004את \u0003המוכסין\u0004 הנוטלים מכס מעוברי דרכים שלא כדין.","ומסבירים: \u0003רועים, מעיקרא סבור אקראי בעלמא\u0004 \u0005[מתחילה סברו\u0006 ש\u0005מקרה בלבד]\u0006 \u0003הוא\u0004 שהבהמות רועות בשדות אחרים, \u0003כיון דחזו דקא מכווני ושדו\u0004 \u0005[שראו שהם מתכוונים ומשלחים]\u0006 בכוונה את הבהמות \u0003לכתחילה\u0004 לשדות זרים — \u0003גזרו בהו רבנן\u0004 \u0005[בהם חכמים]\u0006 לפוסלם. וכן \u0003הגבאין והמוכסין, מעיקרא סבור\u0004 \u0005[מתחילה סברו]\u0006 כי \u0003מאי דקיץ להו קא שקלי\u0004 \u0005[מה שקבוע להם הם נוטלים]\u0006 וממלאים שליחותם. \u0003כיון דחזו דקא שקלי יתירא\u0004 \u0005[שראו שהם נוטלים יותר]\u0006 — \u0003פסלינהו\u0004 \u0005[פסלום].\u0006","\u0003אמר רבא: רועה שאמרו\u0004 שהוא פסול לעדות — \u0003אחד רועה בהמה דקה ואחד רועה בהמה גסה.\u0004","ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר רבא הכי\u0004 \u0005[כן]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבא: רועה בהמה דקה בארץ ישראל\u0004 הם \u0003פסולין\u0004 לעדות, שנוסף לגזלנות הם גם גורמים להשחית את הארץ, \u0003בחוצה לארץ\u0004 — \u0003כשרין\u0004 . ואילו \u0003רועה בהמה גסה\u0004 — \u0003אפילו בארץ ישראל כשרים\u0004. ומשיבים: \u0003ההוא במגדלים.\u0004 מה שנאמר בפסילת רועים הרי זה באלה שמגדלים את בהמותיהם שלהם, והם הנהנים מכך ואינם רועים בלבד.","ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 לומר, ממה ששנינו: \u0003נאמנין עלי שלשה רועי בקר, מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה שנאמנים \u0003לעדות,\u0004 משמע שרועים אלה פסולים בדרך כלל!","ודוחים: \u0003לא,\u0004 הכוונה היא \u0003לדינא\u0004 \u0005[ל\u0006היות \u0005דיינים],\u0006 ומוסיפים: \u0003דיקא נמי\u0004 \u0005[מדוייק גם כן]\u0006 הסבר זה מעיון בנושא, ששנינו: \u0003שלשה רועי בקר, ואי\u0004 \u0005[ואם]\u0006 הכוונה \u0003לעדות\u0004 אם כן \u0003שלשה למה לי?\u0004 הרי די בשנים!","ומקשים: \u0003ואלא מאי\u0004 \u0005[מה]\u0006 \u0003לדינא\u0004 \u0005[ל\u0006ענין \u0005דין],\u0006 \u0003מאי איריא\u0004 \u0005[מה שייך],\u0006 מדוע דווקא \u0003שלשה רועי בקר? כל בי תלתא\u0004 \u0005[שלושה]\u0006 ש\u0003לא גמרי דינא נמי\u0004 \u0005[למדו דינים גם כן\u0006 כך\u0005]\u0006 ומה איפוא החידוש ברועי בקר?","ומסבירים: \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003אפילו הני\u0004 \u0005[אלה]\u0006 רועי הבקר שהם \u0003לא שכיחי\u0004 \u0005[מצויים]\u0006 \u0003ביישוב,\u0004 שעיקר זמנם מצויים הם בשדות שמחוץ לערים ואינם בקיאים יפה בטיב משא ומתן, בכל זאת יכול לקבל אותם כדיינים.","\u0003אמר רב יהודה: סתם רועה פסול\u0004 עד שנדע בו שהוא מן הרועים הכשרים. \u0003סתם גבאי\u0004 של מיסים — \u0003כשר\u0004 עד שנדע בו שנוטל יתר על הדרוש.","ומסופר על גבאי כשר כגון זה: \u0003אבוה\u0004 \u0005[אביו]\u0006 של \u0003ר' זירא עבד גביותא תליסר שנין\u0004 \u0005[היה עושה גביה\u0006 של מיסים \u0005שלש עשרה שנים].\u0006 \u0003כי הוה אתי ריש נהרא למתא\u0004 \u0005[כאשר היה בא ראש הנהר,\u0006 הממונה על גבית המיסים מאותו אזור, \u0005לעיר]\u0006 \u0003כי הוה חזי רבנן\u0004 \u0005[כשהיה רואה\u0006 הגבאי את \u0005החכמים]\u0006 אמר להם ברמז: \u0003\"לך עמי בא בחדריך\u0004 וסגור דלתיך בעדך חבי כמעט רגע עד יעבור זעם\u0003\"\u0004 (ישעיה כו, כ), כדי שלא יראה אותם השר, ואפשר יהיה למעט במסי העיר. \u0003כי הוה חזי אינשי דמתא\u0004 \u0005[כאשר היה רואה את אנשי העיר]\u0006 סתם, היה אומר להם: \u0003ריש נהרא אתא למתא, והאידנא נכיס אבא לפום ברא וברא לפום אבא\u0004 \u0005[ראש הנהר בא לעיר, ועכשיו ישחט\u0006 את \u0005האב על פי הבן והבן לפי האב]\u0006 ודעו מה שתעשו"]]};
